@app.route('/api/get-fuel-properties', methods=['POST'])
def get_fuel_properties():
    try:
        data = request.json
        fuel_type = data.get('fuel_type', 'htpb')
        # V3 SG-1 F-06: metin olmayan ``fuel_type`` ``.upper()``'da
        # düşüyor ve 500 'NASA CEA Database Error' (yanlış suçlu) dönüyordu.
        _fp_tip = _field_types.field_type_error('fuel_type', fuel_type,
                                                'string')
        if _fp_tip is not None:
            return jsonify(_fp_tip[0]), _fp_tip[1]
        # ÖH D23 a2 / P13B4-12: dört düşman değerin DÖRDÜ de HTTP 200
        # dönüyordu ve günlükte "FETCHING NASA CEA DATA: htpb at
        # yirmiK" satırı vardı — sıcaklık hiç sayı olmadan aşağı
        # iniyordu.
        try:
            temperature = input_guard.num(data, 'temperature',
                                          default=298.15, unit='K')
        except input_guard.InputError as _ig_exc:
            # ÖH D23 a2 / P13B4-12: bu ucun genel dalı
            # ``except Exception -> 500``. Alan düzeyinde bir İSTEMCİ
            # hatası SUNUCU arızası gibi yayımlanamaz; kapı kendi
            # 422'sini alan adıyla verir (fail-closed, sayı uydurulmaz).
            return jsonify({
                'status': 'error',
                'error': 'invalid_input',
                'message': str(_ig_exc),
                'invalid_fields': [{
                    'field': 'temperature',
                    'reason': _kanonik_gerekce(data.get('temperature'),
                                               sayi_ise='out_of_range')}],
            }), 422
        
        print(f"FETCHING NASA CEA DATA: {fuel_type} at {temperature}K")
        
        # Get fuel properties from chemical database
        fuel_mapping = {
            'rp1': 'RP1',
            'lh2': 'H2', 
            'methane': 'CH4',
            'mmh': 'MMH',
            'udmh': 'UDMH',
            'htpb': 'HTPB',
            'paraffin': 'Paraffin'
        }
        
        species_name = fuel_mapping.get(fuel_type, fuel_type.upper())
        species = chemical_db.get_species(species_name)
        
        if species:
            # Calculate properties at requested temperature
            cp = chemical_db.calculate_cp(species_name, temperature)
            enthalpy = chemical_db.calculate_enthalpy(species_name, temperature)
            entropy = chemical_db.calculate_entropy(species_name, temperature)

            # --- ÖH Z5S / S6 EK MADDE (P9B4-12 / OH-Z5-04) ---------------
            # ÖLÇÜLDÜ (taban df67bce): ``fuel_type = 'htpb'`` ve
            # ``'paraffin'`` bu uçta HTTP **500** veriyor, gövde de ham
            # Python metniydi:
            # ``"unsupported operand type(s) for /: 'NoneType' and 'int'"``.
            # Kök: ``calculate_cp`` KAZANILMAMIŞ katsayılarda (yer tutucu
            # sıfırlar / eksik katsayı) bilerek ``None`` dönüyor — bu
            # fail-closed davranış DOĞRU — ama uç dönen ``None``ı 1000'e
            # bölmeye çalışıyordu. Yani veritabanının dürüstlüğü ucu
            # çökertiyordu: ürünün varsayılan yakıtı (HTPB) sorulamıyordu.
            #
            # Sayı UYDURULMAZ: alan ``null`` kalır ve NEDENİ
            # ``chemical_db.species_data_status`` künyesinden ADIYLA
            # yayımlanır (``unavailable_reason``).
            veri_kunyesi = chemical_db.species_data_status(species_name)

            def _kJ(deger):
                """J -> kJ; hesaplanamayan büyüklükte ``None`` (uydurma yok)."""
                if deger is None:
                    return None
                try:
                    return float(deger) / 1000.0
                except (TypeError, ValueError):
                    return None

            properties = {
                # --- ÖH D26 / app-api a4 · P7B4-01 -------------------
                # ÖLÇÜLDÜ (``a4/once.json`` K7): bu alan
                # ``molecular_weight * 10`` (sıvı) ya da ham
                # ``molecular_weight`` (gaz) basıyordu ve gövde onu
                # ``source = 'NASA CEA Database'`` + ``real_time = True``
                # künyesiyle yayımlıyordu. Ölçülen dört sayı:
                # LH2 2,016 (gerçek 70,85 -> 35,1 kat KÜÇÜK),
                # HTPB 54,09 (920 -> 17,0 kat), metan 16,043 (422,6 ->
                # 26,3 kat), RP-1 1673,1 (810 -> 2,07 kat BÜYÜK).
                # Molekül ağırlığı yoğunluk DEĞİLDİR (g/mol ⟷ kg/m³);
                # NASA-CEA kaydında yoğunluk YOKTUR. Sayı artık deponun
                # KENDİ ölçülü önbellek kaydından okunur; kayıt yoksa alan
                # ``null`` kalır ve nedeni adıyla yayımlanır (fail-closed).
                'density': _fuel_density_from_record(fuel_type),
                'enthalpy_formation': _kJ(species.enthalpy_formation),  # kJ/mol
                'formula': species.formula,
                'phase': species.phase,
                'cp': _kJ(cp),  # kJ/mol/K
                'enthalpy': _kJ(enthalpy),
                'entropy': _kJ(entropy),
                # ÖH D26 a4 / P7B4-01: yoğunluğun KÖKENİ adıyla; kayıt
                # yoksa alan null ve nedeni burada (sayı uydurulmaz).
                'density_source': _fuel_density_kunyesi(fuel_type)[0],
                'density_unavailable_reason': _fuel_density_kunyesi(
                    fuel_type)[1],
                'density_basis': FUEL_DENSITY_UNAVAILABLE_BASIS,
                'density_unit': 'kg/m^3',
                # ÖH D21 / P15B1-05 — kardeş uçla (``/api/chemical-species``)
                # AYNI ÜÇ AD, 1000 kat farklı birim. Birim artık gövdede.
                'units': dict(_TERMO_BIRIMLERI_KJ),
                'source': species.source,
                'molecular_weight': species.molecular_weight,
                'temperature': temperature,
                'timestamp': datetime.now().isoformat()
            }
            # Hangi büyüklüğün NEDEN basılamadığı: boş alan sessiz kalmaz.
            hesaplanamayan = [ad for ad in ('cp', 'enthalpy', 'entropy')
                              if properties[ad] is None]
            if hesaplanamayan:
                properties['unavailable_fields'] = hesaplanamayan
                properties['unavailable_reason'] = veri_kunyesi.get(
                    'unavailable_reason')
                properties['unavailable_basis'] = (
                    'The NASA-polynomial coefficients for this species are '
                    'not usable in HRMA, so cp / enthalpy / entropy were NOT '
                    'computed. A placeholder number would have looked like a '
                    'measurement; the field is left null instead. '
                    'coefficient_count and the reason code below say what is '
                    'missing.')
            properties['data_status'] = veri_kunyesi

            print(f"NASA CEA RESPONSE: {species_name} - MW: {species.molecular_weight}, dHf: {species.enthalpy_formation}")

            # --- ÖH D26 a4 / P7B4-01 · KÜNYE ÇELİŞKİSİ -----------------
            # ÖLÇÜLDÜ (``a4/once.json`` K7): üst düzey ``source`` HER
            # yanıtta ``'NASA CEA Database'`` yazıyordu, oysa AYNI gövdede
            # ``properties.source`` htpb ve rp1 için ``'Custom'`` idi —
            # tek yanıtta iki çelişen köken künyesi. Üst düzey künye artık
            # türün KENDİ kaydından türetilir; ``'Custom'`` bir NASA CEA
            # kaydı DEĞİLDİR ve öyle ilan edilmez.
            _tur_kaynagi = str(species.source or '')
            _nasa_kaydi = _tur_kaynagi.upper().startswith('NASA')
            return jsonify({
                # ÖH D26 a3 / OH-D25-17: öksüzlük beyanı.
                'surface_note': OKSUZ_UC_BEYANI,
                'status': 'success',
                'properties': sanitize_json_values(properties),
                'source': ('NASA CEA Database' if _nasa_kaydi
                           else 'HRMA species record (%s) - NOT NASA CEA'
                                % (_tur_kaynagi or 'unlabelled')),
                'species_source': _tur_kaynagi,
                # Katsayılar kazanılmamışsa yanıt "gerçek zamanlı hesap"
                # DEĞİLDİR; bayrak hesabın gerçekten koştuğunu söyler.
                'real_time': not hesaplanamayan,
            })
        else:
            print(f"Species not found: {species_name}, trying fallback...")

            # --- ÖH D27 / app-api a3 (P7B4-02) · İKAME KALKTI ----------
            # ÖLÇÜLDÜ (``a3/once.json`` K2, worktree ``a67dd68``):
            # ``fuel_type='ethanol'`` ve ``'peynir'`` HTTP **200** +
            # ``status='success'`` + ``density 810,0 kg/m³`` +
            # ``formula 'C12H23'`` alıyordu — yani RP-1'in kaydı. D26 a4
            # bu ikameyi ADIYLA beyan ettirmişti (``substituted_record``,
            # ``substituted_basis``, üst düzey ``note``) ve o beyan
            # ölçülerek doğrulandı; ama Doktrin 1 açıktır: BEYAN ÇÖZÜM
            # DEĞİLDİR. ``status='success'`` diyen bir gövdede etanolün
            # yoğunluğu diye RP-1'in yoğunluğu duruyorsa, künye o sayıyı
            # doğru yapmaz — yalnız yanlışın üstüne bir cümle yazar.
            #
            # Fail-closed: eşleşen kayıt YOKSA sayı YAYIMLANMAZ. Reddin
            # gövdesi alanı adıyla anar ve bu ürünün GERÇEKTEN kaydı olan
            # yakıtları listeler, böylece kullanıcı ne isteyebileceğini
            # yanıttan öğrenir (sayı uydurulmaz, liste tek kaynaktan
            # okunur: ``CACHED_FUEL_PROPERTIES``).
            #
            # MEŞRU YOL DARALMAZ (ÖK-22): tabloda KENDİ kaydı olan bir
            # yakıt NASA-CEA türünde bulunamasa bile 200 alır ve kendi
            # önbellek kaydını yayımlar — ikame olmadığı için gövdesinde
            # ``substituted_record`` da yoktur.
            _onbellek_adi = str(fuel_type).lower()
            if _onbellek_adi not in CACHED_FUEL_PROPERTIES:
                return jsonify({
                    'status': 'error',
                    'error': 'unknown_fuel',
                    'message': (
                        'HRMA has no species record and no cached propellant '
                        "record for fuel_type '%s'. Nothing was "
                        'substituted: earlier versions answered this request '
                        'with another propellant record under '
                        'status=success, so the numbers described that other '
                        'propellant and not the fuel that was asked for. Ask '
                        'for one of the fuels listed in '
                        'accepted_fuel_types, or add the record with its '
                        'source.'
                        % _clip_echo(str(fuel_type))),
                    'invalid_fields': [{
                        'field': 'fuel_type',
                        'value': _clip_echo(str(fuel_type)),
                        'reason': 'no_species_or_cached_record',
                    }],
                    'accepted_fuel_types': sorted(CACHED_FUEL_PROPERTIES),
                }), 422

            fallback_props = get_cached_fuel_properties(fuel_type, temperature)
            
            return jsonify({
                # ÖH D26 a3 / OH-D25-17: öksüzlük beyanı.
                'surface_note': OKSUZ_UC_BEYANI,
                'status': 'success',
                'properties': sanitize_json_values(fallback_props),
                'source': 'Cached Database',
                # Faz 5B / H3-B13: ``species_name`` doğrudan kullanıcı
                # girdisidir. 100 000 karakterlik bir ``fuel_type`` ile bu
                # not 100 049 karakter oluyordu (ölçüldü, HTTP 200 — yani
                # ``_clip_error_body`` kapsamı DIŞINDA). Yankı kaynağında
                # kırpılır ve kırpma açıkça beyan edilir.
                # ÖH D26 a4 / P7B4-02: not YALNIZ "bulunamadı" diyordu;
                # ÖLÇÜLDÜ (``a4/once.json`` K8): ``ethanol`` ve ``peynir``
                # HTTP 200 + ``density 810,0`` + ``formula 'C12H23'`` (RP-1)
                # alıyordu ve bu tek satırlık not YERİNE NE KONDUĞUNU
                # söylemiyordu — kullanıcı üst düzeyde yalnız "cached data"
                # görüyordu. İkame edilen kaydın adı artık NOTUN KENDİSİNDE.
                'note': ('Species '
                         + _clip_echo(species_name)
                         + ' not found in NASA CEA, using cached data'
                         + ((" from the '%s' record - those numbers "
                             'describe %s, NOT the fuel you asked for'
                             % (fallback_props['cached_record'],
                                fallback_props['cached_record']))
                            if fallback_props.get('substituted_record')
                            else ''))
            })
            
    except Exception as e:
        print(f"NASA CEA ERROR: {str(e)}")
        return jsonify({
            'status': 'error', 
            'error': f'NASA CEA Database Error: {str(e)}'
        }), 500


#: ÖH D26 / app-api a4 (P7B4-01) — YAKIT ÖNBELLEK KAYDI TEK KAYNAKTA.
#: Bu sözlük eskiden ``get_cached_fuel_properties`` GÖVDESİNDE yerel bir
#: değişkendi, yani ``/api/get-fuel-properties``in NASA-CEA dalı ona
#: erişemiyordu ve orada yoğunluk MOLEKÜL AĞIRLIĞINDAN uyduruluyordu
#: (ölçüldü, ``a4/once.json`` K7: LH2 2,016 · HTPB 54,09 · metan 16,043 ·
#: RP-1 1673,1 kg/m³ — gerçekleri 70,85 · 920 · 422,6 · 810). Kayıt artık
#: modül düzeyinde tek kaynaktır; iki dal da BURADAN okur (ÖK-04).
#:
#: ÖH D27 / app-api a3 (OH-D26-17) — HER KAYIT KÜNYELİ. ÖLÇÜLDÜ
#: (``a3/once.json`` K2): ``fuel_type='htpb'`` — ürünün KENDİ varsayılan
#: hibrit yakıtı — ``density: null`` +
#: ``density_unavailable_reason='no_measured_density_record_for_this_fuel'``
#: alıyordu, çünkü tabloda üç kayıt vardı ve HTPB onlardan biri değildi.
#: Kaydın eklenmesi bir SAYI İCADI DEĞİLDİR: değer literatürden alınır ve
#: ``density_reference`` alanında KAYNAK KÜNYESİYLE birlikte durur.
#: Künyesiz kayıt YOKTUR — üç eski kaydın künyesi de aynı hamlede yazıldı,
#: böylece "kaynağı yazılmamış yoğunluk" hâli yapısal olarak imkânsız
#: (bekçi: ``tests/test_d27_app_api_a3.py::TestOHD2617KunyeliKayit``).
CACHED_FUEL_PROPERTIES = {
    'rp1': {
        'density': 810.0,
        'enthalpy_formation': -194.2,  # kJ/mol
        'formula': 'C12H23',
        'phase': 'liquid',
        'heating_value': 43000,  # kJ/kg
        'density_reference': (
            'Sutton & Biblarz, Rocket Propulsion Elements, 9th ed., '
            'Table 7-1: RP-1 liquid density 0.81 g/cm^3 at 289 K'),
        'density_temperature_K': 289.0,
    },
    'lh2': {
        'density': 71.0,
        'enthalpy_formation': 0.0,
        'formula': 'H2',
        'phase': 'liquid',
        'heating_value': 120000,
        'density_reference': (
            'Sutton & Biblarz, Rocket Propulsion Elements, 9th ed., '
            'Table 7-1: liquid hydrogen 0.071 g/cm^3 at its normal '
            'boiling point 20.4 K'),
        'density_temperature_K': 20.4,
    },
    'methane': {
        'density': 423.0,
        'enthalpy_formation': -74.6,
        'formula': 'CH4',
        'phase': 'liquid',
        'heating_value': 50000,
        'density_reference': (
            'NIST Chemistry WebBook / Setzmann & Wagner (1991) reference '
            'equation of state: saturated liquid methane 422.6 kg/m^3 at '
            'its normal boiling point 111.7 K'),
        'density_temperature_K': 111.7,
    },
    # ÖH D27 a3 / OH-D26-17 — ÜRÜNÜN VARSAYILAN HİBRİT YAKITI.
    # HTPB bir POLİMER BAĞLAYICIDIR: yoğunluğu sıcaklığın değil kürlenmiş
    # reçetenin (bağlayıcı/kürleyici/plastikleştirici oranı) fonksiyonudur
    # ve literatür 920 kg/m^3'ü kürlenmiş saf bağlayıcı için verir. Bu
    # yüzden ``density_temperature_K`` bilerek None: sayı bir doyma
    # eğrisinden değil, katı bir malzeme kaydından gelir.
    'htpb': {
        'density': 920.0,
        'enthalpy_formation': -51.9,  # kJ/mol (C7.337 H10.982 O0.058 esas)
        'formula': 'C4H6',
        'phase': 'solid',
        'heating_value': 42000,
        'density_reference': (
            'Chiaverini & Kuo (eds.), Fundamentals of Hybrid Rocket '
            'Combustion and Propulsion, AIAA Progress in Astronautics and '
            'Aeronautics Vol. 218 (2007), Ch. 2: cured HTPB binder '
            '920 kg/m^3; consistent with Sutton & Biblarz, Rocket '
            'Propulsion Elements, 9th ed., Ch. 15 (HTPB binder)'),
        'density_temperature_K': None,
    },
}

#: Yoğunluk kaydı KÜNYESİZ olamaz (OH-D26-17). Bu küme, her kaydın taşımak
#: ZORUNDA olduğu alanlardır; bekçi tabloyu bu kümeye karşı sınar.
CACHED_FUEL_REQUIRED_KEYS = frozenset({
    'density', 'enthalpy_formation', 'formula', 'phase', 'heating_value',
    'density_reference', 'density_temperature_K'})

#: Yoğunluğun NEDEN yayımlanamadığını söyleyen tek cümle (P7B4-01).
FUEL_DENSITY_UNAVAILABLE_BASIS = (
    'Density is NOT a NASA CEA quantity: the CEA record carries the '
    'molecular weight and the NASA polynomial coefficients, not a '
    'condensed-phase density. HRMA used to publish the molecular weight '
    '(x10 for liquids) in this field, which is a different physical '
    'quantity with different units and was wrong by factors of 2 to 35. '
    'The field is left null instead of carrying a fabricated number; '
    'density_source names the record when HRMA has a measured one.')


def _fuel_density_from_record(fuel_type):
    """Yakıt yoğunluğu [kg/m³] — YALNIZ deponun ölçülü kaydından.

    ÖH D26 / app-api a4 (P7B4-01). Kayıt yoksa ``None`` döner: molekül
    ağırlığından yoğunluk TÜRETİLMEZ (farklı büyüklük, farklı birim).
    """
    kayit = CACHED_FUEL_PROPERTIES.get(str(fuel_type).lower())
    if not kayit:
        return None
    return kayit['density']


def _fuel_density_kunyesi(fuel_type):
    """``(density_source, density_unavailable_reason)`` çifti.

    ÖH D27 a3 / OH-D26-17: kaynak künyesi artık KAYDIN KENDİSİNDEN okunur
    (``density_reference``). İki yerde yazılmadığı için "yayımlanan künye"
    ile "kaydın dayandığı kaynak" ayrışamaz (Doktrin 4).
    """
    ad = str(fuel_type).lower()
    kayit = CACHED_FUEL_PROPERTIES.get(ad)
    if kayit:
        return ("HRMA cached propellant record '%s' (density is not part "
                "of the NASA CEA species record); source: %s"
                % (ad, kayit['density_reference'])), None
    return None, 'no_measured_density_record_for_this_fuel'


def get_cached_fuel_properties(fuel_type, temperature):
    """Get cached fuel properties"""
    cache_data = CACHED_FUEL_PROPERTIES

    # ÖH Z5S / S6: HANGİ kaydın kullanıldığı SÖYLENİR. Ölçüldü (taban
    # df67bce): ``fuel_type = 'peynir'`` HTTP 200 ile RP-1'in yoğunluğunu,
    # formülünü (``C12H23``) ve ısıl değerini basıyordu; yanıttaki tek not
    # "using cached data" idi, yani kullanıcı SORMADIĞI bir yakıtın
    # sayılarını kendi yakıtınınki sanıyordu. Sayılar DEĞİŞMEDİ; eklenen
    # tek şey, ikame edilen kaydın adı ve ikamenin beyanıdır.
    _kayit = fuel_type if fuel_type in cache_data else 'rp1'
    props = cache_data[_kayit].copy()
    props.update({
        'temperature': temperature,
        'source': 'Cached Database',
        'cached_record': _kayit,
        'timestamp': datetime.now().isoformat()
    })
    if _kayit != fuel_type:
        props['substituted_record'] = _kayit
        props['substituted_basis'] = (
            "no cached record matches the requested fuel, so the numbers "
            f"above are the '{_kayit}' record. They describe {_kayit}, NOT "
            "your fuel: treat every value here as a placeholder until the "
            "fuel is added to the database.")
    return props

def get_oxidizer_density(oxidizer_type, temperature):
    """Oksitleyici yoğunluğu [kg/m³] — TEK doğruluk kaynağından.

    Z1 ONARIMI (docs/arastirma/fizik/Z1-yogunluk-dogrulama.md). Eski hâli
    üç çapa ve sabit bir eğimle doğrusal ekstrapolasyon yapıyordu::

        'lox': (1141.0, 90.15, -4.0), 'n2o4': (1443.0, 261.95, -2.8),
        'n2o': (1220.0, 184.67, -2.5)
        return max(10.0, rho_base + drho_dt * (T - t_base))

    Ölçülen dört ayrı kusur:

    * **n2o**: 1220 N₂O'nun NORMAL KAYNAMA NOKTASI değeridir; 293,15 K'ye
      −2,5 kg/(m³·K) ile taşınınca 948,80 çıkıyordu. Bu sayı bağımsız bir
      literatür değeri DEĞİL, 1220'nin ekstrapolasyonudur ve 264,4 K'nin
      gerçeğine denk düşer: sorulan 293,15 K'de **+%20,9** hata (gerçeği
      785,10). Doymuş sıvı yoğunluğu doğrusal değildir — eğim 185 K'de
      −2,93 iken 306 K'de −20,8 kg/(m³·K)'dir (7 kat).
    * **n2o4**: 20 °C değeri (1443) DONMA noktasına (261,95 K) çapalanmıştı
      (kaynama noktası 294,25 K); 293,15 K'de 1355,6 → **−%6,1**.
    * **lox**: 293,15 K sorulunca 329 kg/m³ dönüyordu. LOX 154,58 K'nin
      üstünde SIVI DEĞİLDİR; ``max(10.0, …)`` kapısı yalnız negatifi
      keser, anlamsızlığı geçirir.
    * **h2o2**: tabloda yoktu, sessizce "Default to LOX" dalına düşüyordu.

    Yeni davranış: değer akışkana özgü referans kapısından gelir, sorulan
    sıcaklık uygulanabiliyorsa uygulanır, uygulanamıyorsa künyede beyan
    edilir; çözülemeyen durumda ``OxidizerStateError`` yükselir (fail-closed).

    ÖH D20 / OH-D19-02: skaler kanal artık ``oxidizer_liquid_density``e
    delege eder. Fark tek noktadadır — sorulan sıcaklık akışkanın SIVI
    BANDININ DIŞINDAysa sayı yayımlanmaz (ölçüldü: ``lox @293,15 K`` ->
    1141,0 kg/m³, oysa aynı çağrının künyesi ``state_reason =
    'outside_liquid_band'`` diyordu). ``'not_modelled'`` hâli aynen geçer.
    """
    return oxidizer_liquid_density(oxidizer_type, temperature)


def get_oxidizer_density_report(oxidizer_type, temperature):
    """(ρ, künye) çifti — sayının nereden geldiğini birlikte taşır."""
    veri = oxidizer_reference_density(oxidizer_type, temperature)
    return veri['density'], veri['source']


def get_oxidizer_viscosity(oxidizer_type, temperature):
    """Oksitleyici dinamik viskozitesi [Pa·s] — TEK doğruluk kaynağından.

    Z1: eski tablo akışkan-başına tek sabitti ve N₂O girdisi (2,8e-4 Pa·s)
    293 K gerçeğinin (6,817e-5) **4,1 KATIYDI** — bu sayı N₂O'nun normal
    kaynama noktası viskozitesine (3,07e-4) yakındır, yani 1220 ile AYNI hâl
    hatasıdır. Ayrıca tanınmayan akışkan sessizce LOX'un değerini alıyordu.
    """
    return oxidizer_reference_viscosity(oxidizer_type, temperature)['viscosity']

def get_oxidizer_conductivity(oxidizer_type, temperature):
    """Calculate thermal conductivity"""
    conductivities = {
        'lox': 0.15,
        'n2o4': 0.12,
        'n2o': 0.20
    }
    return conductivities.get(oxidizer_type, 0.15)

def get_cached_oxidizer_properties(oxidizer_type, temperature):
    """Önbellek yolundaki oksitleyici özellikleri.

    Z1: yoğunluk ve viskozite artık burada SABİT tutulmuyor, tek kaynaktan
    çözülüyor; sözlük tembel kurulur (bir akışkanın tanımsız durumu diğer
    akışkanın sorgusunu düşüremesin). Tanınmayan tip artık sessizce LOX'a
    düşmez — eskiden ``cache_data.get(type, cache_data['lox'])`` ile bilinmeyen
    her oksitleyici LOX'un yoğunluğunu alıyordu.
    """
    sabit_kunye = {
        'lox': {'heat_capacity': 1.7, 'thermal_conductivity': 0.15,
                'formula': 'O2', 'boiling_point': 90.19,
                'critical_temperature': 154.581, 'molecular_weight': 31.998},
        'n2o4': {'heat_capacity': 1.4, 'thermal_conductivity': 0.12,
                 'formula': 'N2O4', 'boiling_point': 294.3,
                 'critical_temperature': 431.35, 'molecular_weight': 92.011},
        'n2o': {'heat_capacity': 2.2, 'thermal_conductivity': 0.20,
                'formula': 'N2O', 'boiling_point': 184.67,
                'critical_temperature': 309.52, 'molecular_weight': 44.013},
        'h2o2': {'heat_capacity': 2.6, 'thermal_conductivity': 0.6,
                 'formula': 'H2O2', 'boiling_point': 423.35,
                 'critical_temperature': 730.15, 'molecular_weight': 34.015},
    }
    if oxidizer_type not in sabit_kunye:
        raise OxidizerStateError(
            f"No cached oxidizer record for {oxidizer_type!r}. Known: "
            + ', '.join(sorted(sabit_kunye))
            + ". Supply 'oxidizer_density'/'oxidizer_viscosity' explicitly "
              "instead of inheriting another fluid's values.")

    props = dict(sabit_kunye[oxidizer_type])
    props.update(_oxidizer_state_props(oxidizer_type, temperature))
    props.update({
        'temperature': temperature,
        'source': 'Cached Database',
        'timestamp': datetime.now().isoformat(),
        'note': 'Live NIST data unavailable'
    })
    return props

#: ÖH D27 a4 / P7B4-11 — ``/api/advanced-performance-analysis`` figürlerinin
#: ZORUNLU saydığı alanlar (TEK KAYNAK, "biri-ya-da-öteki" çiftleri hâlinde).
#:
#: ÖLÇÜLDÜ (taban ``8f083ca0``, ``docs/scofield/raw/OH/D27/app-api/a4/
#: once.json`` K1): uç, figür modülünün ZORUNLU saydığı alanlara kendi
#: varsayılanını enjekte ediyordu — ``throat_area=0,001`` m², ``nozzle_length
#: =0,1`` m, ``expansion_ratio=16``, ``burn_time=30`` s, ``chamber_length=0,5``
#: m, ``base_heat_flux=2e6`` W/m², ``critical_heat_flux=4,0`` MW/m². Sonuç::
#:
#:     POST {'analysis_type': 'nozzle_mach'}   -> HTTP 200, 35.255 bayt
#:       alt başlık: "Assumed (not supplied by this call): gamma = 1.20,
#:                    MW = 24 g/mol, Pc = 20 bar, Tc = 3000 K, ..."
#:       aynı başlıkta OLGU olarak: "Ae/At = 16.0"
#:
#: Yani modülün KENDİ dürüstlük kanalı (``_nozzle_fig_motor_data``in
#: ``assumed`` listesi) çalışıyordu, ama uç onu ETKİSİZLEŞTİRİYORDU: gaz hâli
#: "varsayıldı" diye yazılırken, ucun uydurduğu alan oranı ve boğaz alanı
#: figürün ölçülmüş olgusu gibi basılıyordu. ε figürün TÜM Mach alanını,
#: A_t ise tüm ölçeğini belirler — ikisi de "varsayılabilir" bir süs değil,
#: çizilen şeyin kendisidir.
#:
#: Küme İCAT EDİLMEDİ: ``visualization._nozzle_fig_motor_data``in kendi iki
#: ``raise ValueError`` koşulunun ta kendisidir (boğaz geometrisi; alan oranı
#: ya da çıkış çapı). ``burn_time`` ısı akısı şelalesinin ZAMAN EKSENİDİR ve
#: modül onu sessizce 1,0 s'ye düşürüyor — uç artık adıyla sorar.
#:
#: Biçim: analiz türü -> (alternatif alan adları,) demeti.
_APA_REQUIRED_ANY_OF = {
    'nozzle_mach': (('throat_area', 'throat_diameter'),
                    ('expansion_ratio', 'exit_diameter')),
    'heat_flux': (('throat_area', 'throat_diameter'),
                  ('burn_time',)),
}


def _apa_eksik_zorunlu(analysis_type, kaynak):
    """``_APA_REQUIRED_ANY_OF`` kapısı: eksik çiftleri döndürür."""
    eksik = []
    for secenekler in _APA_REQUIRED_ANY_OF.get(analysis_type, ()):
        if not any(kaynak.get(ad) is not None for ad in secenekler):
            eksik.append(list(secenekler))
    return eksik


def _apa_eksik_reddi(analysis_type, eksik):
    """P7B4-11 reddi: sayı uydurulmadı, alan adları yanıtta."""
    return jsonify({
        'status': 'error',
        'error': 'incomplete_figure_input',
        'message': (
            'This figure was not drawn: values that define it were not '
            'supplied and are not assumed on your behalf. The area ratio '
            'sets the whole Mach field, the throat area sets its scale and '
            'the burn time is the waterfall time axis — a figure built from '
            'placeholder numbers would be labelled with them as if they were '
            'measured. Nothing was computed.'),
        'analysis_type': analysis_type,
        'missing_fields': eksik,
        'required_any_of': [list(g) for g in
                            _APA_REQUIRED_ANY_OF.get(analysis_type, ())],
    }), 422


@app.route('/api/advanced-performance-analysis', methods=['POST'])
def advanced_performance_analysis():
    """Generate advanced performance analysis graphs based on NASA standards"""
    analysis_type = None      # P7B4-11 ret dalları bu adı okur
    try:
        data = request.json
        analysis_type = data.get('analysis_type', '3d_surface')
        
        if analysis_type == '3d_surface':
            # Chamber Pressure vs Mixture Ratio vs Isp (NASA SP-125)
            # v2.5.2 (Codex bulgusu): yakıt/oksitleyici KİMLİĞİ bu sözlüğe
            # konmuyordu, bu yüzden LOX/RP-1 koşusunda bile denge yüzeyi
            # _resolve_surface_propellant'ın HTPB/N2O referans çiftiyle
            # çözülüyordu. Kimlik ve tarama aralıkları artık aktarılır;
            # verilmezse görselleştirme "referans çift" uyarısını basar.
            # P8B4-16 (ÖH D15 / fea-viz a2): tasarım noktasının ÜÇ sayısı
            # burada 300 / 3,5 / 50 diye UYDURULUYORDU. Ölçüldü: yalnız
            # itici kimliği gönderilen istekte figüre "Design point reported
            # by the motor solver" künyesiyle Pc 50 · O/F 3,5 · Isp 300
            # haçı basılıyordu — hiçbir motor çözülmeden. Varsayılanlar
            # kalktı: gönderilmeyen alan sözlüğe hiç girmez (aşağıdaki
            # None süzgeci) ve görselleştirme haçı ÇİZMEZ. Gönderilen sayı
            # ise istekten gelir; kaynağını çağıran ``design_point_source``
            # ile BEYAN etmedikçe "motor sonucu" diye etiketlenmez.
            engine_data = {
                'base_isp': data.get('base_isp'),
                'optimal_of_ratio': data.get('optimal_of_ratio'),
                'optimal_chamber_pressure': data.get('chamber_pressure'),
                'design_point_source': data.get('design_point_source'),
                'fuel_type': data.get('fuel_type'),
                'fuel_composition': data.get('fuel_composition'),
                'oxidizer_type': data.get('oxidizer_type'),
                'pc_range': data.get('pc_range'),
                'of_range': data.get('of_range'),
                'grid_n': data.get('grid_n'),
            }
            engine_data = {k: v for k, v in engine_data.items() if v is not None}

            plot_json = create_chamber_pressure_mixture_ratio_3d_surface(engine_data)

            _yuzey_govde = {
                'status': 'success',
                'plot_data': plot_json,
                'analysis_info': {
                    'title': '3D Performance Surface Analysis',
                    # C2: künye "Liquid-Propellant Rocket Engine Performance"
                    # diyordu; SP-125'in gerçek adı bu değil. Doğrulanmış ad
                    # docs/STANDART_ATIFLARI.md'de (NTRS/ADS 1971NASSP.125.....H).
                    'reference': ('NASA SP-125 — Huzel & Huang, Design of '
                                  'Liquid Propellant Rocket Engines '
                                  '(2nd ed., 1971)'),
                    'description': 'Shows optimum O/F ratio and chamber pressure regions with combustion instability bands'
                }
            }
            # Kitap uyum B16, 2. tur (Ş-7): yüzey düğümleri görselleştirme
            # modülünün KENDİ (modül düzeyi önbellekli) analizöründe çözülür;
            # giriş durumu oraya taşınamaz (dosya bu kulvarın dışında,
            # devir). Yüzey bu yüzden VARSAYILAN N₂O giriş durumunda
            # çözülür ve bu ADIYLA beyan edilir; istek farklı bir durum
            # taşıyorsa uygulanmadığı da söylenir.
            from hrma.visualization.visualization import (
                _resolve_surface_propellant)
            from hrma.engines.oxidizer_inlet import (
                inlet_request_from_payload, unapplied_inlet_state_declaration)
            _yuzey_ox = _resolve_surface_propellant(engine_data)[1]
            if str(_yuzey_ox).strip().lower() == 'n2o':
                _yuzey_govde['oxidizer_inlet_state'] = (
                    unapplied_inlet_state_declaration(
                        _yuzey_ox, inlet_request_from_payload(data),
                        'the surface nodes are solved by the visualization '
                        "module's own cached equilibrium analyzer, which "
                        'is always at the default inlet state'))
            return jsonify(_yuzey_govde)

        elif analysis_type == 'nozzle_mach':
            # Nozzle Mach-Area Ratio Contour
            # (NACA Report 1135, "Equations, Tables, and Charts for
            #  Compressible Flow", Ames Research Staff, 1953; Anderson,
            #  "Modern Compressible Flow", 3. baskı — bkz.
            #  hrma/analysis/nozzle_flow_1d.py:12-26 kaynak listesi)
            #
            # DENETİM DÜZELTMESİ (2026-08-02, C2): bu satır ve aşağıdaki
            # 'reference' alanı konturun kaynağı olarak NASA-STD-5012
            # gösteriyordu. İki ayrı hata vardı: (1) BAŞLIK yanlıştı —
            # belgeye "Pressure Vessels & Pressurized Systems" deniyordu,
            # gerçek adı "Strength and Life Assessment Requirements for
            # Liquid-Fueled Space Propulsion System Engines" (Rev. B, 2016);
            # (2) KONU yanlıştı — o belge motor mukavemeti ve ömür
            # değerlendirmesi hakkındadır, içinde izantropik alan-Mach
            # bağıntısı yoktur, dolayısıyla bu figürün kaynağı olamaz.
            # Doğrulanmış başlıklar: docs/STANDART_ATIFLARI.md; aynı
            # düzeltme formulas.html §14.2, i18n_formulas.js (EN+TR) ve
            # performance_panel.js:7'de yapıldı — kaynak adı üç yerde
            # birebir aynıdır.
            # v2.5.2 (Codex bulgusu): yalnız throat_area / nozzle_length /
            # expansion_ratio aktarılıyordu; gaz hâli (gamma, MW, Tc), oda
            # basıncı, hazne çapı ve ortam basıncı DÜŞÜYORDU. Çözücü kendi
            # 20 bar / gamma 1.20 / 1 atm varsayılanlarına iniyor, oda
            # basıncını değiştirmek grafiği hiç değiştirmiyordu. Aynı ısı
            # akısı dalındaki desen uygulanır: alan varsa geçilir, yoksa
            # hiç konmaz ve figür "assumed" listesinde açıkça yazar.
            cfd_data = {
                # ÖH D23 a2 / P13B4-12: ham 400 alanı ADIYLA anmıyordu.
                # ÖH D27 a4 / P7B4-11: ``default=`` KALKTI (bkz.
                # ``_APA_REQUIRED_ANY_OF``); alan yoksa sözlüğe HİÇ girmez.
                'throat_area': input_guard.num(
                    data, 'throat_area', unit='m^2'),
                'throat_diameter': data.get('throat_diameter'),
                'exit_diameter': data.get('exit_diameter'),
                'nozzle_length': input_guard.num(
                    data, 'nozzle_length', unit='m'),
                'expansion_ratio': input_guard.num(
                    data, 'expansion_ratio'),
                'chamber_diameter': data.get('chamber_diameter'),
                'chamber_pressure': data.get('chamber_pressure'),
                'chamber_temperature': data.get('chamber_temperature'),
                'gamma': data.get('gamma'),
                'molecular_weight': data.get('molecular_weight'),
                # Görselleştirme sözleşmesi: ambient_pressure PASCAL
                # (NozzleFlow1D.from_motor_data ambient_pressure=Pa bekler).
                # Bar cinsinden gönderen çağıranlar için ayrı anahtar.
                'ambient_pressure': (
                    data.get('ambient_pressure')
                    if data.get('ambient_pressure') is not None
                    else (float(data['ambient_pressure_bar']) * 1e5
                          if data.get('ambient_pressure_bar') is not None
                          else None)),
            }
            cfd_data = {k: v for k, v in cfd_data.items() if v is not None}

            # ÖH D27 a4 / P7B4-11: fail-closed kapı (bkz.
            # ``_APA_REQUIRED_ANY_OF``). Modülün kendi ``ValueError``ı
            # aşağıda yakalanır — kapı onun İKİZİDİR, yerine geçmez.
            _apa_eksik = _apa_eksik_zorunlu('nozzle_mach', cfd_data)
            if _apa_eksik:
                return _apa_eksik_reddi('nozzle_mach', _apa_eksik)

            plot_json = create_nozzle_mach_area_ratio_contour(cfd_data)
            
            return jsonify({
                'status': 'success',
                'plot_data': plot_json,
                'analysis_info': {
                    'title': 'Nozzle Mach Distribution Analysis',
                    'reference': ('NACA Report 1135, "Equations, Tables, and '
                                  'Charts for Compressible Flow" (Ames '
                                  'Research Staff, 1953); Anderson, "Modern '
                                  'Compressible Flow", 3rd ed.'),
                    'description': 'Visualizes Mach distribution and shock/threshold regions for over/under-expansion detection'
                }
            })
            
        elif analysis_type == 'heat_flux':
            # Wall Heat Flux Waterfall (NASA SP-8124)
            # v2.5.2: panel throat_area / chamber_pressure / expansion_ratio
            # gönderiyordu ama bu sözlüğe konmuyordu, dolayısıyla ısı akısı
            # GERÇEK Bartz hesabına giremeyip "not available" durumuna
            # düşüyordu. Üç alan da geçiriliyor; ek olarak malzeme, gaz
            # özellikleri ve kütle debisi de varsa aktarılır.
            # ÖH D27 a4 / P7B4-11: BEŞ ``default=`` KALKTI. Gerekçe ve
            # ölçüm ``_APA_REQUIRED_ANY_OF``ta; ``base_heat_flux`` ve
            # ``critical_heat_flux`` figürün KULLANICI referans düzlemleridir
            # (``_heat_flux_reference_planes``) — sorulmamış bir referans
            # çizgisi çizilmez.
            thermal_data = {
                'burn_time': input_guard.num(data, 'burn_time', unit='s'),
                'chamber_length': input_guard.num(
                    data, 'chamber_length', unit='m'),
                'nozzle_length': data.get('nozzle_length'),
                'base_heat_flux': input_guard.num(
                    data, 'base_heat_flux', unit='W/m^2'),
                'critical_heat_flux': input_guard.num(
                    data, 'critical_heat_flux', unit='MW/m^2'),
                'molecular_weight': data.get('molecular_weight'),
                'throat_area': data.get('throat_area'),
                'throat_diameter': data.get('throat_diameter'),
                'chamber_pressure': data.get('chamber_pressure'),
                'chamber_temperature': data.get('chamber_temperature'),
                'expansion_ratio': data.get('expansion_ratio'),
                'chamber_diameter': data.get('chamber_diameter'),
                'mdot_total': data.get('mdot_total'),
                'gamma': data.get('gamma'),
                'material': data.get('material'),
                'c_star': data.get('c_star'),
            }
            thermal_data = {k: v for k, v in thermal_data.items() if v is not None}

            # ÖH D27 a4 / P7B4-11 — bkz. ``_APA_REQUIRED_ANY_OF``.
            _apa_eksik = _apa_eksik_zorunlu('heat_flux', thermal_data)
            if _apa_eksik:
                return _apa_eksik_reddi('heat_flux', _apa_eksik)

            plot_json = create_wall_heat_flux_waterfall_plot(thermal_data)
            
            return jsonify({
                'status': 'success',
                'plot_data': plot_json,
                'analysis_info': {
                    'title': 'Wall Heat Flux Waterfall Analysis',
                    # C2: künye "Thermal Design Criteria" diyordu; SP-8124'ün
                    # gerçek adı bu değil (NTRS 78N21211). Doğrulanmış ad
                    # docs/STANDART_ATIFLARI.md'de.
                    'reference': ('NASA SP-8124 — Liquid Rocket Engine '
                                  'Self-Cooled Combustion Chambers (1977)'),
                    'description': 'Gradient colored waterfall showing local heat flux along cooling channels with thermal runaway detection'
                }
            })
            
        else:
            return jsonify({
                'status': 'error',
                'error': f'Unknown analysis type: {analysis_type}',
                'available_types': ['3d_surface', 'nozzle_mach', 'heat_flux']
            }), 400

    # ÖH D27 a4 / P7B4-11 — İSTEMCİ HATASI SUNUCU ARIZASI GİBİ YAYIMLANMAZ.
    # ``input_guard`` okunamayan alanı, figür modülü ise eksik/çelişkili
    # geometriyi ``ValueError`` ile bildirir; ikisi de 500 sınıfı DEĞİLDİR.
    except input_guard.InputError as _apa_ig:
        return jsonify({
            'status': 'error',
            'error': 'invalid_figure_input',
            'message': str(_apa_ig),
        }), 422
    except ValueError as _apa_ve:
        return jsonify({
            'status': 'error',
            'error': 'incomplete_figure_input',
            'message': str(_apa_ve),
            'analysis_type': analysis_type,
            'required_any_of': [list(g) for g in
                                _APA_REQUIRED_ANY_OF.get(analysis_type, ())],
        }), 422
    except Exception as e:
        return jsonify({
            'status': 'error',
            'error': str(e)
        }), 500

# PDF Export Endpoints
def _build_pdf_analysis_sections(motor_data, analysis_results):
    """PDF rapor bölümlerini motorun GERÇEK analiz sonuçlarıyla doldurur.

    Kaynak öncelik sırası (Dalga 2, 2026-07-14):
      motor sonuçları (motor_data.heat_transfer_analysis /
      structural_analysis) > istekle gelen analysis_results alanları.
    Sabit/uydurma değer ÜRETİLMEZ: veri yoksa ilgili alan hiç konmaz;
    pdf_generator eksik alanları 'N/A' olarak basar. (Eski app.js sabit
    SF 4.0/3.0/4.0 dürüstlük sorununun rapor katmanındaki karşılığı.)
    """
    out = dict(analysis_results or {})
    md = motor_data or {}

    def _num(value):
        # P15B2-01 / OH-D30-08: sonlu-sayı kararı merkezden.
        return input_guard.finite_number(value)

    # ---- Performans: motor sonucundaki gerçek değerler öncelikli ----
    #
    # ÖH Z5S / S7 (defter P9B3-09, KRİTİK — P09-D'den devir). ÖLÇÜLDÜ
    # (28 Ağustos 2026, bu ağaçta, katı sayfasının GERÇEK gövdesiyle):
    #
    #   /calculate_solid yayımladı: max_thrust=3491,48 N,
    #     specific_impulse=248,53 s, burn_time=3,011 s,
    #     total_impulse=10.093,54 N·s, chamber_pressure=50 bar
    #   /api/export-pdf/complete bastı: yönetici özeti 4/4 "N/A",
    #     performans tablosu 7/7 "N/A"
    #
    # Sebep BESLEME KATMANINDAYDI, rapor katmanında değil: ``solid.html``
    # ``motor_data`` alanına FORM GEOMETRİSİNİ (çap/boy/yoğunluk), gerçek
    # çözücü sonucunu ise ``analysis_results``ın ÜST DÜZEYİNE koyar
    # (``window.currentResults``). Bu fonksiyon performans alanlarını yalnız
    # ``motor_data``da arıyordu; ``pdf_generator`` da yalnız hazırlanmış
    # ``performance`` bloğu ile ``motor_data``ya bakıyor. Yani çözücünün
    # sayıları raporun hiçbir kaynağında görünmüyordu.
    #
    # Ad çözümü ``pdf_generator.SOLVER_PERFORMANCE_ALIASES`` tablosundan
    # gelir — İKİNCİ BİR AD LİSTESİ TUTULMAZ (aynı büyüklüğe iki farklı
    # cevap veren eski desenin kaynağı buydu).
    from hrma.export.pdf_generator import SOLVER_PERFORMANCE_ALIASES

    raw_solver = analysis_results if isinstance(analysis_results, dict) else {}

    def _coz(aliases):
        """Önce ``motor_data``, sonra ham çözücü yükü. Uydurma YOK."""
        for source in (md, raw_solver):
            if not isinstance(source, dict):
                continue
            for name in aliases:
                value = _num(source.get(name))
                if value is not None:
                    return value
        return None

    performance = dict(out.get('performance') or {})
    for target, aliases in SOLVER_PERFORMANCE_ALIASES.items():
        value = _coz(aliases)
        if value is not None:
            performance[target] = value
    if performance:
        out['performance'] = performance


    # ---- Termal: heat_transfer_analysis (Bartz) gerçek sonuçları ----
    heat = md.get('heat_transfer_analysis') or out.get('heat_transfer_analysis') or {}
    if isinstance(heat, dict) and heat:
        wall = heat.get('wall_analysis') or {}
        gas_side = heat.get('gas_side_analysis') or {}
        cooling = heat.get('cooling_analysis') or {}
        thermal = dict(out.get('thermal') or {})
        heat_flux = _num(gas_side.get('heat_flux'))
        candidates = {
            'max_wall_temp': _num(wall.get('max_temperature')),
            'heat_flux': heat_flux / 1e6 if heat_flux is not None else None,  # W/m^2 -> MW/m^2
            'cooling_req': _num(cooling.get('peak_heat_rate')),  # kW
            'adiabatic_wall_temp': _num(gas_side.get('adiabatic_wall_temperature')),
            'gas_side_coefficient': _num(gas_side.get('gas_side_coefficient')),
        }
        for key, value in candidates.items():
            if value is not None:
                thermal[key] = value

        # ÖH D15 / defter P9B3-05 — ÇÖZÜCÜNÜN HÜKMÜ KÂĞIDA ÇIKMIYORDU.
        # ÖLÇÜLDÜ (hibrit, bu ağaçta): çözücü
        # ``gas_side_analysis.wall_temperature_unphysical = True``,
        # ``safety_analysis.melting_safety_factor = 0,907``,
        # ``temperature_safety_factor = 0,532``, ``risk_level = HIGH``
        # yayımlıyordu; PDF metninde ``melting`` / ``unphysical`` /
        # ``exceeds`` / ``warn.thermal`` / ``melting_safety`` dizelerinin
        # 5/5'i YOKTU — yalnız beş sayı basılıyordu. Belgenin okuyucusu
        # 3283 K'yi normal bir tasarım sayısı sanıyordu.
        #
        # Karşıtlık zaten depodaydı: YAPISAL bölümde ``status`` ve
        # ``risk_level`` PDF'e taşınıyor (birkaç satır aşağıda); termalde
        # eşdeğeri yoktu. Aynı desen buraya da uygulandı.
        if gas_side.get('wall_temperature_unphysical') is not None:
            thermal['wall_temperature_unphysical'] = bool(
                gas_side.get('wall_temperature_unphysical'))
        melting_sf = _num((heat.get('safety_analysis') or {}).get(
            'melting_safety_factor'))
        if melting_sf is not None:
            thermal['melting_safety_factor'] = melting_sf
        temp_sf = _num((heat.get('safety_analysis') or {}).get(
            'temperature_safety_factor'))
        if temp_sf is not None:
            thermal['temperature_safety_factor'] = temp_sf
        for alan in ('status', 'risk_level'):
            deger = (heat.get('safety_analysis') or {}).get(alan)
            if deger:
                thermal[alan] = str(deger)
        # Malzeme ve ergime noktası: uyarı metni "hangi malzeme, kaç K"
        # diyebilsin diye taşınır (uydurulmaz; yoksa konmaz).
        for kaynak, alan in ((gas_side, 'material'),
                             (heat.get('safety_analysis') or {},
                              'melting_temperature'),
                             (wall, 'material')):
            deger = kaynak.get(alan) if isinstance(kaynak, dict) else None
            if deger not in (None, '') and alan not in thermal:
                thermal[alan] = deger
        # Termal uyarı kayıtları OLDUĞU GİBİ taşınır (kod + mesaj +
        # şiddet); rapor katmanı metni kendisi UYDURMAZ.
        _uyarilar = [w for w in (heat.get('warnings') or [])
                     if isinstance(w, dict)]
        if _uyarilar:
            thermal['warnings'] = _uyarilar

        if thermal:
            out['thermal'] = thermal

    # ---- Çözücünün BEYAN blokları (ÖH D15 / defter P9B3-26) ----
    #
    # ÖLÇÜLDÜ (hibrit, /api/export-pdf/complete): çözücü
    # ``not_modelled`` = 6 fizik kalemi (feed_system,
    # hybrid_boundary_layer_instability, ignition_startup_transient,
    # oxidizer_tank_structural_mass, shutdown_transient,
    # throttle_response_restart) ve YEDİ ``*_basis`` / ``l_star_note``
    # metni yayımlıyordu; PDF metninde ``not modelled`` / ``not_modelled``
    # / ``burn time basis`` / ``L* `` dizelerinin hiçbiri geçmiyordu.
    # Teknik ek "Analysis Assumptions" başlığı altında SABİT bir varsayım
    # listesi basıyor, motorun KENDİ "bunu modellemiyoruz" listesini
    # basmıyordu. Aynı beyanlar ``.eng`` dosyasına ZATEN taşınıyor — desen
    # depoda vardı, PDF'e uygulanmamıştı.
    #
    # Blok raporun kendi sözlüğüne konur; ``pdf_generator`` onu teknik ekte
    # basar. Değer UYDURULMAZ: yalnız çözücüde GERÇEKTEN bulunan alanlar.
    beyan = {}
    for kaynak in (md, raw_solver):
        if not isinstance(kaynak, dict):
            continue
        _nm = kaynak.get('not_modelled')
        if _nm and 'not_modelled' not in beyan:
            beyan['not_modelled'] = sorted(str(x) for x in _nm)
        _w = [w for w in (kaynak.get('warnings') or []) if isinstance(w, dict)]
        if _w and 'warnings' not in beyan:
            beyan['warnings'] = _w
        _dw = [w for w in (kaynak.get('design_warnings') or [])
               if isinstance(w, dict)]
        if _dw and 'design_warnings' not in beyan:
            beyan['design_warnings'] = _dw
        for ad, deger in kaynak.items():
            if not isinstance(ad, str):
                continue
            if not (ad.endswith('_basis') or ad.endswith('_note')):
                continue
            if isinstance(deger, str) and deger.strip():
                beyan.setdefault('basis_notes', {}).setdefault(ad, deger)
    if beyan:
        out['solver_declarations'] = beyan

    # ---- Yapısal: gerçek SF'ler (sabit 4.0 kalıntısı YOK) ----
    structural_src = md.get('structural_analysis') or out.get('structural_analysis') or {}
    if isinstance(structural_src, dict) and structural_src:
        safety_sub = structural_src.get('safety_analysis') or {}
        chamber = structural_src.get('chamber_analysis') or {}
        structural = dict(out.get('structural') or {})
        candidates = {
            'safety_factor': _num(structural_src.get('safety_factor')),
            'safety_factor_pressure': _num(structural_src.get('safety_factor_pressure')),
            'safety_factor_total': _num(structural_src.get('safety_factor_total')),
            'min_safety_factor': _num(safety_sub.get('minimum_safety_factor')),
            'von_mises_stress_MPa': _num(chamber.get('von_mises_stress')),
            'hoop_stress_MPa': _num(chamber.get('hoop_stress')),
        }
        for key, value in candidates.items():
            if value is not None:
                structural[key] = value
        if safety_sub.get('status'):
            structural['status'] = str(safety_sub['status'])
        if safety_sub.get('risk_level'):
            structural['risk_level'] = str(safety_sub['risk_level'])
        if structural:
            out['structural'] = structural

    # --- ÖH D30 / app-api-uc a2 · P7B4-16 · TAUTOLOJİ BAĞLAMI PDF'E GEÇER -
    # ÖLÇÜLDÜ (``a2/once.json`` K2, taban ``ab7cf68b``): bu fonksiyon
    # ``analysis_results``ı kopyalıyor ve emniyet katsayısını BAĞLAMINDAN
    # KOPARARAK taşıyordu. Yalnız ``analysis_results`` gönderen istemcide
    # (``{'structural': {'min_safety_factor': 4.0}}``) çıktı sözlüğünde
    # ``structural_analysis`` HİÇ olmuyordu; ``pdf_generator`` tasarım
    # tabanını yalnız o ham bloktan okuduğu için
    # (``_structural_design_basis(structural_raw)``) ``known=False`` dalına
    # düşüyor ve PDF'e "Minimum Safety Factor (all modes) 4.00" satırını
    # BEYANSIZ basıyordu — 'Design basis' notu hiç çıkmıyordu.
    #
    # Savcının hükmü (``raw/P07/S1-savci.md`` §EKA, "en ağır alt küme"):
    # *"dürüstlük katmanı JSON'da var, PDF'te yok"*. ``/calculate`` ve
    # ``/calculate_solid`` yanıtları ``safety_factor_is_tautological``,
    # ``design_mode``, ``verdict_basis``, ``structural_design_basis`` ile
    # tautolojiyi titizlikle kuruyor; eksik olan tek şey bu katmanın rapor
    # besleyicisinden GEÇMESİYDİ.
    #
    # İki ayrı iş, ikisi de beyan DEĞİL davranış:
    #
    # (a) TAŞIMA — motorun kendi dürüstlük bloğu (``structural_analysis``,
    #     ``structural_design_basis``, katı/sıvı ``case_analysis``) çıktı
    #     sözlüğüne AYNEN kopyalanır, böylece ``pdf_generator``ın ZATEN
    #     doğru olan taban mantığı doğru dalı seçer ve 'Design basis' notu
    #     basılır. Sayı ÜRETİLMEZ, yalnız var olan blok taşınır.
    #
    # (b) FAIL-CLOSED — hiçbir kaynakta tabanı söyleyen bir blok YOKSA,
    #     emniyet katsayısı "doğrulanmış pay mı yoksa girdinin geri okunması
    #     mı" olduğu BİLİNMEYEN bir sayıdır. Kazanılmamış hüküm yayımlanmaz
    #     (Doktrin 1): satırlar rapordan DÜŞÜRÜLÜR ve düşürülme gerekçesi
    #     ``structural_withheld`` ile makine-okur biçimde yayımlanır. Bu,
    #     v2.5 öncesindeki sabit "SF 4.0" kalıntısının rapor katmanındaki
    #     son kapısıdır.
    _tab_bloklari = ('structural_analysis', 'structural_design_basis',
                     'pressure_vessel')
    for _kaynak in (md, raw_solver):
        if not isinstance(_kaynak, dict):
            continue
        for _ad in _tab_bloklari:
            _blok = _kaynak.get(_ad)
            if isinstance(_blok, dict) and _blok and _ad not in out:
                out[_ad] = _blok

    _sf_satirlari = ('min_safety_factor', 'safety_factor',
                     'safety_factor_pressure', 'safety_factor_total')
    _yapisal_cikti = out.get('structural')
    if isinstance(_yapisal_cikti, dict) and any(
            _yapisal_cikti.get(_k) is not None for _k in _sf_satirlari):
        _ham = out.get('structural_analysis')
        _taban_bilinir = False
        if isinstance(_ham, dict) and _ham:
            _safety = _ham.get('safety_analysis') or {}
            if isinstance(_safety.get('safety_factor_is_tautological'), dict):
                _taban_bilinir = True
            else:
                for _blok in _ham.values():
                    if isinstance(_blok, dict) and (
                            'safety_factor_is_tautological' in _blok
                            or 'design_mode' in _blok):
                        _taban_bilinir = True
                        break
        if not _taban_bilinir and isinstance(
                out.get('structural_design_basis'), dict):
            _taban_bilinir = bool(out['structural_design_basis'])
        if not _taban_bilinir:
            _dusurulen = {_k: _yapisal_cikti[_k] for _k in _sf_satirlari
                          if _yapisal_cikti.get(_k) is not None}
            for _k in _dusurulen:
                _yapisal_cikti.pop(_k, None)
            out['structural'] = _yapisal_cikti
            out['structural_withheld'] = {
                'fields': sorted(_dusurulen),
                'submitted_values': _dusurulen,
                'reason': 'design_basis_unknown',
                'message': (
                    'These safety factors were not printed: the request '
                    'carried the numbers but no structural_analysis / '
                    'structural_design_basis block, so nothing says whether '
                    'they are a VERIFICATION of an as-built wall or the '
                    'design safety factor target read back '
                    '(safety_factor_is_tautological). A report cannot call '
                    'an unattributed number a safety margin. Send the '
                    'solver block from /calculate, /calculate_solid or '
                    '/analyze_structural_safety alongside them.'),
            }

    # ---- Güvenlik özeti: istekle geldiyse aynen korunur ----
    # (out zaten istekten kopyalandı; 'safety' anahtarına dokunulmaz.)
    return out


def _build_pdf_motor_data(motor_data, analysis_results):
    """Rapor YAPILANDIRMA tablosunun besleme sözleşmesi.

    ÖH Z5S / S7 (defter P9B3-09'un ikinci ayağı).
    ``pdf_generator._create_motor_configuration`` YALNIZ ``motor_data``ya
    bakar. Katı sayfası ``motor_data``ya form geometrisini koyar; O/F oranı
    ve tanecik yoğunluğu gibi ÇÖZÜLMÜŞ büyüklükler ise ham çözücü yükünde
    (``analysis_results`` üst düzeyi) durur. Ölçüldü: sıvı koşumda
    ``mixture_ratio`` çözücüde VAR, tabloda "N/A" idi.

    Değer UYDURULMAZ: yalnız ham yükte GERÇEKTEN bulunan sonlu sayı
    taşınır ve ``motor_data``daki kullanıcı girdisi HER ZAMAN öncelikli
    kalır. Hiçbir şey bulunmazsa sözlük DEĞİŞMEDEN döner (aynı nesne).
    """
    from hrma.export.pdf_generator import SOLVER_CONFIG_ALIASES
    md = motor_data or {}
    raw_solver = analysis_results if isinstance(analysis_results, dict) else {}
    if not isinstance(md, dict) or not raw_solver:
        return md

    def _num(value):
        # P15B2-01 / OH-D30-08: sonlu-sayı kararı merkezden.
        return input_guard.finite_number(value)

    eklenen = {}
    for target, aliases in SOLVER_CONFIG_ALIASES.items():
        if any(_num(md.get(name)) is not None for name in aliases):
            continue
        for name in aliases:
            value = _num(raw_solver.get(name))
            if value is not None:
                eklenen[target] = value
                break
    if not eklenen:
        return md
    return dict(md, **eklenen)


@app.route('/api/materials', methods=['GET'])
def get_materials_catalog():
    """Merkezi malzeme kütüphanesini döndürür.

    Sözleşme (v2.5.2): {ok, materials: {key: {name, source, tags, ...}},
    aliases: {...}, default_structural_material: str}. Paneller (static/js/materials_catalog.js) select
    listelerini buradan doldurur; endpoint yoksa hardcoded fallback'e düşer.
    """
    try:
        from hrma.data.materials_db import (
            MATERIALS, ALIASES, DEFAULT_STRUCTURAL_MATERIAL)
        return jsonify(sanitize_json_values({
            'ok': True,
            'materials': MATERIALS,
            'aliases': ALIASES,
            # ÖH D24 / OH-D23-03: yapısal varsayılan malzemenin TEK
            # KAYNAĞI sunucudadır. İstemci panelleri kendi sabitlerini
            # taşımak zorunda kalırsa (senkron form kurulumu) bekçi
            # ikisini eşitler; bu alan o eşitlemenin referansıdır.
            'default_structural_material': DEFAULT_STRUCTURAL_MATERIAL,
        }))
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/propellants', methods=['GET'])
def get_propellants_catalog():
    """Merkezi katı yakıt kataloğunu döndürür.

    Sözleşme (v2.5.2) — /api/materials ile birebir aynı desen:
        {ok: true,
         propellants: {key: {...tüm kayıt alanları}},
         aliases: {alias: canonical_key}}
    Katı sayfası (static/js/propellant_catalog.js) yakıt seçicisini ve
    otomatik dolan özellik alanlarını buradan besler; endpoint yoksa
    sayfa kendi hardcoded fallback listesine düşer.

    Tek doğruluk kaynağı: hrma/data/propellants_db.py — yanma hızı yasası
    olan yakıtlarda (KNDX/KNSB) a-n değerleri merkezi burn_rate_db'den
    türetilir, burada ayrıca yazılmaz.
    """
    try:
        from hrma.data.propellants_db import PROPELLANTS, ALIASES
        return jsonify(sanitize_json_values({
            'ok': True,
            'propellants': PROPELLANTS,
            'aliases': ALIASES,
        }))
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


#: Elektronik tabloların formül başlangıcı saydığı karakterler. Excel ve
#: LibreOffice '=' dışındakileri de bağlama göre formül/komut olarak
#: yorumlayabildiği için dördü birden kaçırılır (CWE-1236).
_FORMULA_LEAD = ('=', '+', '-', '@', '\t', '\r', '\n')


def _looks_numeric(text_value):
    """'-5000' / '+3.2e4' gibi sayı görünen metin mi?

    Formül kaçışının bunlara DOKUNMAMASI gerekir: negatif sayılar '-' ile
    başlar ve körü körüne apostrof eklemek veriyi bozardı.
    """
    try:
        parsed = float(text_value)
    except (TypeError, ValueError):
        return False
    return math.isfinite(parsed)


def _spreadsheet_safe(value):
    """Kullanıcı metnini hücreye yazmadan önce formüle dönüşmekten korur.

    v2.6.26 ÖLÇÜMÜ: '=1+1' ile başlayan bir motor adı XLSX'e yazıldığında
    openpyxl hücreyi ``data_type='f'`` (formül) olarak saklıyordu; dosya
    yeniden açıldığında formül olarak görünüyordu. Başa apostrof koymak
    elektronik tabloların standart 'bu metindir' işaretidir ve hücre metni
    olarak görüntülenirken apostrof gösterilmez.
    """
    text_value = str(value)
    if text_value.startswith(_FORMULA_LEAD) and not _looks_numeric(text_value):
        return "'" + text_value
    return text_value


def _safe_sheet_title(title, idx):
    """Excel'in yasakladığı karakterleri temizler (eskiden HTTP 500 oluyordu).

    ÖH Z5S / S7 (P16B4-27): temizlenen ad BAŞTAKİ NOKTA DİZİSİNİ koruyordu.
    Ölçüldü: ``{'name': '../[]:*?/\\\\'}`` -> HTTP 200, sayfa adı
    ``'..________'``. Excel'de zararsızdır (sayfa adı bir yol değildir) ama
    aynı deponun dosya-adı tarafı (``input_guard.safe_name``) baştaki/sondaki
    ``.`` ve ``_`` karakterlerini ``strip('._')`` ile ATIYOR — iki temizleyici
    aynı girdiye iki farklı ad veriyordu. Burada da aynı alfabe uygulanır;
    ad tamamen erirse numaralı yedeğe düşülür (sessiz boş ad yok).
    """
    import re
    cleaned = re.sub(r'[\\/*?:\[\]]', '_', str(title)).strip()
    # safe_name ile AYNI kural: kenarlardaki nokta/alt çizgi taşınmaz.
    cleaned = cleaned.strip('._') or f'Sheet{idx + 1}'
    return cleaned[:31]


# ---------------------------------------------------------------------------
# D8 — XLSX İŞ BÜTÇESİ (2026-08-02)
#
# ÖLÇÜLDÜ: tek bir 23.3 MiB istek 26.3 saniye sürdü ve süreç 2.4 GB RSS'e
# çıktı. 60 000 sütunluk sayfa hiçbir yerde yakalanmıyordu, 200 000
# karakterlik hücreyi openpyxl SESSİZCE 32 767'ye kırpıyordu (bu makinede
# doğrulandı: 200000 karakter yazıldı, geri okunan uzunluk 32767).
#
# Eski kodda iki SESSİZ kırpma daha vardı: ``sheets[:20]`` ve
# ``rows[:100000]``. Kullanıcı eksik bir çalışma kitabı indiriyor ve bunu
# hiçbir yerden öğrenemiyordu. Artık her sınır AÇIK hata döndürür.
#
# Sınırların dayanağı — bu makinede openpyxl ile ölçüldü:
#   500 000 sayısal hücre (250 sütun x 2000 satır) -> 1.2 s, 229 MB tepe RSS
#   500 000 sayısal hücre (10 sütun x 50 000 satır) -> 1.4 s, 263 MB tepe RSS
#   8 000 000 karakter metin                        -> 0.13 s, 59 MB
# Gerçek HRMA çıktılarının en genişi 10 sütun (transient paneli ve katı
# motor itki eğrisi sayfası), en uzunu birkaç bin satır — yani meşru
# kullanım bu tavanların çok altında.
# ---------------------------------------------------------------------------
XLSX_MAX_SHEETS = 20
XLSX_MAX_COLUMNS = 256
XLSX_MAX_ROWS_PER_SHEET = 100_000
XLSX_MAX_TOTAL_CELLS = 500_000
#: Excel'in kendi hücre sınırı. Aşan değeri KIRPMAK yerine reddediyoruz.
XLSX_MAX_CELL_CHARS = 32_767


def _xlsx_budget_error(sheets):
    """İş bütçesi aşıldı mı? Aşıldıysa ``(gövde, http_kodu)`` döner.

    Sessiz kırpma yasak: her ret, hangi sayfanın hangi sınırı hangi değerle
    aştığını söyler. 413 "istek fazla büyük", 422 "istek biçimi geçersiz".
    """
    if len(sheets) > XLSX_MAX_SHEETS:
        return ({'status': 'error', 'error': 'xlsx_budget_exceeded',
                 'limit': 'sheets', 'maximum': XLSX_MAX_SHEETS,
                 'requested': len(sheets),
                 'message': (f'At most {XLSX_MAX_SHEETS} sheets per workbook; '
                             f'{len(sheets)} were supplied.')}, 413)

    total_cells = 0
    for idx, sheet in enumerate(sheets):
        if not isinstance(sheet, dict):
            return ({'status': 'error', 'error': 'invalid_sheet',
                     'sheet_index': idx,
                     'message': 'Each sheet must be an object with '
                                '{name, headers, rows}.'}, 422)
        headers = sheet.get('headers') or []
        rows = sheet.get('rows') or []
        if len(rows) > XLSX_MAX_ROWS_PER_SHEET:
            return ({'status': 'error', 'error': 'xlsx_budget_exceeded',
                     'limit': 'rows_per_sheet', 'sheet_index': idx,
                     'maximum': XLSX_MAX_ROWS_PER_SHEET,
                     'requested': len(rows),
                     'message': (f'Sheet {idx} has {len(rows)} rows; the '
                                 f'limit is {XLSX_MAX_ROWS_PER_SHEET}.')}, 413)

        widest = len(headers)
        for row in rows:
            width = len(row) if isinstance(row, (list, tuple)) else 1
            if width > widest:
                widest = width
        if widest > XLSX_MAX_COLUMNS:
            return ({'status': 'error', 'error': 'xlsx_budget_exceeded',
                     'limit': 'columns', 'sheet_index': idx,
                     'maximum': XLSX_MAX_COLUMNS, 'requested': widest,
                     'message': (f'Sheet {idx} is {widest} columns wide; the '
                                 f'limit is {XLSX_MAX_COLUMNS}.')}, 413)

        total_cells += widest * (len(rows) + (1 if headers else 0))
        if total_cells > XLSX_MAX_TOTAL_CELLS:
            return ({'status': 'error', 'error': 'xlsx_budget_exceeded',
                     'limit': 'total_cells',
                     'maximum': XLSX_MAX_TOTAL_CELLS,
                     'requested': total_cells,
                     'message': (f'The workbook would contain at least '
                                 f'{total_cells} cells; the limit is '
                                 f'{XLSX_MAX_TOTAL_CELLS}.')}, 413)

        def _too_long(values, kind):
            for value in values:
                if isinstance(value, str) and len(value) > XLSX_MAX_CELL_CHARS:
                    return ({'status': 'error', 'error': 'xlsx_cell_too_long',
                             'sheet_index': idx, 'cell_kind': kind,
                             'maximum': XLSX_MAX_CELL_CHARS,
                             'requested': len(value),
                             'message': (f'A {kind} cell holds {len(value)} '
                                         f'characters; Excel stores at most '
                                         f'{XLSX_MAX_CELL_CHARS} and the '
                                         f'value would be truncated without '
                                         f'notice.')}, 422)
            return None

        problem = _too_long(headers, 'header')
        if problem:
            return problem
        for row in rows:
            problem = _too_long(
                row if isinstance(row, (list, tuple)) else [row], 'data')
            if problem:
                return problem
    return None


@app.route('/api/export-xlsx', methods=['POST'])
def export_xlsx():
    """Genel amaçlı Excel (xlsx) dışa aktarma.

    Girdi: {filename: 'name.xlsx', sheets: [{name, headers: [...],
    rows: [[...], ...]}]}. Transient sonuçları, regresyon analizi ve
    genel analiz özeti bu uçtan insan-dostu Excel olarak iner
    (kullanıcı şikayeti: .json indirmesi kullanışsızdı).
    """
    try:
        from io import BytesIO
        from openpyxl import Workbook
        from openpyxl.styles import Font
        from openpyxl.utils import get_column_letter

        data = request.json or {}
        sheets = data.get('sheets') or []
        if not sheets:
            return jsonify({'status': 'error', 'error': 'No sheets provided'}), 400
        if not isinstance(sheets, list):
            return jsonify({'status': 'error', 'error': 'invalid_sheets',
                            'message': "'sheets' must be a list."}), 422

        # --- ÖH D29 / app-api-uc a2 · P16B4-24 · SATIR TAŞIYICISININ TİPİ -
        # ÖLÇÜLDÜ (``a2/once.json`` K2, taban ``4dc63c11``):
        #
        #   rows: "abc"   -> HTTP 200, sayfa [['v'], ['a'], ['b'], ['c']]
        #                    (metin KARAKTER BAŞINA bir satıra açıldı)
        #   rows: {"a":1} -> HTTP 200, sayfa [['v'], ['a']]
        #                    (sözlüğün ANAHTARI hücre oldu, değeri düştü)
        #   rows: 42      -> HTTP 500, "object of type 'int' has no len()"
        #                    (ham çözücü hatası kullanıcıya çıktı)
        #
        # Üçü de aynı sınıftır: ``for row in rows`` her yinelenebilirde
        # "çalışır", ama ürettiği tablo kullanıcının verisi DEĞİLDİR. Ucun
        # bir üst seviyesinde (``sheets``) doğru kapı ZATEN kurulu
        # (``invalid_sheets``, 422 — ölçüldü); bu, aynı sözleşmenin bir alt
        # seviyeye uygulanmasıdır. ``headers`` da aynı yoldan geçer: ölçümde
        # ``headers: "ab"`` başlığı iki harfli iki sütuna açıyordu.
        #
        # SAĞLIKLI ENVANTER GEVŞEMEZ (ÖK-22): ``rows`` verilmemişse
        # (``None``), boş listeyse ya da SKALER satırlar taşıyorsa
        # (``[1, 2, 3]`` -> her sayı kendi satırı) davranış bit-aynıdır;
        # kapı yalnız TAŞIYICININ kendisinin liste olmamasını reddeder.
        for _sf_i, _sf in enumerate(sheets):
            if not isinstance(_sf, dict):
                continue                      # bu kalemin konusu değil
            for _sf_ad in ('rows', 'headers'):
                _sf_deger = _sf.get(_sf_ad)
                if _sf_deger is None or isinstance(_sf_deger, (list, tuple)):
                    continue
                return jsonify({
                    'status': 'error',
                    'error': 'invalid_%s' % _sf_ad,
                    'message': (
                        f"'{_sf_ad}' of sheet {_sf_i} must be a list of "
                        f'rows; a '
                        f'{type(_sf_deger).__name__} was submitted. It was '
                        'previously iterated element by element, so a text '
                        'value became one spreadsheet row per character and '
                        'the exported workbook did not carry the submitted '
                        'data. Nothing was written.'),
                    'invalid_fields': [{
                        'field': 'sheets[%d].%s' % (_sf_i, _sf_ad),
                        'reason': 'not_a_list',
                        'received_type': type(_sf_deger).__name__,
                        'submitted': _clip_echo(_sf_deger, 64),
                    }],
                }), 422

        # --- ÖH D29 / app-api-uc a2 · P16B4-23 · TEMSİL EDİLEMEYEN HÜCRE --
        # ÖLÇÜLDÜ (``a2/once.json`` K2, taban ``4dc63c11``): gövde
        # ``rows: [[NaN], [Infinity], [-Infinity], [1.5]]`` HTTP 200 döndü
        # ve çalışma kitabının ilk sayfası ``[[v], [None], [None], [None],
        # [1.5]]`` oldu — üç hücrenin üçü de BOŞ indi.
        #
        # Excel'de boş hücre "veri yok" demektir; buradaki üç hücrenin
        # anlamı ise "hesap NaN/sonsuz verdi"dir. İki farklı hüküm aynı
        # görünüme iniyordu ve yanıtın hiçbir yerinde bunu söyleyen bir
        # alan yoktu (Doktrin 1: beyan bile YOKTU, sessiz ikame vardı).
        # Fail-closed: temsil edilemeyen bir sayı için dosya yayımlanmaz.
        #
        # Kapsam DAR: yalnız GERÇEK sayı olup sonlu OLMAYAN hücreler.
        # Metin, ``None``, bool ve sonlu sayılar aynen geçer (ölçülen
        # sağlıklı envanter bit-aynı kalır).
        for _sf_i, _sf in enumerate(sheets):
            if not isinstance(_sf, dict):
                continue
            for _sr_j, _sr in enumerate(_sf.get('rows') or []):
                _hucreler = (_sr if isinstance(_sr, (list, tuple)) else [_sr])
                for _sc_k, _sc in enumerate(_hucreler):
                    if (isinstance(_sc, (int, float))
                            and not isinstance(_sc, bool)
                            and not math.isfinite(_sc)):
                        return jsonify({
                            'status': 'error',
                            'error': 'unrepresentable_cell',
                            'message': (
                                'A spreadsheet cell cannot carry '
                                f'{_sc!r}: the workbook format has no such '
                                'value and the cell was previously written '
                                'as blank, which in a spreadsheet reads as '
                                '"no data" rather than "the computation '
                                'returned a non-finite number". Nothing '
                                'was written.'),
                            'invalid_fields': [{
                                'field': 'sheets[%d].rows[%d][%d]' % (
                                    _sf_i, _sr_j, _sc_k),
                                'reason': 'not_finite',
                                'submitted': repr(_sc),
                            }],
                        }), 422

        # D8: iş bütçesi. Tek satırlık kırpma yerine açık ret.
        budget = _xlsx_budget_error(sheets)
        if budget:
            body, code = budget
            return jsonify(body), code

        wb = Workbook()
        wb.remove(wb.active)
        header_font = Font(bold=True)
        for idx, sheet in enumerate(sheets):
            raw_title = str(sheet.get('name') or f'Sheet{idx + 1}')[:31]
            title = _safe_sheet_title(raw_title, idx)
            ws = wb.create_sheet(title=title)
            headers = sheet.get('headers') or []
            rows = sheet.get('rows') or []
            if headers:
                ws.append([_spreadsheet_safe(h) for h in headers])
                for cell in ws[1]:
                    cell.font = header_font
            for row in rows:
                ws.append([
                    (float(v) if isinstance(v, (int, float)) and not isinstance(v, bool)
                     else ('' if v is None else _spreadsheet_safe(v)))
                    for v in (row if isinstance(row, (list, tuple)) else [row])
                ])
            # Kolon genişliklerini başlığa göre kabaca ayarla
            for col_idx, h in enumerate(headers, start=1):
                ws.column_dimensions[get_column_letter(col_idx)].width = max(12, min(32, len(str(h)) + 4))

        buf = BytesIO()
        wb.save(buf)
        buf.seek(0)
        # D9 (2026-08-02): dosya adı ``safe_name``'den GEÇMİYORDU.
        # ÖLÇÜLDÜ: filename='../../../../etc/passwd.xlsx' isteği HTTP 200
        # döndü ve ad Content-Disposition başlığına aynen girdi. Diğer
        # export uçları (STEP/DXF/ZIP) zaten safe_name kullanıyordu; bu uç
        # atlanmıştı.
        # ÖH D23 a2 / P13B4-12: ``safe_name`` AD yarısıdır (yol kaçışı);
        # tip ve uzunluk kapısı DEĞER yarısının işidir ve yoktu
        # (ölçüldü: ``filename: true`` -> HTTP 200).
        # V3 SG-1 F-11: uzunluk reddi (InputError) genel dalda 500'dü.
        try:
            _xlsx_ad = input_guard.text(data, 'filename')
        except input_guard.InputError as _fn_exc:
            _fn_red = _field_types.input_error_body('filename', _fn_exc)
            return jsonify(_fn_red[0]), _fn_red[1]
        filename = safe_name(_xlsx_ad or 'hrma_export.xlsx',
                             default='hrma_export.xlsx')
        if not filename.lower().endswith('.xlsx'):
            filename += '.xlsx'
        return send_file(
            buf,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=filename,
        )
    except ImportError:
        return jsonify({
            'status': 'error',
            'error': 'openpyxl is not installed on the server; falling back to CSV is recommended.'
        }), 501
    except Exception as e:
        return jsonify({'status': 'error', 'error': str(e)}), 500


#: ÖH D29 / app-api-uc a2 (P16B4-20) — ``/api/export-pdf/<report_type>``
#: ucunun YAYIMLADIĞI rapor türleri. TEK KAYNAK (Doktrin 4): hem uç kapısı
#: hem aşağıdaki dallanma bu demeti okur. Küme uydurma değildir, ürünün
#: kendi düğmeleridir: ``liquid.html`` ve ``solid.html`` üç düğmeyle
#: (``summary``/``technical``/``complete``), ``advanced.html`` ikisiyle
#: (``summary``/``technical``) bu ucu çağırır; dördüncü bir tür üreten
#: hiçbir çağrı yeri yoktur (ölçüldü: ``a2/once.json`` K1 + arama).
PDF_REPORT_TYPES = ('summary', 'technical', 'complete')


@app.route('/api/export-pdf/<report_type>', methods=['POST'])
def export_pdf_report(report_type):
    """Export motor analysis as PDF report"""
    try:
        from hrma.export.pdf_generator import PDFReportGenerator

        data = request.json or {}
        motor_data = data.get('motor_data', {})
        analysis_results = data.get('analysis_results', {})
        charts = data.get('charts', [])

        # ÖH D18 / P13B1-02 (D17 devri, ihracat sahası) — HİÇ MOTOR
        # VERİLMEDİYSE RAPOR YAYIMLANMAZ.
        #
        # ÖLÇÜLDÜ (taban 9071a64, ``once.json`` E bölümü): BOŞ gövdeyle
        # (``{}``) üç rapor türü de HTTP **200** ve gerçek bir PDF
        # üretiyordu — ``summary`` 5.635 B, ``technical`` 5.397 B,
        # ``complete`` 6.351 B. Yani "motor analiz raporu" adında, hiçbir
        # motoru olmayan bir belge indiriliyordu. (Aynı kusur ``analysis``
        # türü için ``tests/test_d17_app_api_a1.py`` içinde xfail(strict)
        # bekçisiyle kayda geçmişti.)
        #
        # Kapı EN DAR biçimde kurulur: rapor bölümlerinin "veri yoksa N/A
        # bas, uydurma" davranışı ZATEN doğrudur ve bekçileri var
        # (``tests/test_pdf_analysis.py::TestNoFabricationWithoutData``);
        # dolayısıyla ELDE BİR ŞEY OLAN istek aynen geçer. Reddedilen tek
        # durum, isteğin hiçbir motor tanımlamamasıdır.
        if not isinstance(motor_data, dict) or not motor_data:
            return jsonify({
                'status': 'error',
                'error': 'no_motor_data',
                'message': ('Cannot export a motor analysis report: the '
                            'request carries no motor_data at all. A report '
                            'is not published for a motor that was never '
                            'submitted.'),
                'invalid_fields': [{
                    'field': 'motor_data',
                    'reason': ('not_an_object'
                               if not isinstance(motor_data, dict)
                               else 'empty'),
                }],
            }), 422

        # V3 SG-1 F-10: nesne olmayan ``analysis_results`` / dizi olmayan
        # ``charts`` rapor kurucusunda 500 veriyordu; tip girişte reddedilir.
        _pdf_tip = _field_types.first_field_type_error(
            data, {'analysis_results': 'object', 'charts': 'array'})
        if _pdf_tip is not None:
            return jsonify(_pdf_tip[0]), _pdf_tip[1]
        # ÖH V3 CAD · CADK D-T7-2 (15 Eki): motor_data'nın iç blokları da
        # sözlük olmalı (ihracat uçlarıyla AYNI kapı; ölçüm: bu uçta
        # heat_transfer_analysis.* ve structural_analysis.* metin gelince 500).
        _ic_blok = _reject_non_object_blocks(motor_data, 'motor_data')
        if _ic_blok is not None:
            return _ic_blok

        # Dalga 2: rapor bölümleri motor sonuçlarındaki GERÇEK analizlerle
        # beslenir (heat_transfer_analysis + structural_analysis + istekle
        # gelen safety özeti). Sabit değer enjekte edilmez.
        # ÖH Z5S / S7 (P9B3-09): İKİ besleme de ham çözücü yükünü görmeli.
        # Sıra önemli — yapılandırma zenginleştirmesi HAM ``analysis_results``
        # ile çalışır, bu yüzden bölümler kurulmadan ÖNCE hesaplanır.
        motor_data = _build_pdf_motor_data(motor_data, analysis_results)
        analysis_results = _build_pdf_analysis_sections(motor_data, analysis_results)

        # --- ÖH D31 / ihracat a1 · defter P9B3-21 -------------------------
        # BELGENİN GÜVENLİK BÖLÜMÜ ARTIK BESLENİYOR.
        #
        # ÖLÇÜLDÜ (taban ``9d70e9ed``; ``docs/scofield/raw/OH/D31/ihracat/
        # a1/once_p9b321.json``): ürünün PDF indiren dört yerinin hiçbiri
        # gövdeye ``safety`` koymuyor (4/4 ölçüldü), bu yüzden üç motor
        # tipinin GERÇEK sayfa yüküyle üretilen ``complete`` raporunda
        # güvenlik bölümü 3/3 koşumda "NOT EVALUATED IN THIS RUN" diyor ve
        # altı tehlike bloğunun 0'ı basılıyordu.
        #
        # Berke karar dosyası §4 seçeneği (b): analiz SUNUCUDA, raporun
        # render ettiği AYNI veriyle, TEK KEZ koşar. İkinci bir koşum
        # doğmadığı için Z4/P17B3-06'nın yasakladığı karışım oluşmaz.
        # İstekle ZATEN ``safety`` geldiyse ona dokunulmaz (eski sözleşme).
        # FAIL-CLOSED: zorunlu ölçü eksikse analiz koşulmaz, sayı
        # uydurulmaz; belge hangi alanın eksik olduğunu adıyla söyler.
        _istekten_safety = analysis_results.get('safety')
        if not isinstance(_istekten_safety, dict) or not _istekten_safety:
            from hrma.export.pdf_safety import build_pdf_safety
            _pdf_safety, _pdf_safety_kunye = build_pdf_safety(
                motor_data, analysis_results)
            analysis_results = dict(
                analysis_results,
                **({'safety': _pdf_safety} if _pdf_safety is not None
                   else {'safety_not_evaluated': _pdf_safety_kunye}))

        pdf_generator = PDFReportGenerator()

        # D5 (2026-08-02): indirme adı ``safe_name``'den GEÇMİYORDU — motor
        # adı ham olarak Content-Disposition'a giriyordu. Depodaki doğru
        # desen aynı dosyada zaten var (app.py:3403 vd., STEP/DXF/ZIP uçları).
        safe_motor_name = safe_name(motor_data.get('motor_name'),
                                    default='unnamed')

        # --- ÖH D29 / app-api-uc a2 · P16B4-20 · TÜR ADI UYDURULMAZ ------
        # ÖLÇÜLDÜ (``a2/once.json`` K1, taban ``4dc63c11``; dolu
        # ``motor_data``):
        #
        #   /api/export-pdf/summary   -> 200, motor_summary_FUZZBASE.pdf
        #   /api/export-pdf/technical -> 200, motor_technical_FUZZBASE.pdf
        #   /api/export-pdf/complete  -> 200, motor_complete_FUZZBASE.pdf,
        #                                7.109 B
        #   /api/export-pdf/HAYALET   -> 200, motor_complete_FUZZBASE.pdf,
        #                                7.109 B
        #   /api/export-pdf/analysis  -> 200, motor_complete_FUZZBASE.pdf,
        #                                7.109 B
        #
        # Var olmayan bir rapor türü sessizce ``complete``e düşüyordu:
        # bayt uzunluğu birebir aynı, indirilen dosyanın adı ``complete``in
        # adı. Kullanıcı istediğinden BAŞKA bir belge indirdiğini yalnız
        # dosya adına bakarak fark edebilirdi.
        #
        # DESEN İCAT EDİLMEDİ — kardeş uç ``/api/detailed-cad/<motor_type>``
        # aynı sınıfa ZATEN HTTP 400 + ``Unknown motor type`` veriyor
        # (ölçüldü: aynı koşumda ``kardes_detailed_cad_HAYALET`` -> 400).
        # Sınıf o kardeşten alınır; gövde P16B1-47'nin makine-okur
        # sözleşmesini taşır (alan + gerekçe + gönderilen + kabul edilenler).
        #
        # SIRA BİLEREK BÖYLE: bu kapı ``no_motor_data`` kapısından SONRA
        # koşar. Mevcut bekçi ``tests/test_d18_ihracat_a1.py``
        # (``TestP13B102PdfRaporu``) boş gövdeyi ``analysis`` türüyle de
        # gönderiyor ve ``no_motor_data`` bekliyor — isteğin hiç taşımadığı
        # motor, adı yanlış yazılmış türden önce gelir.
        if report_type not in PDF_REPORT_TYPES:
            return jsonify({
                'status': 'error',
                'error': 'unknown_report_type',
                'message': (
                    f"'{report_type}' is not a report type this endpoint "
                    'publishes, so no document was generated. Previously '
                    'the request silently produced the complete report and '
                    'the downloaded file was not the one that was asked '
                    'for.'),
                'invalid_fields': [{
                    'field': 'report_type',
                    'submitted': report_type,
                    'reason': 'unknown_report_type',
                    'accepted_values': list(PDF_REPORT_TYPES),
                }],
            }), 400

        # Generate different types of reports
        # (Tür kapısından sonra ``else`` dalına YALNIZ ``'complete'``
        #  ulaşır — kabul edilen küme ``PDF_REPORT_TYPES``tir.)
        if report_type == 'summary':
            pdf_bytes = pdf_generator.generate_quick_summary_report(motor_data, analysis_results)
            filename = f"motor_summary_{safe_motor_name}.pdf"
        elif report_type == 'technical':
            pdf_bytes = pdf_generator.generate_technical_report(motor_data, analysis_results, charts)
            filename = f"motor_technical_{safe_motor_name}.pdf"
        else:
            pdf_bytes = pdf_generator.generate_motor_analysis_report(
                motor_data, analysis_results, charts, 'complete'
            )
            filename = f"motor_complete_{safe_motor_name}.pdf"

        # Return PDF file
        pdf_buffer = io.BytesIO(pdf_bytes)
        pdf_buffer.seek(0)
        
        return send_file(
            pdf_buffer,
            mimetype='application/pdf',
            as_attachment=True,
            download_name=filename
        )
        
    except Exception as e:
        return jsonify({
            'status': 'error',
            'error': f'PDF generation failed: {str(e)}'
        }), 500

@app.route('/api/export-chart-pdf', methods=['POST'])
def export_chart_as_pdf():
    """Export individual chart as PDF"""
    try:
        from hrma.export.pdf_generator import PDFReportGenerator
        
        data = request.json
        chart_json = data.get('chart_data', '')
        # ÖH D23 a2 / P13B4-12: başlık PDF'e ve dosya adına giriyor;
        # sınırsız uzunlukta ve tip denetimsizdi (ölçüldü: 4/4 düşman
        # değer HTTP 200).
        # V3 SG-1 F-11: uzunluk reddi (InputError) genel dalda 500'dü.
        try:
            chart_title = input_guard.text(data, 'chart_title',
                                           default='Chart')
        except input_guard.InputError as _ct_exc:
            _ct_red = _field_types.input_error_body('chart_title', _ct_exc)
            return jsonify(_ct_red[0]), _ct_red[1]
        motor_name = data.get('motor_name', 'unnamed')
        
        pdf_generator = PDFReportGenerator()
        
        # Convert chart to image
        chart_image = pdf_generator.export_plotly_chart_to_image(chart_json)
        
        if not chart_image:
            return jsonify({
                'status': 'error',
                'error': 'Failed to convert chart to image'
            }), 400
        
        # ÖH D22 / defter P9B3-22 — SAHTE MOTOR RAPORU SÖKÜLDÜ.
        #
        # Eskiden burada ``motor_data = {'motor_name': ..., 'motor_type':
        # 'analysis'}`` diye UYDURMA bir motor kaydı kurulup
        # ``generate_motor_analysis_report(..., 'summary')`` çağrılıyordu.
        # ÖLÇÜLDÜ (taban ``b84b10a``, ``once.json`` P9B3-22): tek bir itki
        # eğrisi 102.803 baytlık, içinde "Executive Summary" / "Motor
        # Configuration" / "Performance" başlıkları ve 17 adet "N/A" olan
        # bir "motor analiz raporu" üretiyordu — hiç hesaplanmamış bir
        # motorun raporu. Grafik dışa aktarımı artık NE OLDUĞUNU söyleyen
        # kendi belgesini üretir (ÖK: uydurma yapılandırma tablosu yok).
        pdf_bytes = pdf_generator.generate_chart_only_report(
            chart_image, chart_title, motor_name
        )
        
        pdf_buffer = io.BytesIO(pdf_bytes)
        pdf_buffer.seek(0)
        
        # D5: iki bileşen de ``safe_name``'den geçer — grafik başlığı ve motor
        # adı kullanıcı girdisidir ve doğrudan Content-Disposition'a giriyordu.
        filename = 'chart_{}_{}.pdf'.format(
            safe_name(str(chart_title).lower().replace(' ', '_'),
                      default='chart'),
            safe_name(motor_name, default='unnamed'))

        return send_file(
            pdf_buffer,
            mimetype='application/pdf',
            as_attachment=True,
            download_name=filename
        )
        
    except Exception as e:
        return jsonify({
            'status': 'error',
            'error': f'Chart PDF export failed: {str(e)}'
        }), 500

#: ÖH D30 / app-api-uc a1 · P7B4-13 — CAD "features" listesinin ÜRETİLEN
#: veriye bağlanması. ``component_details`` blokları eksik alanları
#: ``'NOT AVAILABLE - ...'`` sentinelıyla ya da ``source: 'not available'``
#: ile işaretliyor; bir çizim özelliği ancak kendi bloğu GERÇEK veri
#: taşıyorsa iddia edilir.
_CAD_OZELLIK_KAYNAKLARI = (
    ('Injector hole patterns', 'injector'),
    ('Cooling channel layout', 'cooling'),
    ('Material callouts', 'materials'),
)


def _cad_blok_gercek_mi(blok):
    """Blok bu koşumdan GERÇEK veri taşıyor mu? (sentinel sayılmaz)"""
    if not isinstance(blok, dict):
        return False
    if str(blok.get('source', '')).strip().lower() == 'not available':
        return False
    for anahtar, deger in blok.items():
        if anahtar == 'source':
            continue
        if not str(deger).startswith('NOT AVAILABLE'):
            return True
    return False


def _cad_ozellik_listesi(component_details, iz_sayisi):
    """Yanıtta iddia edilecek çizim özellikleri (P7B4-13).

    Çizimin KENDİSİNE ait iki özellik (dış bileşenler, kesit) iz sayısı
    ölçüsüne bağlanır — 0 iz zaten 501'e düşer, ama sayı burada da
    hükmün dayanağıdır. Geri kalanlar bileşen bloklarından türer.
    """
    ozellikler = []
    if iz_sayisi:
        ozellikler += ['External component details',
                       'Internal structure cross-section']
    detay = component_details if isinstance(component_details, dict) else {}
    for ad, anahtar in _CAD_OZELLIK_KAYNAKLARI:
        if _cad_blok_gercek_mi(detay.get(anahtar)):
            ozellikler.append(ad)
    return ozellikler


@app.route('/api/detailed-cad/<motor_type>', methods=['POST'])
def generate_detailed_cad(motor_type):
    """Generate detailed engineering CAD visualization.

    ÖH Z5S / S7 — bu uçta İKİ kusur ölçüldü (28 Ağustos 2026, bu ağaçta):

    * **P16B4-18 (RFC 8259 dışı gövde).** ``chamber_diameter=NaN`` isteği
      HTTP 200 döndü ve yanıtın ``dimensions`` bloğuna ÇIPLAK ``NaN``
      belirteci yazıldı (``{"chamber_diameter": NaN, ...}``). Bu JSON
      değildir: tarayıcıda ``response.json()`` ``SyntaxError`` atar, panel
      sessizce boş kalır. Depoda ``sanitize_json_values`` VAR ve
      ``/api/export-complete-zip`` onu kullanıyordu; bu uç kullanmıyordu.
    * **Kapısızlık (P16B4-01 ile aynı sınıf).** BOŞ gövde 200 + 155.858 B
      döndürüyordu: üreticinin kendi yedek ölçüleri (Ø100 x 200 mm kamara,
      Ø50 mm boğaz) kullanıcının motoruymuş gibi çiziliyordu.

    Bu uç gövdeyi DÜZ okur (``data['chamber_diameter']``; sarmalayıcı
    ``motor_data`` yoktur — ``liquid.html`` düz sözlük yollar), bu yüzden
    geometri kapısı isteğin kendisine uygulanır.
    """
    try:
        from hrma.export.cad_visualization import DetailedCADGenerator

        data = request.json
        # Kapı ÜRETİCİDEN ÖNCE: aile sözleşmesiyle aynı (422 +
        # missing_export_geometry / invalid_export_geometry + alan adı).
        red = _reject_unexportable_geometry(data)
        if red is not None:
            return red

        cad_generator = DetailedCADGenerator()

        # ÖH D22 / defter OH-D19-03 — ÜRETİCİNİN ADLI REDDİ 422'YE ÇEVRİLİR.
        #
        # ``DetailedCADGenerator`` artık yayımlanmamış bir ölçü için sayı
        # uydurmuyor (ölçüldü: boş gövde Ø100 x 200 mm'lik uydurma bir motor
        # çiziyordu); ölçüyü ADIYLA reddediyor. Bu bir sunucu hatası DEĞİL,
        # bir GİRDİ hükmüdür — kapının kendi sözleşmesiyle (422 +
        # ``invalid_fields`` + alan adı) aynı biçimde bildirilir, 500 ile
        # değil. Bu ucun kapısı ``_reject_unexportable_geometry`` birincil
        # ölçüleri sorar; üreticinin ek olarak ihtiyaç duyduğu alan (ör.
        # ``nozzle_length``) buradan görünür hâle gelir.
        try:
            if motor_type == 'liquid':
                result = cad_generator.generate_liquid_motor_cad(data)
            elif motor_type == 'solid':
                result = cad_generator.generate_solid_motor_cad(data)
            else:
                result = None
        except ValueError as _red:
            _metin = str(_red)
            _alan = _metin.split('_not_available', 1)[0] if \
                '_not_available' in _metin else None
            if _alan is None:
                raise
            return jsonify({
                'status': 'error',
                'error': 'missing_export_geometry',
                'message': _metin,
                'invalid_fields': [{'field': _alan,
                                    'reason': 'not_published'}],
            }), 422

        if motor_type not in ('liquid', 'solid'):
            return jsonify({
                'status': 'error',
                'error': f'Unknown motor type: {motor_type}'
            }), 400

        # ÖH D16/kati (P16B4-06) — BOŞ ÇİZİMİ 'success' DİYE YAYIMLAMA.
        #
        # ÖLÇÜLDÜ (docs/scofield/raw/OH/D16/kati/a1/once.json, P16B4-06):
        # ``/api/detailed-cad/solid`` beş FARKLI motor için (Ø80 x 300 mm ⟷
        # Ø250 x 1500 mm, 40 ⟷ 120 bar, apcp ⟷ kndx) 8.939 baytlık
        # BAYT-AYNI yanıt döndürüyordu (aynı sha256); yalnız grain_type
        # değişince 5 bayt oynuyordu. Kök sebep uç değil ÜRETİCİ:
        # ``cad_visualization.generate_solid_motor_cad`` bir TASLAKtır —
        # gövdesinde "Will implement grain patterns, inhibitor, case
        # details" yazar ve alt grafik iskeletini boş döndürür. Ölçüm:
        # üretilen figürün iz (trace) sayısı 0, ``dimensions`` anahtarı hiç
        # yok. Yanıt buna rağmen ``status: 'success'`` ve "Detailed
        # engineering visualization with cross-section view" diyordu.
        #
        # FAIL-CLOSED: gövdede GERÇEKTEN geometri yoksa uç hüküm
        # KAZANMAMIŞTIR ve çizim yayımlanmaz. Kapı motor tipine göre değil
        # ÖLÇÜME göre çalışır: üretici bu tipi ilerde gerçekten çizmeye
        # başlarsa kapı kendiliğinden açılır, burada ikinci bir liste
        # bakımı gerekmez.
        try:
            _iz_sayisi = len(json.loads(result['plot_json']).get('data') or [])
        except Exception:
            _iz_sayisi = 0
        # ÖH D19 (defter P9B1-22) — ÜRETİCİ ARTIK KENDİ DURUMUNU SÖYLÜYOR.
        # Kapı ölçümde kalır (üretici çizmeye başlarsa kendiliğinden açılır),
        # ama üretici adlı bir ret beyan ettiyse O GEREKÇE taşınır: hüküm
        # tüketicinin çıkarımı değil üreticinin sözü olur.
        _uretici_reddi = result.get('error') if isinstance(result, dict) else None
        if _iz_sayisi == 0 or _uretici_reddi:
            return jsonify({
                'status': 'error',
                'error': 'cad_not_modelled',
                'motor_type': motor_type,
                'trace_count': _iz_sayisi,
                'generator_error': _uretici_reddi,
                'message': (
                    result.get('error_message') or
                    f'The detailed CAD generator produced no geometry for '
                    f'motor type {motor_type!r} (0 plot traces). This '
                    f'endpoint does not publish an empty drawing as a '
                    f'successful engineering CAD view.'),
            }), 501

        # NaN/Inf -> null (aile sözleşmesi). Kapı geçildiği için buraya sonlu
        # olmayan GİRDİ artık gelmez; yine de üreticinin türettiği bir sayı
        # sonsuza kaçarsa gövde geçerli JSON kalır.
        return jsonify(sanitize_json_values({
            'status': 'success',
            'cad_data': result['plot_json'],
            'component_details': result['component_details'],
            'dimensions': result.get('dimensions', {}),
            # Çizilen iz sayısı ÖLÇÜMDÜR ve yayımlanır: aşağıdaki 'features'
            # listesi üreticinin sabit iddiasıdır, bu sayı ise gerçekten ne
            # üretildiğinin denetlenebilir karşılığıdır.
            'trace_count': _iz_sayisi,
            'design_info': {
                'title': f'Engineering CAD: {motor_type.title()} Motor',
                'description': 'Detailed engineering visualization with cross-section view',
                # ÖH D30 / app-api-uc a1 · P7B4-13 — LİSTE SABİT DEĞİL,
                # ÜRETİLENDEN TÜRETİLİR. ÖLÇÜLDÜ (``a1/once.json`` /
                # ``sonra.json`` K10, taban ``ab7cf68b``,
                # ``/api/detailed-cad/liquid`` 200): ``component_details``
                # bloklarının tamamı *"NOT AVAILABLE - not produced by this
                # analysis run"* iken (enjektör ``hole_count``, soğutma
                # ``channel_count``, malzemeler, Isp) yanıt yine de
                # 'Injector hole patterns' ve 'Cooling channel layout'
                # ÇİZİLDİĞİNİ iddia ediyordu; aynı liste katı motorda da
                # değişmeden dönüyordu. İddia artık verisi olana kurulur
                # (doktrin 1: kazanılmamış hüküm yayımlanmaz) ve neye
                # dayandığı ``features_basis`` ile söylenir.
                'features': _cad_ozellik_listesi(
                    result.get('component_details'), _iz_sayisi),
                'features_basis': (
                    'Each entry is claimed only when the matching '
                    'component_details block carries real data from this '
                    'run; blocks marked NOT AVAILABLE are not listed.'),
            }
        }))

    except Exception as e:
        return jsonify({
            'status': 'error',
            'error': f'CAD generation failed: {str(e)}'
        }), 500

# ============================================================================
# Dalga 4A — Akış / Kinetik / Doğrulama / İş kuyruğu uç noktaları (2026-07-14)
# Mimari: docs/ANALIZ_PLATFORM_PLANI.md — sahte CFD/kinetik yerine hızlı
# gerçekçi modeller; UI seviyeleri Fast Screening / Engineering / High-Fidelity.
# ============================================================================

# /api/flow-analysis'in kabul ettiği seviyeler (High-Fidelity kinetik zinciri
# /api/kinetic-efficiency üzerinden yürür; akış modeli quasi-1D kalır)
FLOW_FIDELITY_LEVELS = ('fast', 'engineering')


#: ÖH D26 / app-api a4 (P7B4-05) — ``/api/flow-analysis``in SUNUCU TARAFI
#: VARSAYILANLARI, TEK KAYNAKTA. ÖLÇÜLDÜ (``a4/once.json`` K9): BOŞ gövde
#: HTTP 200 + tam bir quasi-1D akış çözümü alıyordu ve yanıtta yalnız
#: ``chamber_pressure``ın künyesi vardı; kalan SEKİZ uydurma sayı
#: (3000 K · γ 1,2 · MW 24 · D_t 0,02 m · 101.325 Pa · 45 istasyon ·
#: k 0,40 · T_w 800 K) gövdenin HİÇBİR yerinde geçmiyordu — kullanıcı
#: hiç tarif etmediği bir gazın, hiç ölçmediği bir boğazın akışına
#: kendi motorununki diye bakıyordu. Sayılar burada BİR KEZ yazılır:
#: hem okuma hem künye buradan besleniyor (ÖK-04), böylece künyedeki
#: değerle çözücüye giden değerin ayrışması mümkün değil.
FLOW_ANALYSIS_DEFAULTS = {
    'chamber_temperature': (3000.0, 'K',
        'the chamber temperature is a property of the propellant and the '
        'mixture ratio; it cannot be derived from the geometry'),
    'gamma': (1.2, '',
        'the ratio of specific heats is a property of the combustion '
        'products; the solver is a calorically perfect gas model'),
    'molecular_weight': (24.0, 'g/mol',
        'the molecular weight of the combustion products fixes R = '
        'R_universal / M and therefore c* and the thrust'),
    'throat_diameter': (0.02, 'm',
        'the throat diameter sets the mass flow and every station area '
        'ratio in the published profile'),
    'ambient_pressure': (101325.0, 'Pa',
        'the Summerfield separation criterion and the pressure thrust term '
        'are both defined against the ambient pressure'),
    'n_stations': (45, 'count',
        'the axial station count is a discretisation choice, not a '
        'property of the motor'),
    'separation_factor': (0.40, '',
        'the Summerfield k of the separation criterion'),
    'wall_temperature': (800.0, 'K',
        'the wall temperature enters the Bartz sigma correction and the '
        'convective flux q = h*(T_aw - T_w)'),
}


#: ÖH D27 / app-api a3 (OH-D26-20) — MOTORUN KENDİSİ olan ve bu yüzden
#: SUNUCU VARSAYILANIYLA DOLDURULAMAYACAK alanlar. Küme yeni bir liste
#: DEĞİL, ``FLOW_ANALYSIS_DEFAULTS``in bir alt kümesidir: ayrımın gerekçesi
#: o tablonun kendi üçüncü sütununda yazılıdır (bkz. ``flow_analysis``
#: gövdesindeki blok). ``chamber_pressure`` tabloda yoktur (künyesi
#: ``_pc_varsayilan_kunyesi`` ailesinden gelir) ama motorun ta kendisidir.
FLOW_REQUIRED_FIELDS = ('chamber_pressure', 'chamber_temperature', 'gamma',
                        'molecular_weight', 'throat_diameter',
                        'ambient_pressure')

#: Zorunlu alanların ``(birim, gerekçe)`` künyesi. Beşi TABLODAN okunur —
#: metin iki kez yazılmaz (Doktrin 4); ``chamber_pressure`` tabloda
#: olmadığı için gerekçesi burada ve YALNIZ burada durur.
_FLOW_REQUIRED_KUNYE = {
    ad: (FLOW_ANALYSIS_DEFAULTS[ad][1], FLOW_ANALYSIS_DEFAULTS[ad][2])
    for ad in FLOW_REQUIRED_FIELDS if ad in FLOW_ANALYSIS_DEFAULTS}
_FLOW_REQUIRED_KUNYE['chamber_pressure'] = (
    'bar',
    'the chamber pressure sets the whole isentropic expansion: every '
    'station pressure, the regime classification and the thrust are '
    'proportional to it')


def _flow_varsayilan_kunyesi(data):
    """GÖNDERİLMEYEN her alan için künye satırı (P7B4-05).

    ``_pc_varsayilan_kunyesi`` ile AYNI şema: ``field / value / unit /
    reason / message``. Kullanıcı alanı gönderdiyse satır ÜRETİLMEZ —
    sağlıklı yolun gövdesi bit-aynı kalır.

    ÖH D27 a3 (OH-D26-20): uçtaki kapı, motorun HİÇBİR tanımının
    gelmediği isteği reddeder. Buraya ulaşan istek en az bir motor alanı
    taşır, yani kalan alanlar için ÖK-19'un ikinci şıkkı (beyanlı
    varsayılan) yürürlüktedir ve künye HER alan için üretilmeye devam
    eder — ``FLOW_REQUIRED_FIELDS`` üyeleri DÂHİL. Alan-alan fail-closed
    borcu form katmanıyla birlikte kapanacaktır (ÖK-21; ``a3/rapor.md``).
    """
    kunye = []
    for ad, (deger, birim, gerekce) in FLOW_ANALYSIS_DEFAULTS.items():
        if (data or {}).get(ad) not in (None, ''):
            continue
        kunye.append({
            'field': ad,
            'value': deger,
            'unit': birim,
            'reason': 'not_supplied',
            'message': (
                '%s was not supplied; the quasi-1D solver was run at %s%s. '
                'That is an assumption, not a result - %s.'
                % (ad, deger, (' ' + birim) if birim else '', gerekce)),
        })
    return kunye


def _flow_bos_deger(value):
    """"Gönderilmedi" hükmünün TEK KAYNAĞI (P7B4-06 / P16B3-17).

    ``None`` (açık ``null``) ve yalnız boşluktan ibaret dize, alanın HİÇ
    gönderilmemesiyle AYNI hükmü alır — ``test_z5s_ham_500``
    ``TestYoklukIleAcikNullAyni`` sözleşmesi budur. Kural iki yerde
    yazılmaz: hem ``_flow_float`` (okuma) hem ``_flow_alan_verilmedi``
    (kapı) buradan okur, böylece kapının "verilmedi" saydığı bir alanı
    okuyucunun "verildi" sayması mümkün değildir.
    """
    return value is None or (isinstance(value, str) and value.strip() == '')


def _flow_alan_verilmedi(data, key):
    """Alan gövdede HİÇ yok mu? (anahtar yok / ``null`` / boş dize)

    ÖH D32 / arayuz-panel a2 (OH-D31-14) — alan-alan fail-closed kapısının
    yüklemi. ``_flow_bos_deger`` ile aynı kaynaktan beslenir.
    """
    return (data or {}).get(key, _MISSING) is _MISSING or _flow_bos_deger(
        (data or {}).get(key))


def _flow_float(data, key, default=None, absent_log=None):
    """İstek gövdesinden sayısal alan oku; bozuksa net İngilizce ValueError.

    ÖH Z5S / S2 (P7B4-06, P16B3-17) — AÇIK ``null`` ARTIK VARSAYILANA DÜŞER.
    Eski satır ``value = data.get(key, default)`` idi ve bu, "anahtar yok"
    ile "anahtarın değeri ``null``" arasındaki farkı SİLİYORDU: anahtar
    gönderilmemişse varsayılan geliyordu, ama açıkça ``null`` gönderilmişse
    ``None`` dönüyor ve varsayılan HİÇ uygulanmıyordu. Ölçüldü
    (``once_supurme.json``), üçü de bu uçtan:

    ======================================  ====  ==========================
    gövde                                   HTTP  sonuç
    ======================================  ====  ==========================
    ``{'n_stations': null}``                 500  ``int(None)`` — yakalanmamış
    ``{'chamber_pressure': null}``           500  ``NoneType * float``
    ``{'chamber_temperature': null}``        500  ``'>' str/NoneType``
    ``{'ambient_pressure': null}``           500  ``'<' NoneType/float``
    ======================================  ====  ==========================

    Yani alan HİÇ gönderilmese sağlıklı çalışan istek, alan BOŞ gönderilince
    500 alıyordu. Bu bir ürün yoludur: form alanı boş bırakıldığında
    ``advanced.html``in ``numById()`` yardımcısı açıkça ``null`` gönderir.

    ``''`` de aynı dala girer (eskiden ``float('')`` -> ``ValueError`` ->
    400). Varsayılanı olmayan alanlarda davranış değişmez: ``None`` döner.
    Düşüş SESSİZ DEĞİLDİR — ``absent_log`` verilirse alan adı oraya yazılır
    ve uç bunu ``inputs_treated_as_absent`` diye yayımlar.
    """
    value = data.get(key, _MISSING)
    if value is _MISSING:
        return default
    if _flow_bos_deger(value):
        if default is not None and absent_log is not None:
            absent_log.append(key)
        return default
    # --- ÖH D25 / P16B3-16 · BOOL TUZAĞI -------------------------------
    # ÖLÇÜLDÜ (taban ``cdf2106``, ``a4/once.json`` P16B3-16): dokuz uçlu
    # matriste ``true`` gönderilen alan BEŞ uçta 422 ``not_a_number``
    # alırken ``/api/flow-analysis``ta HTTP **400** ve şu gerekçeyi
    # alıyordu:
    #
    #   "ambient_pressure must be below chamber_pressure — otherwise
    #    there is no nozzle flow."
    #
    # Gerekçe YANLIŞTI: kullanıcı ortam basıncı hakkında hiçbir şey
    # söylememişti. ``float(True) == 1.0`` sessizce 1 bar'lık bir oda
    # kurmuş, 1 bar = 1e5 Pa da varsayılan ortam basıncının (101 325 Pa)
    # ALTINA düşmüştü; çözücünün doğru fizik denetimi böylece yanlış
    # alanı suçlayan bir mesaja dönüşüyordu. Kullanıcı düzeltmesi gereken
    # alanı (``chamber_pressure``) yanıttan ÖĞRENEMİYORDU.
    #
    # Kardeş kapı ``input_guard.num`` (``_json_float``in gövdesi) bool'u
    # zaten adıyla reddediyor; bu yardımcı o denetimi taşımıyordu. Yeni
    # eşik/sabit YOK — yalnız tip denetimi, kardeşle aynı cümleyle.
    # Denetim ``float()`` çağrısından ÖNCE olmak zorundadır: Python'da
    # ``isinstance(True, int)`` doğrudur ve ``float(True)`` istisna atmaz.
    if isinstance(value, bool):
        raise ValueError(
            f"Field '{key}' must be a number, got {value!r} (a boolean is "
            "not a measurement: JSON true would silently become 1).")
    try:
        value = float(value)
    except (TypeError, ValueError):
        raise ValueError(f"Field '{key}' must be a number, got {value!r}.")
    if not np.isfinite(value):
        raise ValueError(f"Field '{key}' must be finite.")
    return value


def _kinetic_evaluate_job(kwargs, progress_callback=None):
    """job_runner işi: kinetik verim değerlendirmesi (async yol).

    progress_callback runner tarafından enjekte edilir; değerlendirme tek
    parça olduğundan yalnız başla/bitti işaretlenir.
    """
    if progress_callback:
        progress_callback(0.1)
    result = kinetic_efficiency.evaluate(**kwargs)
    if progress_callback:
        progress_callback(1.0)
    return sanitize_json_values(result)


def _run_kinetic_chain(data, chamber_pressure_bar, throat_diameter,
                       nozzle_profile=None):
    """Ortak kinetik verim zinciri (flow-analysis + kinetic-efficiency).

    Returns (result_dict_or_None, note_or_None). Yakıt tanımı yoksa None +
    açıklayıcı not döner; değerlendirme hatası da not olarak raporlanır
    (akış analizi kinetik zincir yüzünden 500'e düşmez).
    """
    of_ratio = data.get('of_ratio')
    if of_ratio is None:
        return None, ("Kinetic-efficiency chain skipped: provide 'of_ratio' "
                      "(and optionally 'fuel_type', 'oxidizer_type') to "
                      "evaluate nozzle kinetic losses.")
    fidelity = str(data.get('kinetic_fidelity',
                            data.get('fidelity', 'engineering')))
    if fidelity not in KINETIC_FIDELITY_LEVELS:
        fidelity = 'engineering'
    fuel_composition = data.get('fuel_composition')
    if not isinstance(fuel_composition, dict) or not fuel_composition:
        fuel_composition = {str(data.get('fuel_type', 'htpb')): 100.0}
    try:
        result = kinetic_efficiency.evaluate(
            fuel_composition=fuel_composition,
            oxidizer_type=str(data.get('oxidizer_type', 'N2O')),
            of_ratio=float(of_ratio),
            chamber_pressure=chamber_pressure_bar,
            fidelity=fidelity,
            characteristic_length=_flow_float(data, 'characteristic_length'),
            throat_diameter=throat_diameter,
            nozzle_profile=nozzle_profile,
        )
        return sanitize_json_values(result), None
    except Exception as exc:
        return None, f"Kinetic-efficiency chain failed: {exc}"


@app.route('/api/flow-analysis', methods=['POST'])
def flow_analysis():
    """Quasi-1D compressible nozzle flow (successor of /api/cfd-analysis).

    Fidelity levels (Wave 4 architecture):
      fast        — isentropic summary: regime classification, CF/thrust,
                    throat state (no station arrays, no Bartz coupling).
      engineering — full 30-60 station arrays (P, M, T, rho, u, wall P),
                    axial Bartz h_g/q coupling, and the kinetic-efficiency
                    chain when the propellant definition is supplied
                    (of_ratio [+ fuel_type/oxidizer_type]).

    Units follow the repo convention: chamber_pressure in bar, temperatures
    in K, diameters in m, ambient_pressure in Pa.
    """
    data = request.get_json(silent=True) or {}

    fidelity = str(data.get('fidelity', 'engineering')).lower()
    if fidelity not in FLOW_FIDELITY_LEVELS:
        return jsonify({
            'status': 'error',
            'error': (f"fidelity must be one of {list(FLOW_FIDELITY_LEVELS)}; "
                      f"got '{fidelity}'. High-fidelity finite-rate kinetics "
                      "is served by POST /api/kinetic-efficiency."),
        }), 400

    # --- ÖH D27 / app-api a3 (OH-D26-20) · MOTOR UYDURULMAZ -----------
    # ÖLÇÜLDÜ (``a3/once.json`` K5, worktree ``a67dd68``): BOŞ gövde
    # (``{}``) HTTP **200** + ``status='success'`` + tam bir quasi-1D akış
    # çözümü alıyordu; yanıtta DOKUZ ``defaults_applied`` künyesi vardı
    # (D26 a4 / P7B4-05 onarımı — beyan çalışıyor ve ölçüldü).
    #
    # Beyan doğrudur ama YETMEZ (Doktrin 1): künye, uydurulan sayıyı
    # doğru yapmaz. Bu ucun yayımladığı hüküm — ayrılma rejimi, CF, itki,
    # boğaz durumu — DOĞRUDAN bu sayıların kendisidir; "3000 K varsaydım"
    # yazan bir gövdede duran itki, kullanıcının motorunun itkisi değildir.
    #
    # AYRIM UYDURMA DEĞİL, TABLONUN KENDİ GEREKÇESİNDEN OKUNUR
    # (``FLOW_ANALYSIS_DEFAULTS`` üçlüsünün üçüncü elemanı):
    #
    #   * MOTORUN KENDİSİ olan altı büyüklük — oda basıncı ve sıcaklığı,
    #     gamma, molekül ağırlığı, boğaz çapı, ortam basıncı — türetilemez
    #     ve varsayılamaz: ÖK-19'un "varsayılan KALKAR" şıkkı. Alan yoksa
    #     çözüm hiç başlatılmaz, 422 + alan adı döner.
    #   * MODEL/AYRIKLAŞTIRMA seçimi olan üçü — ``n_stations`` (bir
    #     ayrıklaştırma seçimi, motorun özelliği değil),
    #     ``separation_factor`` (Summerfield k'si, bir model katsayısı),
    #     ``wall_temperature`` (yalnız Bartz düzeltmesine girer, akış
    #     hükmünü kurmaz) — ÖK-19'un "``defaults_applied`` beyanıyla
    #     kalır" şıkkında BIRAKILIR. Bu üçünün varsayılanı bir motor
    #     iddiası değil, bir yöntem iddiasıdır ve künyede öyle durur.
    #
    # YENİ SAYI YAZILMADI, MEVCUT SAYI DEĞİŞTİRİLMEDİ: zorunlu altının
    # varsayılanı artık OKUNMUYOR (tabloda tarihsel kayıt olarak duruyor,
    # künye üreticisi onları atlıyor), kalan üçü aynı sayıyla aynı kanaldan
    # beyan edilmeye devam ediyor. Sağlıklı gövdenin yanıtı BİT-AYNI.
    #
    # KAPSAM — ÖLÇÜLEREK DARALTILDI (bu aşamanın kendi bulgusu):
    # Kapı ilk hâlinde "altı alandan biri bile eksikse 422" idi. Kapanış
    # koşumu o hâlin bedelini ölçtü: **55 kırmızı** (test_z5s_ham_500,
    # test_d24_app_api_a1, test_d25_app_api_a4, test_d26_app_api_a3/a4,
    # test_d23_app_api_a2, test_wave4b_contract, test_d15_termo_ucus_a3).
    # Kırmızıların çoğu kusuru koruyan bekçi DEĞİL: konuları başka
    # (istasyon sayısı bandı, bool tuzağı, ham-500 envanteri) ve hepsi
    # ``_flow_float``ın ÜRÜN YOLU sözleşmesine dayanıyor —
    # ``advanced.html``in ``numById()`` yardımcısı BOŞ BIRAKILAN her form
    # alanını açıkça ``null`` gönderir (bkz. ``_flow_float`` künyesi).
    # Alan-alan fail-closed, o form katmanının da düzeltilmesini
    # gerektirir; form katmanı bu dalgada ÖK-21 ile KİLİTLİ. Kapıyı tek
    # başına indirmek, kullanıcının bir kutuyu boş bırakmasını 422'ye
    # çeviren ama kutuyu doldurmasını sağlayamayan yarım bir onarım olurdu.
    #
    # İNDİRİLEN KAPI, ÖLÇÜLEN KUSURUN TAM KENDİSİDİR: motorun HİÇBİR
    # tanımı gelmediğinde çözüm üretilmez. Ölçüm (``a3/once.json`` K5)
    # zaten bunu söylüyordu: ``{}`` gövdesi HTTP 200 + tam çözüm.
    # Desen İCAT EDİLMEDİ — kardeş uç ``/api/uncertainty-analysis`` aynı
    # doktrini aynı şekille uyguluyor (``if not inputs: 422
    # incomplete_uncertainty_input`` — "belirsizlik analizi girdisi olmayan
    # bir motor için üretilemez"). Kısmî gövdede D26 a4'ün
    # ``defaults_applied`` beyanı yürürlükte kalır (ÖK-19 ikinci şıkkı).
    #
    # D27'nin KALAN BORCU (alan-alan fail-closed) ÖH D32 / arayuz-panel a2
    # ile ÖDENDİ; kapının kendisi aşağı, bütün biçim denetimlerinin ARDINA
    # taşındı (bkz. "OH-D31-14" bloğu). Gerekçe orada, ölçüsüyle.

    verilmedi = []
    try:
        chamber_pressure_bar = _flow_float(data, 'chamber_pressure', _CALCULATE_PC_DEFAULT_BAR,
                                           verilmedi)
        chamber_temperature = _flow_float(
            data, 'chamber_temperature',
            FLOW_ANALYSIS_DEFAULTS['chamber_temperature'][0], verilmedi)
        gamma = _flow_float(data, 'gamma',
                            FLOW_ANALYSIS_DEFAULTS['gamma'][0], verilmedi)
        molecular_weight = _flow_float(
            data, 'molecular_weight',
            FLOW_ANALYSIS_DEFAULTS['molecular_weight'][0], verilmedi)
        throat_diameter = _flow_float(
            data, 'throat_diameter',
            FLOW_ANALYSIS_DEFAULTS['throat_diameter'][0], verilmedi)
        exit_diameter = _flow_float(data, 'exit_diameter')
        expansion_ratio = _flow_float(data, 'expansion_ratio')
        ambient_pressure = _flow_float(
            data, 'ambient_pressure',
            FLOW_ANALYSIS_DEFAULTS['ambient_pressure'][0], verilmedi)
        # ÖH D29 a3 / P7B4-07 — KESİRLİ İSTASYON SAYISI SESSİZCE KIRPILMAZ.
        #
        # ÖLÇÜLDÜ (taban ``4dc63c11``, ``a3/once.json`` K11): bandın kapısı
        # D26'da kurulmuştu ama ``int(...)`` ondan ÖNCE koşuyordu, yani
        # kesirli değer önce tabana yuvarlanıp sonra denetleniyordu:
        #
        #   ``n_stations = 30,7``  -> HTTP **200**, yayımlanan ızgara
        #                             ``n_stations = 30`` (istenen değil,
        #                             uyarı yok, beyan yok)
        #   ``n_stations = 2,7``   -> HTTP 400 ama gerekçe "got **2**"
        #                             diyordu; kullanıcının gönderdiği sayı
        #                             reddin kendi metninde yanlış yazılıydı
        #
        # Kardeş kapı aynı dosyada zaten kurulu: ``/api/cfd/nozzle``
        # ``max_iterations`` için "must be a WHOLE number of iterations"
        # reddini veriyor. Sınıf aynı (ayrıklaştırma sayacı), hüküm de aynı
        # olur; yeni sabit ya da yeni bant YAZILMADI.
        _ns_ham = data.get('n_stations')
        n_stations_f = _flow_float(
            data, 'n_stations',
            FLOW_ANALYSIS_DEFAULTS['n_stations'][0], verilmedi)
        if (_ns_ham not in (None, '') and math.isfinite(n_stations_f)
                and float(n_stations_f) != int(n_stations_f)):
            return jsonify({
                'status': 'error',
                'error': ("'n_stations' must be a WHOLE number of stations; "
                          f'got {n_stations_f!r}. A fractional count was '
                          'silently truncated before this gate, so the grid '
                          'that got published was not the one you asked '
                          'for.'),
                'invalid_fields': [{
                    'field': 'n_stations',
                    'value': n_stations_f,
                    'reason': 'not_a_whole_number',
                    'accepted_range': [FLOW_N_STATIONS_MIN,
                                       FLOW_N_STATIONS_MAX],
                    'unit': '',
                }],
            }), 400
        n_stations = int(n_stations_f)
        separation_factor = _flow_float(
            data, 'separation_factor',
            FLOW_ANALYSIS_DEFAULTS['separation_factor'][0], verilmedi)
        wall_temperature = _flow_float(
            data, 'wall_temperature',
            FLOW_ANALYSIS_DEFAULTS['wall_temperature'][0], verilmedi)
        # GÖÇ (16 Ağu 2026): varsayılan ARTIK sabit DEĞİL. Alan gövdede
        # yoksa None geçilir; çözücü o zaman ölçülen sınır tabakası kesrini
        # yayımlar (yayımlanamıyorsa 1,5 % sabitine beyanla düşer). Burada
        # sabiti varsayılan olarak geçmek, her isteği "kullanıcı açıkça
        # 0.015 istedi" (source='user') hâline getirir ve göçü SESSİZCE
        # iptal ederdi. Kullanıcı alanı gönderirse üstünlük yine onundur.
        friction_loss_fraction = _flow_float(data, 'friction_loss_fraction')
    except ValueError as exc:
        # HTTP sınıfı 400 KORUNDU (bu ucun kurulu sözleşmesi; bekçi
        # ``tests/test_wave4a_contract.py::test_non_numeric_field_400``
        # ``error`` metninde alan adını arıyor). ÖH Z5S / S2 eki: alan adı
        # artık makine-okur biçimde de var, tahmin edilmesi gerekmiyor.
        alan = next((k for k in ('chamber_pressure', 'chamber_temperature',
                                 'gamma', 'molecular_weight',
                                 'throat_diameter', 'exit_diameter',
                                 'expansion_ratio', 'ambient_pressure',
                                 'n_stations', 'separation_factor',
                                 'wall_temperature',
                                 'friction_loss_fraction')
                     if f"'{k}'" in str(exc)), None)
        govde = {'status': 'error', 'error': str(exc)}
        if alan is not None:
            govde['invalid_fields'] = [{
                'field': alan,
                'reason': ('not_finite' if 'finite' in str(exc)
                           else 'not_a_number'),
            }]
        return jsonify(govde), 400

    # --- ÖH D29 / app-api-uc a2 · P16B3-32 · TERS BİRİM ŞÜPHESİ -----------
    # ÖLÇÜLDÜ (``a2/once.json`` K4, taban ``4dc63c11``): "birim ters
    # yazıldı" sınıfı BEŞ gövdede sınandı ve DÖRDÜ zaten kapılıydı —
    #
    #   /api/analysis/wall-profile  Pa yerine bar (2e6)   -> 422 out_of_range
    #   /api/water-hammer           m yerine mm (0,02)    -> 422 boru geometrisi
    #   /analyze_thermal_safety     mm yerine m (100)     -> 422 out_of_range
    #   /analyze_structural_safety  cidar >= yarıçap      -> 422 (karşı örnek)
    #   /api/flow-analysis          mm yerine m (30)      -> **HTTP 200**
    #
    # Yani kalemin "hiçbir uçta kapılı değil" başlığı bu ağaçta 4/5 için
    # ölçümle yanlıştır; AÇIK KALAN TEK AYAK bu uçtu. 30 metrelik bir boğaz
    # (kullanıcının 30 mm demek istediği), CF ve itki dahil tam bir akış
    # hükmü üretiyordu.
    #
    # YENİ EŞİK İCAT EDİLMEDİ (Doktrin 4): bant deponun KENDİ kanonik
    # tablosundan gelir — ``_ust_sinir_bandi`` ``motor_validator.limits``i
    # okur (``throat_diameter`` max 2,0 m, ``exit_diameter`` 5,0 m,
    # ``chamber_pressure`` 500 bar, ``chamber_temperature`` 5000 K) ve
    # kardeş uçlar (``/analyze_thermal_safety``,
    # ``/api/analysis/wall-profile``) aynı yardımcıyı zaten çağırıyor.
    # YALNIZ ÜST UÇ dayatılır: alt uç ``positive=`` işidir ve bu uçta
    # yoktur, dolayısıyla bu onarım hiçbir yeni alt-sınır reddi doğurmaz.
    # ÖK-21 KAPSAMI DIŞI: kapı GÖNDERİLMİŞ ve OKUNMUŞ sayının büyüklüğüne
    # bakar; boş bırakılan/``null`` alan (form katmanının konusu) hiç
    # incelenmez, o yol bit-aynı kalır.
    #
    # HTTP sınıfı 400: bu ucun KURULU sözleşmesi (``n_stations`` ve
    # ``wall_temperature`` bant retleri de 400 veriyor; bkz. hemen aşağısı).
    _bant_ihlali = _ust_sinir_ihlalleri(
        data, ('chamber_pressure', 'chamber_temperature',
               'throat_diameter', 'exit_diameter'))
    if _bant_ihlali:
        _bi = _bant_ihlali[0]
        return jsonify({
            'status': 'error',
            'error': (f"'{_bi['field']}' ({_bi['value']:g}) is above the "
                      f"largest value this product accepts for it "
                      f"({_bi['accepted_range'][1]:g}); a quantity that far "
                      'outside the band is usually the same number written '
                      'in the wrong unit. Nothing was solved.'),
            'invalid_fields': _bant_ihlali,
        }), 400

    # --- ÖH D24 / P16B3-13 · SESSİZ KELEPÇE VE ÜST UÇ SÖKÜLDÜ -------------
    # ÖLÇÜLDÜ (taban 88a29d3, ``a1/once.json`` P16B3-13):
    #
    #   {'n_stations': -5}        -> HTTP 200, 914 sayısal yaprak
    #   {'n_stations': 0}         -> HTTP 200, 914 sayısal yaprak
    #   {'n_stations': 1000000}   -> HTTP 200, 1754 sayısal yaprak
    #   {'wall_temperature': 1e9} -> HTTP 200 (oda 3000 K iken cidar 1e9 K)
    #
    # Çözücü ``NozzleFlow1D.__init__`` istasyon sayısını SESSİZCE kelepçeler
    # (``int(min(max(int(n), N_STATIONS_MIN), N_STATIONS_MAX))``): -5 ve
    # 1e6 istekleri 30 ve 60'a çevrilip hiçbir uyarı üretmeden tam bir
    # istasyon dizisi yayımlıyordu. Kullanıcı istediği ızgaranın
    # kullanılmadığını hiçbir alandan öğrenemiyordu. Yeni bant İCAT
    # EDİLMEDİ: kelepçenin KENDİ iki sabiti (``N_STATIONS_MIN/MAX``)
    # yukarıda ithal edilip kapıya bağlandı; alan gönderilmediğinde
    # varsayılan 45 bit-aynı kalır (kapı yalnız GÖNDERİLMİŞ değeri denetler).
    #
    # ``wall_temperature`` alt ucu çözücüde zaten kapalı ("must be positive
    # [K]", ölçüldü: -500 ve 0 -> 400). Kapalı olmayan ÜST uçtu: Bartz
    # bağıntısının sigma düzeltmesi T_w/T_c oranı üzerine kuruludur ve
    # taşınım akısı q = h·(T_aw − T_w) ile yazılır; cidar gazdan SICAKSA
    # akı işaret değiştirir, yani "lüle cidarı" diye çözülen şey artık gazı
    # ısıtan bir yüzeydir. Üst sınır bir ayar sayısı değil, isteğin KENDİ
    # ``chamber_temperature`` alanıdır — yeni sabit yazılmadı.
    if data.get('n_stations') not in (None, '') and not (
            FLOW_N_STATIONS_MIN <= n_stations <= FLOW_N_STATIONS_MAX):
        return jsonify({
            'status': 'error',
            'error': (f"'n_stations' must be between {FLOW_N_STATIONS_MIN} "
                      f"and {FLOW_N_STATIONS_MAX}; got {n_stations}. The "
                      'quasi-1D solver clamps the station count to that '
                      'range, so a value outside it would have been '
                      'silently replaced and the published grid would not '
                      'be the one you asked for.'),
            'invalid_fields': [{
                'field': 'n_stations',
                'value': n_stations,
                'reason': 'out_of_range',
                'accepted_range': [FLOW_N_STATIONS_MIN, FLOW_N_STATIONS_MAX],
                'unit': '',
            }],
        }), 400
    if (data.get('wall_temperature') not in (None, '')
            and wall_temperature is not None
            and chamber_temperature is not None
            and wall_temperature >= chamber_temperature):
        return jsonify({
            'status': 'error',
            'error': (f"'wall_temperature' ({wall_temperature:g} K) must be "
                      'below the chamber temperature '
                      f'({chamber_temperature:g} K). The Bartz sigma '
                      'correction is built on T_w/T_c and the convective '
                      'flux is q = h*(T_aw - T_w); a wall at or above the '
                      'gas temperature reverses that flux, so the run would '
                      'not describe a nozzle wall. Nothing was solved.'),
            'invalid_fields': [{
                'field': 'wall_temperature',
                'value': wall_temperature,
                'reason': 'wall_hotter_than_gas',
                'chamber_temperature_K': chamber_temperature,
                'unit': 'K',
            }],
        }), 400

    # === ÖH D32 / arayuz-panel a2 · OH-D31-14 · KAPI ALAN ALAN İNDİ ======
    #
    # D27 a3 kapıyı ``if not data`` hâlinde bırakmış ve KALAN BORCU
    # (alan-alan fail-closed) iki engelle künyelemişti: (1) ürün yolunda
    # ``advanced.html``in boş form alanını açıkça ``null`` göndermesi,
    # (2) ÖK-21'in form katmanını kilitlemesi. D31 / arayuz-panel a2 İKİ
    # ENGELİ DE KALDIRDI (OH-D26-20 + OH-D27-10): ``numById`` boş alanın
    # anahtarını gövdeden düşürüyor ve ``flow_panel.js``in altı zorunlu
    # alanı artık BOŞ doğuyor. Kapı bu yüzden bugün inebiliyor.
    #
    # ÖLÇÜLDÜ (``a2/once.json``, taban ``dd1dcddc``):
    #
    #   * TAM gövdeden zorunlu alanlardan BİRİ düşürüldüğünde (altı alan ×
    #     üç biçim: anahtar yok / açık null / boş dize) **18/18 istek HTTP
    #     200** ve tam bir hüküm (itki, C*, kütle debisi) dönüyordu.
    #   * ``{'fidelity': 'engineering'}`` — yani motorun HİÇBİR tanımını
    #     taşımayan, panelin SOĞUK hâlde gönderdiği gövde — HTTP 200 ve
    #     882,49 N itki dönüyordu. ``data`` boş olmadığı için D27'nin 422
    #     dalı ÜRÜN YOLUNDAN ERİŞİLEMEZDİ: güverte ``fidelity`` ve
    #     ``kinetic_fidelity`` seçicilerini HER istekte gönderir, dolayısıyla
    #     ``if not data`` hiçbir zaman doğru olmaz. Kanal vardı, kapı yoktu.
    #
    # KAPININ YERİ ÖLÇÜLEREK SEÇİLDİ: kapı, D24-D29'un kurduğu BİÇİM
    # denetimlerinin (bool tuzağı, ters birim bandı, kesirli istasyon
    # sayısı, cidar/gaz sıcaklığı) ARDINA konur. Böylece "gönderdiğin alan
    # sayı değil" hükmü "hiç göndermedin" hükmünün önünde kalır ve o
    # sözleşmelerin hiçbiri değişmez (ölçüldü: ``a2/sonra.json`` K5, altı
    # vakanın altısı da ÖNCE ile aynı HTTP sınıfı ve aynı alan adı).
    # Hiçbir şey ÇÖZÜLMEDEN önce dönüldüğü için fail-closed bozulmaz:
    # buradan sonrası yalnız ``NozzleFlow1D`` çağrısıdır.
    #
    # "Gönderilmedi" hükmü OKUYUCUYLA AYNI KAYNAKTAN gelir
    # (``_flow_alan_verilmedi`` -> ``_flow_bos_deger``), yani kapının
    # reddettiği bir alanı ``_flow_float``ın "verildi" sayması mümkün
    # değildir; ``test_z5s_ham_500::TestYoklukIleAcikNullAyni``in
    # "yokluk = açık null = boş dize" sözleşmesi de böylece korunur
    # (üç biçim de aynı 422'yi alır — ölçüldü, K1).
    _flow_eksik = [ad for ad in FLOW_REQUIRED_FIELDS
                   if _flow_alan_verilmedi(data, ad)]
    if _flow_eksik:
        return jsonify({
            'status': 'error',
            'error': 'incomplete_flow_input',
            'message': (
                'A quasi-1D nozzle solution cannot be produced from server '
                'defaults: the regime, CF, thrust and throat state that this '
                'endpoint publishes ARE these numbers. The missing fields '
                'describe the motor and its operating environment; they '
                'cannot be derived from the rest of the request and none was '
                'assumed on your behalf. Nothing was solved.'),
            'missing_fields': _flow_eksik,
            'invalid_fields': [
                {'field': ad,
                 'reason': 'required_not_supplied',
                 'unit': _FLOW_REQUIRED_KUNYE[ad][0] or None,
                 'basis': _FLOW_REQUIRED_KUNYE[ad][1]}
                for ad in _flow_eksik],
        }), 422

    # --- OH-D31-14 · İKİNCİ AYAK: LÜLE GEOMETRİSİ UYDURULMAZ -------------
    #
    # Eski üç satır şunu diyordu: "ne çıkış çapı ne genişleme oranı
    # verilmişse tipik ε=4 (küçük atmosferik motor) ile çalışılır".
    # ÖLÇÜLDÜ (``a2/once.json`` K3): altı zorunlu alanı DOLU ama geometrisi
    # boş bir gövde HTTP 200 ve 1981,64 N itki dönüyordu; yanıtın hiçbir
    # yerinde ε'nin varsayıldığına dair KÜNYE YOKTU
    # (``defaults_applied_expansion_ratio`` = false). Yani beyan bile
    # yoktu: sayı sessizce uyduruluyordu.
    #
    # Genişleme oranı MOTORUN KENDİSİDİR, bir yöntem seçimi değil:
    # ``FLOW_ANALYSIS_DEFAULTS``in kendi gerekçe sütununun ayırdığı iki
    # sınıftan birincisine girer (ÖK-19'un "varsayılan KALKAR" şıkkı).
    # Bu ucun yayımladığı CF, itki, çıkış Mach'ı ve ayrılma rejimi
    # DOĞRUDAN ε'nin kendisidir; ε=4 varsayan bir gövdede duran itki
    # kullanıcının motorunun itkisi değildir. Bu yüzden künyeli varsayılan
    # DEĞİL, kapı seçildi (Doktrin 1: beyan çözüm değildir).
    #
    # İki yazım da kabul edilir (çözücü ikisini de okur): ``expansion_ratio``
    # ya da ``exit_diameter``. Ret ikisini de adıyla anar; YENİ SAYI
    # YAZILMADI, silinen 4.0 başka bir yere taşınMADI.
    if exit_diameter is None and expansion_ratio is None:
        return jsonify({
            'status': 'error',
            'error': 'incomplete_flow_input',
            'message': (
                'The nozzle geometry was not supplied. The area ratio sets '
                'the exit Mach number, CF, the separation regime and the '
                'thrust this endpoint publishes, so it cannot be assumed on '
                'your behalf: send either an expansion_ratio or an '
                'exit_diameter (in metres). Nothing was solved.'),
            'missing_fields': ['expansion_ratio', 'exit_diameter'],
            'invalid_fields': [
                {'field': 'expansion_ratio',
                 'reason': 'required_one_of',
                 'accepted_alternatives': ['exit_diameter'],
                 'unit': None,
                 'basis': ('the nozzle area ratio Ae/At fixes the exit Mach '
                           'number and therefore CF, the separation '
                           'criterion and the published thrust')},
                {'field': 'exit_diameter',
                 'reason': 'required_one_of',
                 'accepted_alternatives': ['expansion_ratio'],
                 'unit': 'm',
                 'basis': ('the exit diameter is the same statement as the '
                           'area ratio, written as a length')},
            ],
        }), 422

    motor_data = {}
    if data.get('nozzle_type'):
        # sample_nozzle_inner_contour konik/bell ayrımını buradan okur
        motor_data['nozzle_angles'] = {
            'nozzle_type': str(data.get('nozzle_type'))}
    # ÖH D23 a2 / P13B4-12 — SESSİZ YEDEK SÖKÜLDÜ. Eski üç satır
    # ``except (TypeError, ValueError): pass`` ile çözülemeyen hazne
    # çapını YUTUYORDU: dört düşman değerin dördü de HTTP 200 dönüyor,
    # kullanıcı gönderdiği çapın hiç kullanılmadığını fark etmiyordu
    # (ölçüldü, ``once_supurme.json``). Fail-closed: çözülemeyen alan
    # adıyla reddedilir (aşağıdaki ``except ValueError`` -> 400).
    if data.get('chamber_diameter') is not None:
        try:
            motor_data['chamber_diameter'] = input_guard.num(
                data, 'chamber_diameter', unit='m')
        except input_guard.InputError as _cd_exc:
            # Bu uçta genel bir istisna dalı YOK; kapı kendi
            # 422'sini verir (eski desen sessizce ``pass``ti).
            return jsonify({
                'status': 'error',
                'error': 'invalid_input',
                'message': str(_cd_exc),
                'invalid_fields': [{
                    'field': 'chamber_diameter',
                    'reason': _kanonik_gerekce(data.get('chamber_diameter'),
                                               sayi_ise='out_of_range')}],
            }), 422

    try:
        solver = NozzleFlow1D(
            chamber_pressure=chamber_pressure_bar * 1e5,
            chamber_temperature=chamber_temperature,
            gamma=gamma,
            molecular_weight=molecular_weight,
            throat_diameter=throat_diameter,
            exit_diameter=exit_diameter,
            expansion_ratio=expansion_ratio,
            ambient_pressure=ambient_pressure,
            n_stations=n_stations,
            separation_factor=separation_factor,
            wall_temperature=wall_temperature,
            friction_loss_fraction=friction_loss_fraction,
            motor_data=motor_data,
        )
        flow = solver.solve(include_bartz=(fidelity == 'engineering'))
    except ValueError as exc:
        # --- ÖH D29 / app-api-uc a1 · P16B3-27 · ÇÖZÜCÜNÜN İÇ MESAJI -----
        # ÖLÇÜLDÜ (``a1/once.json`` K2, taban 4c27fa51; Pc 20 bar, boğaz
        # 30 mm, gamma 1,2, M 24 g/mol):
        #
        #   expansion_ratio = 8    -> HTTP 200 (sağlıklı yol)
        #   expansion_ratio = 1e6  -> HTTP 400, error = "f(a) and f(b) must
        #                             have different signs"
        #   expansion_ratio = 1e9  -> aynı metin
        #
        # Bu metin SciPy ``brentq``ün iç uyarısıdır; hangi alanın
        # reddedildiği, hangi sayının gönderildiği ve neyin çözülemediği
        # yazmıyor. Aynı uçtaki diğer 11 ret gerekçesi örnek nitelikte —
        # bu tek istisnaydı. Yığın izi (aynı ölçüm): ``solve`` ->
        # ``_classify_regime`` -> ``_mach_from_area(eps_exit,
        # supersonic=False)`` -> ``HeatTransferAnalyzer.
        # _mach_from_area_ratio`` -> ``brentq(f, 1e-6, 1-1e-9)``. Yani
        # başarısız olan, alan oranının SESSİZ ALTI (ses altı) kökünü
        # bulan tersine çevirmedir: istenen alan oranı, çözücünün kendi
        # ayraç aralığının dışına düşmüştür.
        #
        # EŞİK İCAT EDİLMEDİ ve BANT UYDURULMADI: kapı yeni bir üst sınır
        # koymaz, yalnız çözücünün KENDİ ayraç hatasını alan adıyla
        # yeniden ifade eder. Çözücünün ham metni ``solver_message``te
        # aynen durur — gizlenmez. Sayı üretilmez, yedek alan oranı
        # varsayılmaz; HTTP sınıfı (400) bu ucun kurulu sözleşmesidir ve
        # DEĞİŞMEZ, yalnız gövde makine-okur hâle gelir (kardeş desen:
        # D28 app-api a1 ``invalid_fields``).
        _ayrac_hatasi = 'must have different signs' in str(exc)
        if _ayrac_hatasi:
            _eps_alanlari = []
            if data.get('expansion_ratio') not in (None, ''):
                _eps_alanlari.append({
                    'field': 'expansion_ratio',
                    'submitted': data.get('expansion_ratio'),
                    'reason': 'area_ratio_outside_solver_inversion_bracket',
                    'unit': '',
                })
            if data.get('exit_diameter') not in (None, ''):
                _eps_alanlari.append({
                    'field': 'exit_diameter',
                    'submitted': data.get('exit_diameter'),
                    'reason': 'area_ratio_outside_solver_inversion_bracket',
                    'unit': 'm',
                })
            if not _eps_alanlari:
                _eps_alanlari.append({
                    'field': 'throat_diameter',
                    'submitted': data.get('throat_diameter'),
                    'reason': 'area_ratio_outside_solver_inversion_bracket',
                    'unit': 'm',
                })
            return jsonify({
                'status': 'error',
                'error': 'unsolvable_area_ratio',
                'message': (
                    'The nozzle area ratio implied by this request could '
                    'not be inverted: the quasi-1D solver locates the '
                    'subsonic and supersonic Mach roots of A/A* by '
                    'bracketing, and this area ratio falls outside the '
                    'bracket, so no station could be resolved. Nothing was '
                    'published and no substitute area ratio was assumed. '
                    'Send an expansion_ratio (or exit_diameter) in the '
                    'range a real nozzle occupies.'),
                'invalid_fields': _eps_alanlari,
                'solver_message': str(exc),
            }), 400
        # Modülün fizik doğrulamaları (Pa >= Pc, gamma bandı...) — net 400
        return jsonify({'status': 'error', 'error': str(exc)}), 400
    except Exception as exc:
        return jsonify({'status': 'error', 'error': str(exc)}), 500

    kinetic_result = None
    kinetic_note = None
    if fidelity == 'fast':
        # İzantropik özet: istasyon dizileri taşınmaz (hızlı tarama seviyesi)
        flow.pop('stations', None)
        kinetic_note = ("Fast Screening level: station arrays and the "
                        "kinetic-efficiency chain require the Engineering "
                        "fidelity level.")
    else:
        nozzle_profile = None
        stations = flow.get('stations') or {}
        if stations.get('x_mm'):
            # Yüksek doğruluk kinetiği için quasi-1D profil (mm -> m)
            nozzle_profile = {
                'x': [v / 1000.0 for v in stations['x_mm']],
                'T': stations['temperature_K'],
                'P': stations['pressure_Pa'],
                'u': stations['velocity_m_s'],
            }
        kinetic_result, kinetic_note = _run_kinetic_chain(
            data, chamber_pressure_bar, throat_diameter,
            nozzle_profile=nozzle_profile)

    response = {
        'status': 'success',
        'fidelity': fidelity,
        'fidelity_levels': list(FLOW_FIDELITY_LEVELS),
        'flow': sanitize_json_values(flow),
        'kinetic_efficiency': kinetic_result,
    }
    if kinetic_note:
        response['kinetic_note'] = kinetic_note
    # ÖH Z5S / S2: açık ``null``/``""`` gelen alanlar "verilmedi" sayılıp
    # belgelenmiş varsayılana düştü — sessiz kalmaz. Sağlıklı yolun gövdesi
    # BİT-AYNI (alan yalnız gerçekten düşüş olduğunda eklenir).
    if verilmedi:
        response['inputs_treated_as_absent'] = verilmedi
    # ÖH D21 / OH-D19-09 — ``chamber_pressure`` HİÇ GÖNDERİLMEDİĞİNDE de
    # sessiz kalmaz. ``inputs_treated_as_absent`` yalnız AÇIK ``null``/``""``
    # dalını yakalıyordu (``_flow_float``: anahtar yoksa ``absent_log``a
    # yazılmadan varsayılan döner), yani "anahtarı hiç göndermeyen" istek
    # 20 bar'da çözülüp bunu yanıttan öğrenemiyordu. Künye ``/calculate``
    # ile AYNI üreticiden gelir; alan yalnız düşüş olduğunda eklenir, sayı
    # gönderildiğinde gövde BİT-AYNI kalır.
    _pc_kunye_akis = []
    _pc_varsayilan_kunyesi(data, _pc_kunye_akis)
    # ÖH D26 a4 / P7B4-05: kalan SEKİZ varsayılan da AYNI kanaldan, AYNI
    # şemayla. Basınç künyesi listenin başında kalır (kardeş uçlarla aynı
    # üretici); ötekiler tek kaynaktan (``FLOW_ANALYSIS_DEFAULTS``) gelir.
    _pc_kunye_akis += _flow_varsayilan_kunyesi(data)
    if _pc_kunye_akis:
        response['defaults_applied'] = _pc_kunye_akis
    return jsonify(response)


@app.route('/api/kinetic-efficiency', methods=['POST'])
def kinetic_efficiency_analysis():
    """Tiered nozzle kinetic-efficiency analysis (successor of
    /api/kinetic-analysis).

    Fidelity: 'fast' (equilibrium reference), 'engineering' (JANNAF-style
    Damköhler correlation), 'high_fidelity' (Cantera finite-rate along a
    nozzle T(x), P(x) profile; graceful fallback to engineering — the
    'fidelity_used' field always reports what actually ran).

    Special modes:
      {'probe': true}  — capability probe only: reports whether the
                         high-fidelity path is available (no heavy work).
      {'async': true}  — queue the evaluation on the job runner; returns
                         202 with a job id to poll via GET /api/jobs/<id>.
    """
    data = request.get_json(silent=True) or {}

    # --- Yetenek sondası: Cantera + reaksiyonlu mekanizma var mı? ---
    # Panel, High-Fidelity seçeneğini fidelity_used alanından tespit eder.
    if data.get('probe'):
        available = False
        detail = 'Cantera is not installed'
        if KINETIC_CANTERA_AVAILABLE:
            try:
                # Modülün kendi mekanizma çözücüsü (önbellekli); reaksiyonsuz
                # termo-dosyalar (nasa_gas.yaml) elenir.
                kinetic_efficiency._get_kinetics_gas()
                available = True
                detail = (f"Cantera mechanism "
                          f"'{kinetic_efficiency._kin_mech_name}' ready")
            except Exception as exc:
                detail = str(exc)
        levels = ['fast', 'engineering'] + (['high_fidelity'] if available
                                            else [])
        return jsonify({
            'status': 'success',
            'probe': True,
            'fidelity_requested': 'high_fidelity',
            'fidelity_used': 'high_fidelity' if available else 'engineering',
            'cantera_available': bool(KINETIC_CANTERA_AVAILABLE),
            'fidelity_levels': levels,
            'detail': detail,
        })

    # ÖH D23 a2 / P13B4-12: seçim listesi TEK KAYNAKTAN
    # (``KINETIC_FIDELITY_LEVELS``) okunur ve kapı deponun kendi
    # ``input_guard.choice``'udur; aşağıdaki 400 gövdesi (panelin
    # okuduğu metin) DEĞİŞMEDEN korunur.
    # --- ÖH D26 / app-api a4 · P7B4-08 — AYNI KAVRAM, TEK SÖZLEŞME ------
    # ÖLÇÜLDÜ (``a4/once.json`` K10, bu worktree): ``fidelity`` alanı iki
    # kardeş uçta iki ayrı sözleşmeye tabiydi::
    #
    #   gövde                     /api/flow-analysis  /api/kinetic-efficiency
    #   fidelity='peynir'                400                 400
    #   fidelity=''                      400            **200**, sessiz düşüş
    #
    # İkinci satır kalemin özüdür: boş dize GÖNDERİLMİŞ bir seçimdir ve
    # ``input_guard.choice`` onu sessizce varsayılana çeviriyordu. Üstelik
    # yanıt ``fidelity_requested = 'engineering'`` yazıyordu — kullanıcının
    # HİÇ yazmadığı bir seviye, "istediğin buydu" diye geri okunuyordu
    # (ölçüldü: gönderilen ``''``, yayımlanan ``'engineering'``). Alan
    # GÖNDERİLMİŞSE artık kardeş ucun kapısından geçer; HİÇ
    # gönderilmediğinde iki uçta da varsayılan uygulanır (bit-aynı).
    #
    # Kapı deponun KENDİ ``input_guard.choice``udur (ÖK-20/ADIM 3 kapsamı
    # ``tests/test_d23_app_api_a2.py::TestKapsamKilidi`` ile kilitli;
    # çağrı SÖKÜLMEZ). Eklenen tek şey, ``choice``un "boş = verilmedi"
    # sayan ``_missing`` dalının bu uçta SESSİZ düşüşe dönüşmesini
    # engellemek: alan GÖNDERİLMİŞ ama boşsa seçim yapılmamış değil,
    # OKUNAMAMIŞTIR.
    _fid_ham = (data or {}).get('fidelity', _MISSING)
    _fid_bos = (_fid_ham is not _MISSING
                and (not isinstance(_fid_ham, str)
                     or not _fid_ham.strip()))
    try:
        fidelity = input_guard.choice(
            data, 'fidelity', KINETIC_FIDELITY_LEVELS,
            default='engineering')
    except input_guard.InputError:
        fidelity = None
    if _fid_bos or fidelity not in KINETIC_FIDELITY_LEVELS:
        return jsonify({
            'status': 'error',
            'error': (f"fidelity must be one of "
                      f"{list(KINETIC_FIDELITY_LEVELS)}; got "
                      f"'{_clip_echo(_fid_ham, 64)}'."),
            # Kullanıcının GERÇEKTEN yazdığı değer, yankı olarak.
            'fidelity_requested': _clip_echo(_fid_ham, 64),
            'invalid_fields': [{'field': 'fidelity',
                                'reason': 'not_in_allowed_choices',
                                'allowed': list(KINETIC_FIDELITY_LEVELS)}],
        }), 400

    try:
        of_ratio = _flow_float(data, 'of_ratio')
        chamber_pressure_bar = _flow_float(data, 'chamber_pressure', _CALCULATE_PC_DEFAULT_BAR)
        characteristic_length = _flow_float(data, 'characteristic_length')
        throat_diameter = _flow_float(data, 'throat_diameter')
    except ValueError as exc:
        return jsonify({'status': 'error', 'error': str(exc)}), 400
    if of_ratio is None:
        return jsonify({
            'status': 'error',
            'error': ("Field 'of_ratio' is required (oxidizer-to-fuel mass "
                      "ratio, e.g. 6.0 for N2O/HTPB)."),
        }), 400

    fuel_composition = data.get('fuel_composition')
    if not isinstance(fuel_composition, dict) or not fuel_composition:
        fuel_composition = {str(data.get('fuel_type', 'htpb')): 100.0}

    kwargs = {
        'fuel_composition': fuel_composition,
        'oxidizer_type': str(data.get('oxidizer_type', 'N2O')),
        'of_ratio': of_ratio,
        'chamber_pressure': chamber_pressure_bar,
        'fidelity': fidelity,
        'characteristic_length': characteristic_length,
        'throat_diameter': throat_diameter,
        'nozzle_profile': data.get('nozzle_profile'),
    }

    if data.get('async'):
        # Uzun sürebilecek yol (Cantera BDF) iş kuyruğuna atılır; istemci
        # GET /api/jobs/<id> ile yoklar (job_runner sözleşmesi).
        job_id = job_runner.submit(_kinetic_evaluate_job, kwargs)
        return jsonify({
            'status': 'queued',
            'job_id': job_id,
            'poll_url': f'/api/jobs/{job_id}',
        }), 202

    try:
        result = kinetic_efficiency.evaluate(**kwargs)
    except ValueError as exc:
        return jsonify({'status': 'error', 'error': str(exc)}), 400
    except Exception as exc:
        return jsonify({'status': 'error', 'error': str(exc)}), 500

    payload = {'status': 'success'}
    payload.update(sanitize_json_values(result))
    # Kitap uyum B16, 2. tur (Ş-7): kinetik verim değerlendirmesi süreç
    # genelinde PAYLAŞILAN bir analizörle koşar (modül düzeyi örnek); giriş
    # durumunu ona yazmak eşzamanlı isteklerde yarış doğururdu. Değerlendirme
    # bu yüzden VARSAYILAN N₂O giriş durumunda yapılır ve bu ADIYLA beyan
    # edilir (N₂O dışı oksitleyicide giriş durumu ayarlanamaz; alan yok).
    if str(kwargs.get('oxidizer_type') or '').strip().lower() == 'n2o':
        from hrma.engines.oxidizer_inlet import (
            inlet_request_from_payload, unapplied_inlet_state_declaration)
        payload['oxidizer_inlet_state'] = unapplied_inlet_state_declaration(
            kwargs.get('oxidizer_type'), inlet_request_from_payload(data),
            'the kinetic-efficiency evaluator uses one process-wide shared '
            'equilibrium analyzer, which stays at the default inlet state')
    # ÖH D21 / OH-D19-09 — kardeş uçla (``/api/flow-analysis``) aynı künye:
    # oda basıncı gönderilmediyse tarama VARSAYILANDA koştu ve bu ADIYLA
    # yayımlanır. Sayı gönderildiğinde gövde BİT-AYNI kalır.
    _pc_kunye_kin = []
    _pc_varsayilan_kunyesi(data, _pc_kunye_kin)
    if _pc_kunye_kin:
        payload['defaults_applied'] = _pc_kunye_kin
    return jsonify(payload)


#: ÖH D27 a4 / P7B4-21 — job hata metninin başındaki Python TİP ADI öneki
#: (``ValueError: ...``, ``_UQAnalysisError: ...``). Senkron yol ``str(exc)``
#: yazdığı için ön ek TAŞIMAZ; iki yol aynı hatayı aynı biçimde yayımlar.
#: (``re`` bu modülde yalnız fonksiyon içinde içe aktarılıyor; küresel içe
#: aktarma eklemek yerine ayrıştırma elle yapılır.)
_JOB_TIP_SONEKLERI = ('Error', 'Exception')


def _job_hata_metni(ham):
    """``'_UQAnalysisError: mesaj'`` -> ``'mesaj'``. Ön ek yoksa BİT-AYNI."""
    if not isinstance(ham, str) or ':' not in ham:
        return ham
    onek, _, kalan = ham.partition(':')
    ad = onek.strip()
    if (ad and (ad[0].isalpha() or ad[0] == '_')
            and all(k.isalnum() or k == '_' for k in ad)
            and ad.endswith(_JOB_TIP_SONEKLERI)):
        return kalan.lstrip()
    return ham


@app.route('/api/jobs/<job_id>', methods=['GET'])
def get_job_status(job_id):
    """Poll a queued analysis job (job_runner contract).

    States: queued | running | done | error. A finished job carries
    'result'; a failed one carries 'error'. Records expire after the
    runner TTL (default 1 h) and then return 404.
    """
    try:
        status = job_runner.status(job_id)
    except KeyError:
        return jsonify({
            'status': 'error',
            'error': f'Unknown or expired job id: {job_id}',
        }), 404
    # --- ÖH D27 a4 / P7B4-21 · DIŞ ZARF İŞİN HÜKMÜNÜ YALANLAYAMAZ -------
    # ÖLÇÜLDÜ (taban ``8f083ca0``, ``a4/once.json`` K5): başarısız bir iş
    # bu uçtan **HTTP 200 + ``status: 'success'``** ile dönüyordu; işin
    # gerçek durumu iki kat aşağıda, ``job.state = 'error'`` idi. ``fetch``
    # sarmalayıcıları ``response.ok`` ve ``status`` alanına bakar — panel
    # başarısız bir koşuyu "başarılı" diye okuyup boş bir sonucu çizmeye
    # kalkar. Beyan bir çözüm değildir, ama BURADA beyanın kendisi yalandı.
    #
    # ``status`` artık işin KENDİ durumundan türer (tek kaynak: job_runner
    # sözleşmesinin ``state`` alanı). Yoklama başarılıdır — kayıt bulundu —
    # bu yüzden HTTP 200 KORUNUR: 4xx/5xx, "iş bulunamadı"yı (404) "iş
    # başarısız bitti"den ayıramaz hâle getirirdi ve yoklama döngüsünü
    # kırardı. Yalan olan sayı değil damgaydı; damga düzeltildi.
    #
    # ``error`` metnindeki PYTHON TİP ADI ön eki de kalkar: aynı ölçümde
    # gövde ``'_UQAnalysisError: Nominal referans hesabi basarisiz: ...'``
    # taşıyordu. Tip adı kullanıcının okuyacağı bir şey değildir ve senkron
    # yol onu ZATEN yazmıyor (``str(exc)``); iki yol aynı hatayı iki
    # biçimde yayımlayamaz.
    _durum = sanitize_json_values(status)
    if isinstance(_durum, dict):
        _ham_hata = _durum.get('error')
        if isinstance(_ham_hata, str):
            _durum['error'] = _job_hata_metni(_ham_hata)
    _is_durumu = (_durum or {}).get('state')
    return jsonify({
        'status': 'error' if _is_durumu == 'error' else 'success',
        'job': _durum,
    })


@app.route('/api/validation/upload-csv', methods=['POST'])
def validation_upload_csv():
    """Parse a user static-fire thrust CSV and (optionally) compare it with
    the HRMA prediction.

    Accepts either:
      - a plain-text body (text/csv, text/plain): parse only, or
      - JSON {'csv_text': str, 'predicted_curve': {'time': [...],
        'thrust': [...]}} — parse + quantitative comparison (total impulse,
        peak/mean thrust, NFPA 1125 burn time, RMSE/NRMSE, English
        assessment).
    """
    predicted_curve = None
    csv_text = None
    if request.is_json:
        data = request.get_json(silent=True) or {}
        csv_text = data.get('csv_text')
        predicted_curve = data.get('predicted_curve')
    else:
        csv_text = request.get_data(as_text=True)

    if not isinstance(csv_text, str) or not csv_text.strip():
        return jsonify({
            'status': 'error',
            'error': ("No CSV content provided. Send the file as a "
                      "text/csv body, or as JSON {'csv_text': '...'} with "
                      "an optional 'predicted_curve' {'time', 'thrust'}."),
        }), 400

    # --- ÖH D32 / P7B4-23 + OH-D31-12 — KANONİK SATIR BANDI ---------------
    # ÖLÇÜLDÜ (a2 ``once.json`` K1/K3, taban ``dd1dcddc``): bu uç satır
    # ekseninde SINIRSIZDI — 600 000 satır HTTP 200, 0,696 s, 8,42 MiB
    # yanıt; tek sınır ``MAX_CONTENT_LENGTH`` idi ve o BAYT tavanı ölçülen
    # 18,0 bayt/satır ile ~1,86 milyon satıra denk düşüyordu.
    #
    # Bant burada DEĞİL, ``parse_thrust_csv``ın yanında tanımlıdır; uç onu
    # okur. Kapı ayrıştırmadan ÖNCE çalışır: banda sığmayan bir yükü önce
    # milyonlarca satır ayrıştırıp sonra reddetmek, korumak istediğimiz
    # belleği zaten harcamak olurdu. Sayım ÜST sınırdır (boş satırlar
    # sayılmaz, başlık/birim payı düşülür), yani banda sığan hiçbir dosya
    # yanlışlıkla kapanmaz. Aşım SESSİZCE KIRPILMAZ: hangi sınırın hangi
    # değerle aşıldığı makine-okur biçimde döner (413 = "istek fazla
    # büyük"; deponun kendi bütçe sözleşmesi, bkz. ``_xlsx_budget_error``).
    _bant_hatasi = _csv_satir_bandi_hatasi(_csv_aday_satir(csv_text))
    if _bant_hatasi is not None:
        return jsonify(_bant_hatasi), 413

    # İKİNCİ GİRDİ EKSENİ (P7B4-23'ün JSON ayağı). Bu uç yalnız CSV
    # gövdesi değil, JSON biçiminde ``predicted_curve`` dizisi de alıyor.
    # ÖLÇÜLDÜ (a2 ``once_pc.json``, taban ``dd1dcddc`` VE bu worktree'nin
    # CSV onarımı sonrası hâli): 300 000 noktalık bir tahmin eğrisi HTTP
    # 200 alıyor ve karşılaştırma hesaplanıyordu — CSV bandı kapatılınca
    # sınırsız kalan tek eksen buydu. AYNI bant, AYNI tek kaynak; yalnız
    # ret künyesinin ``field``ı hangi eksenin aşıldığını söyler.
    if predicted_curve is not None:
        _bant_hatasi = _csv_satir_bandi_hatasi(
            _egri_nokta_sayisi(predicted_curve), field='predicted_curve')
        if _bant_hatasi is not None:
            return jsonify(_bant_hatasi), 413

    try:
        parsed = parse_thrust_csv(csv_text)
    except ValueError as exc:
        return jsonify({'status': 'error', 'error': str(exc)}), 400

    # Ayrıştırma sonrası KESİN sayım. Yukarıdaki kapı ayrıştırma maliyetini
    # sınırlar ama ÜST sınıra baktığı için bandın hemen üstündeki birkaç
    # satırı geçirebilir (başlık/birim payı kadar); gerçek satır sayısı
    # ancak burada bilinir ve bant TAM olarak burada kapanır. İki kapı da
    # AYNI tek kaynağı okur.
    _bant_hatasi = _csv_satir_bandi_hatasi(parsed['n_points'])
    if _bant_hatasi is not None:
        return jsonify(_bant_hatasi), 413

    parsed_out = {
        'time': parsed['time'].tolist(),
        'thrust': parsed['thrust'].tolist(),
        'n_points': parsed['n_points'],
        'warnings': parsed['warnings'],
        # ÖH D16 / P10B2-05: hangi birimin okunduğu ve hangi çarpanın
        # uygulandığı ürün yüzünde durur. Panel bir sayıya bakarken o
        # sayının hangi birimden çevrildiğini görebilmelidir; künye
        # ayrıştırıcının TEK kaynağından gelir (units).
        'units': parsed.get('units'),
    }

    comparison = None
    if predicted_curve is not None:
        try:
            comparison = sanitize_json_values(
                compare_thrust_curves(parsed, predicted_curve))
        except ValueError as exc:
            # CSV çözüldü ama karşılaştırma anlamsız (örtüşme yok vb.):
            # panel çözümlemeyi yine gösterebilsin diye parsed eklenir.
            return jsonify({
                'status': 'error',
                'error': str(exc),
                'parsed': parsed_out,
            }), 400

    return jsonify({
        'status': 'success',
        'parsed': parsed_out,
        'comparison': comparison,
    })


# ---------------------------------------------------------------------------
# v2.5.0 G3 — Belirsizlik nicelemesi (UQ) endpoint'i
# ---------------------------------------------------------------------------
# Kontrat (G3 API dalgası): POST /api/uncertainty-analysis
#   fast / engineering  -> senkron 'ok' gövdesi
#   high_fidelity       -> job_runner'a kuyruklanır (202 + job_id; sonuç
#                          GET /api/jobs/<id> sözleşmesiyle, job.result =
#                          aynı 'ok' gövdesi)
# Motor print gürültüsü endpoint kapsamında os.devnull'a yönlendirilir.

_UQ_MOTOR_TYPES = ('hybrid', 'solid', 'liquid')


#: ÖH D28 a1 / P7B4-19 — motor tipi -> ``FORM_LIMITS`` formu.
#:
#: Eşleme YENİ BİR SÖZLEŞME DEĞİLDİR: ucun kendi belgesi ``inputs``ı "the
#: motor form fields" diye tanımlar ve her motor tipinin formu deponun
#: kendi uçlarında zaten adlıdır — hibrit form ``/api/quick-geometry``,
#: katı ``/calculate_solid``, sıvı ``/calculate_liquid``. Bant değerleri
#: ``hrma.validation.motor_validation.FORM_LIMITS``te BİR KEZ yazılıdır.
_UQ_FORM_BY_MOTOR = {
    'hybrid': 'quick_geometry',
    'solid': 'solid',
    'liquid': 'liquid',
}


class _UQAnalysisError(RuntimeError):
    """UQ koşusu status='error' döndürdü (örnek #0 tutarlılık kırılması
    dahil) — sessiz düşme yok, 500 + mesajla yukarı taşınır."""


def _uq_contract_body(motor_type, level, result):
    """run_uncertainty sonucunu G3 API kontrat gövdesine çevirir.

    Kontrat alanlarına ek olarak şeffaflık alanları taşınır (sampler,
    uq_version, inputs_used künyeleri, yöntem notu) — kontratın üst kümesi.
    'cv' yüzde cinsindendir (mevcut solid MC cv_percent geleneği); aynı değer
    'cv_percent' adıyla da yankılanır ki birim belirsizliği kalmasın.
    """
    outputs = {}
    for key, block in result['outputs'].items():
        outputs[key] = {
            'nominal': block['nominal'],
            'mean': block['mean'],
            'std': block['std'],
            'cv': block['cv_percent'],
            'cv_percent': block['cv_percent'],
            'p5': block['p5'],
            'p25': block['p25'],
            'p50': block['p50'],
            'p75': block['p75'],
            'p95': block['p95'],
            'histogram': block['histogram'],
        }
    # sensitivity sözlüğü hem çıktı-başına SATIR LİSTESİ hem de skaler
    # meta alanları taşır ('method_note', v2.6.2'de eklenen 'noise_floor').
    # Skalerleri satır listesi sanıp döngüye sokmak TypeError üretiyordu;
    # bu yüzden çıktı satırları v2.6.27 E5'ten beri TEK ve KESİN yerden,
    # 'per_output' sözlüğünden okunur (tip bakarak ayırma kalmadı). Eski
    # çekirdeklerle çalışabilmek için per_output yoksa eski tip ayrımına
    # düşülür — davranış aynı kalır.
    sens_src = result['sensitivity']
    if isinstance(sens_src.get('per_output'), dict):
        rows_by_key = sens_src['per_output']
    else:
        rows_by_key = {k: v for k, v in sens_src.items()
                       if isinstance(v, (list, tuple))}
    sensitivity = {}
    for key, rows in rows_by_key.items():
        sensitivity[key] = [
            {'param': row['param'], 'rho': row['spearman'],
             # Gürültü tabanı: |rho| bu değerin altındaysa duyarlılık
             # örnekleme gürültüsünden ayırt edilemez (v2.6.2 fizik denetimi).
             **({'noise_floor': row['noise_floor']}
                if isinstance(row, dict) and 'noise_floor' in row else {}),
             # v2.6.27 E5: çekirdek bu hükmü ZATEN hesaplıyordu ama kontrat
             # gövdesi onu DÜŞÜRÜYORDU; panel de bu yüzden gürültüyü sinyal
             # gibi çiziyordu. Hüküm artık kullanıcıya kadar taşınır.
             **({'significant': bool(row['significant'])}
                if isinstance(row, dict) and 'significant' in row else {})}
            for row in rows
        ]
    # Skaler meta (method_note, noise_floor, status, basis, n_used, ...);
    # per_output satır kaynağıdır, meta'ya KOPYALANMAZ.
    sensitivity_meta = {k: v for k, v in sens_src.items()
                        if k != 'per_output' and k not in rows_by_key
                        and not isinstance(v, (list, tuple))}
    body = {
        'status': 'ok',
        'motor_type': motor_type,
        'level': level,
        'n_samples': result['n_samples'],
        'failed_samples': result['failed_samples'],
        'seed': result['seed'],
        'timing_s': result['timing']['wall_s'],
        'mean_shift_percent': result['consistency']['mean_shift_percent'],
        'outputs': outputs,
        'sensitivity': sensitivity,
        'sensitivity_method_note': result['sensitivity'].get('method_note'),
        # v2.6.27 E5 — beyan alanları: hüküm ('modelled' | 'not_modelled') ve
        # dayanağı (kaç örnek, hangi örneklemden, hangi eşiğin altı okunamaz).
        # Örnek yetersizse çekirdek sıralama ÜRETMEZ; panel bu iki alanı
        # göstererek boşluğu gerekçesiyle beyan eder, sıfır uydurmaz.
        'sensitivity_status': result['sensitivity'].get('status'),
        'sensitivity_basis': result['sensitivity'].get('basis'),
        # Skaler meta alanları (ör. noise_floor): |rho| bu eşiğin altındaysa
        # duyarlılık örnekleme gürültüsünden ayırt edilemez. Kullanıcı bunu
        # görmeden sıralamaya anlam yükleyemez.
        'sensitivity_meta': sensitivity_meta,
        'sampler': result['sampler'],
        'uq_version': result['uq_version'],
        'inputs_used': result['inputs_used'],
        'consistency_note': result['consistency'].get('note'),
        # ÖH D37 A1a pdf-grafik-step DEVİR (OH-D30-12): çekirdeğin P5/P95
        # kapsam künyesi (uncertainty._conditionality_block) gövdeye
        # taşınır; panel (A1b panel-js) ve PDF (UQ_RESULT_KEY) aynı bloğu
        # okur. Yeni sayı üretmez; yoksa alan konmaz (fail-closed).
        **({'conditionality': result['conditionality']}
           if isinstance(result.get('conditionality'), dict) else {}),
    }
    if result.get('warning'):
        body['warning'] = result['warning']
    return body


#: ÖH D29 / app-api-uc a1 (P16B3-29) — belirsizlik koşumunun ÖRNEK SAYISI
#: bandı. TEK KAYNAK: hem uç kapısı hem ``_run_uq_analysis`` bunu okur
#: (Doktrin 4). Seviye bütçeleri ayrı bir tablodur (``LEVEL_BUDGETS``);
#: bunlar o tablonun DEĞİL, koşucunun kendi sınırlarıdır.
#:
#: ÖLÇÜLEN KUSUR (``a1/once3.json`` K4, taban 4c27fa51; hibrit, 'fast'):
#: kapı 2..49 aralığını GEÇİRİYOR, koşum ise ``max(50, min(n, 10000))``
#: ile SESSİZCE 50'ye yükseltiyordu — ``n_samples`` 2 / 30 / 49 gönderen üç
#: istek de HTTP 200 ve yanıtta ``n_samples: 50`` alıyordu. Kullanıcı 30
#: örnek istiyor, 50 örnekle koşulmuş bir dağılım okuyordu.
#:
#: ONARIM YÖNÜ: taban YÜKSELTİLMEDİ, çünkü küçük örnek sayısı çözülemez bir
#: girdi DEĞİLDİR — deponun kendi sağlıklı gövdeleri onu bilerek kullanıyor
#: (``tests/test_d28_app_api_a1.py`` ``n_samples: 2``,
#: ``tests/test_d27_app_api_a4.py`` ``n_samples: 12``: hızlı koşum seçimi).
#: Tabanı 50'ye çekmek o envanteri daraltırdı (ÖK-22). Kusur ikamenin
#: KENDİSİYDİ: artık kullanıcının sayısı AYNEN koşulur, hiçbir sayı yukarı
#: çekilmez. Kapının alt sınırı bandın kurulu alt sınırıdır (iki örnek, bir
#: dağılımın kestirilebileceği en küçük sayı); tavan doğrudan
#: ``LEVEL_BUDGETS``ten gelir ve bu sabitin üstündedir, bu yüzden uç yolunda
#: ``UQ_MAX_SAMPLES`` erişilmez — o yalnız bu çekirdeği DOĞRUDAN çağıran
#: (uç dışı) yolların spec 7.1 tavanıdır.
UQ_MIN_SAMPLES = 2
UQ_MAX_SAMPLES = 10000


def _run_uq_analysis(motor_type, level, seed, inputs, overrides,
                     n_samples=None, progress_callback=None):
    """Senkron ve job yolunun ortak çekirdeği.

    Raises:
        ValueError: girdi/dağılım doğrulama hatası (endpoint 400'e çevirir).
        _UQAnalysisError: koşu status='error' bitirdi (endpoint 500).
    """
    from hrma.analysis import uncertainty as _uq
    from hrma.analysis import uq_adapters as _uqa

    distributions = _uqa.build_distributions(motor_type, overrides)
    if n_samples is None:
        n = _uq.LEVEL_BUDGETS[level]
    else:
        # ÖH D29 / app-api-uc a1 (P16B3-29) — YUKARI ÇEKME KALDIRILDI.
        # Eski satır ``max(50, min(int(n_samples), 10000))`` idi: 2..49
        # aralığındaki her istek SESSİZCE 50'ye çıkıyordu (ölçüm:
        # ``a1/once3.json`` K4). Kullanıcının sayısı artık AYNEN koşulur;
        # bandın alt ucunu uç kapısı ``UQ_MIN_SAMPLES`` ile zaten koruyor.
        # Üst kırpma spec 7.1 tavanı olarak kalır ve uç yolunda erişilmez
        # (uç tavanı ``LEVEL_BUDGETS['high_fidelity']`` bunun altındadır);
        # yalnız bu çekirdeği DOĞRUDAN çağıran yollar için anlamlıdır.
        n = min(int(n_samples), UQ_MAX_SAMPLES)
    track = (level == 'high_fidelity')  # spec: yalnız High-Fidelity O/F izler

    cb = None
    if progress_callback is not None:
        def cb(done, total):
            progress_callback(done / max(total, 1))

    # P17B3-01: süreç-genel redirect_stdout YERİNE iş parçacığı-yerel
    # sessizleştirme (iç içe koşumda sys.stdout'u kapalı dosyaya bağlamaz).
    with _motor_stdout_sessiz():
        factory = _uqa.make_factory(motor_type, inputs,
                                    track_performance=track)
        result = _uq.run_uncertainty(
            factory, distributions, n_samples=n, seed=seed,
            progress_callback=cb)

    if result.get('status') != 'success':
        raise _UQAnalysisError(
            result.get('error') or 'uncertainty analysis failed')
    _govde = _uq_contract_body(motor_type, level, result)
    # --- ÖH D28 a1 / P7B4-18 (ikinci yarı) · MOTORUN KENDİ HÜKMÜ -------
    # ÖLÇÜLDÜ (``a1/once.json`` K2): sağlıklı hibrit gövdenin 19 üst
    # anahtarının hiçbiri motorun ``design_warnings`` defterini taşımıyordu
    # (yanıtta "anormal" 0 kez). Ana sayfa (``/calculate``) o defteri
    # kullanıcıya BASIYOR; belirsizlik raporu aynı motorun aynı hükmünü
    # sessizce düşürüyordu. Gerekçe ve kanal seçimi
    # ``uq_adapters._defteri_kaydet`` künyesindedir (süreç-genel
    # ``warnings.catch_warnings`` KULLANILMAZ).
    #
    # Beyan yalnız GERÇEKTEN bir hüküm varsa eklenir: defteri boş çıkan
    # motorun gövdesi BİT-AYNI kalır (boş liste "denetlendi, temiz" demek
    # olurdu — sahte gösterge yasağı).
    _defter = getattr(factory, 'nominal_design_warnings', None)
    if _defter:
        _govde['nominal_design_warnings'] = _defter
    # --- Kitap uyum B16, 3. tur (Ş-6) · GİRİŞ DURUMU BEYANI ------------
    # ÖLÇÜLDÜ (p1a yeniden denetim-2, 8 Eki): hibrit UQ yanıtında
    # ``oxidizer_inlet_state`` yaprağı YOKTU; formül sayfası "her hibrit
    # sonuç çözüldüğü giriş durumunu beyan eder" diyordu. Fabrika giriş
    # durumunu motora 2. turda taşıdı (Ş-4); burada yalnız BEYANI eklenir.
    if motor_type == 'hybrid':
        _govde['oxidizer_inlet_state'] = _uq_hybrid_inlet_state_declaration(
            inputs)
    return sanitize_json_values(_govde)


def _uq_hybrid_inlet_state_declaration(inputs):
    """Hibrit UQ koşusunun N₂O giriş durumu beyanı (Ş-6, sayı uydurmadan).

    Fabrikanın motorlarına giden AYNI istek (``inlet_request_from_payload``,
    tek öncelik kuralı) bağımsız bir analizöre uygulanır ve beyan, yan
    çözüm uçlarının (``/api/find-optimum-of``, ``/api/advanced-analysis``)
    ortak yardımcısıyla (``inlet_state_declaration``) üretilir; sayı tek
    kaynaktan gelir (``oxidizer_inlet.n2o_inlet_state``). Oksitleyici
    verilmemişse motorun KENDİ imza varsayılanı okunur (ikinci kopya
    yazılmaz; ``uq_adapters.make_hybrid_factory`` ile aynı sözleşme).
    Geçersiz giriş buraya ulaşmaz: fabrika motoru onu koşudan önce reddeder.
    """
    import inspect
    from hrma.engines.combustion_analysis import CombustionAnalyzer
    from hrma.engines.hybrid_rocket_engine import HybridRocketEngine
    from hrma.engines.oxidizer_inlet import (
        apply_inlet_request, inlet_request_from_payload,
        inlet_state_declaration)
    data = dict(inputs or {})
    ox = data.get('oxidizer_type')
    if ox in (None, ''):
        ox = inspect.signature(HybridRocketEngine.__init__).parameters[
            'oxidizer_type'].default
    istek = inlet_request_from_payload(data)
    with _motor_stdout_sessiz():
        analyzer = CombustionAnalyzer(memoize=False)
        uygulandi = apply_inlet_request(analyzer, ox, istek)
    return inlet_state_declaration(analyzer, ox, istek, uygulandi)


def _uncertainty_job(payload, progress_callback=None):
    """job_runner işi: high_fidelity UQ koşusu (job.result = 'ok' gövdesi)."""
    return _run_uq_analysis(
        payload['motor_type'], payload['level'], payload['seed'],
        payload['inputs'], payload['overrides'], payload.get('n_samples'),
        progress_callback=progress_callback)


@app.route('/api/uncertainty-analysis', methods=['POST'])
def uncertainty_analysis():
    """Monte Carlo / LHS uncertainty analysis (G3 contract).

    Request: {motor_type, level, seed?, inputs, distribution_overrides?,
    n_samples?}. fast/engineering run synchronously; high_fidelity is queued
    on the job runner (202 + job_id, poll GET /api/jobs/<id>; the finished
    job's result is the same 'ok' body).
    """
    data = request.get_json(silent=True) or {}

    motor_type = data.get('motor_type')
    if motor_type not in _UQ_MOTOR_TYPES:
        return jsonify({
            'status': 'error',
            'error': (f"motor_type must be one of {list(_UQ_MOTOR_TYPES)}; "
                      f"got {motor_type!r}."),
        }), 400

    from hrma.analysis.uncertainty import LEVEL_BUDGETS as _LEVELS
    level = data.get('level')
    if level not in _LEVELS:
        return jsonify({
            'status': 'error',
            'error': (f"level must be one of {sorted(_LEVELS)}; "
                      f"got {level!r}."),
        }), 400

    # --- ÖH D33-3 / OH-D33-16 · KAPI SIRASI KİLİTLENDİ -----------------
    # ÖLÇÜLDÜ (``docs/scofield/raw/OH/D33-3/app-api-kapilar/a1/once.json``
    # K2, taban ``fa7c4e1d``): iki eksikliği olan gövdede
    # (``inputs`` HİÇ YOK **+** ``seed=-1``) uç 400 ``seed`` diyordu —
    # yani kullanıcıya İKİNCİL sorun söyleniyor, birincil sorun ("bu
    # istekte hiç motor girdisi yok") hiç anılmıyordu. Aynı gövde
    # ``seed`` düzeltilince 422 ``incomplete_uncertainty_input`` alıyor:
    # kullanıcı iki turda öğreniyordu.
    #
    # KANON KARDEŞ UÇTAN OKUNDU, İCAT EDİLMEDİ: ``/analyze_safety`` önce
    # ZORUNLU alan tamlığını sorar (``incomplete_safety_input``, 422),
    # ANCAK SONRA gönderilmiş değerlerin kendisini
    # (``invalid_safety_input``). ``/api/uncertainty-analysis``in kimlik
    # kapıları (``motor_type``, ``level``) zaten en başta; ``inputs`` da
    # bu ucun zorunlu YÜKÜDÜR ve isteğe bağlı ``seed`` alanının
    # DEĞERİNDEN önce sorulur. Sıra artık bekçiyle kilitlidir
    # (``tests/test_d33_app_api_kapilar_a1.py``); hiçbir ret gövdesi,
    # kodu ya da metni değişmedi — yalnız hangi kapının önce konuştuğu
    # kilitlendi.
    inputs = data.get('inputs')
    if inputs is not None and not isinstance(inputs, dict):
        return jsonify({'status': 'error',
                        'error': "Field 'inputs' must be an object with the "
                                 "motor form fields."}), 400
    # --- ÖH D15 / P5B2-08 (YÜKSEK): GİRDİSİZ İSTEK RAPOR ÜRETEMEZ -------
    # ÖLÇÜLDÜ (taban e88d096, docs/scofield/raw/OH/D15/yapisal-sistem/a1/
    # once.json): ``{'motor_type': 'hybrid', 'level': 'fast'}`` — yani
    # kullanıcının TEK BİR motor alanı vermediği istek — HTTP 200 ve 12 042
    # baytlık tam belirsizlik raporu döndürüyordu (hibrit isp nominali
    # 134,05 s, yüzdelikler, histogramlar, duyarlılık sıralaması). Bu
    # sayıların tamamı adaptörün kendi varsayılanlarından üretilmiş bir
    # motorundur; kullanıcının motoru değildir. Kardeş uç aynı durumda
    # zaten fail-closed: ``POST /analyze_safety -d '{}'`` -> HTTP 422
    # (239 bayt, ölçüldü, aynı dosya). Belirsizlik analizi, girdisi olmayan
    # bir motor için üretilemez; ÖK-19 gereği varsayılan KALDIRILIR
    # (``defaults_applied`` beyanıyla saklanmaz).
    if not inputs:
        return jsonify({
            'status': 'error',
            'error': 'incomplete_uncertainty_input',
            'message': ('An uncertainty analysis cannot be produced from '
                        'defaults: every distribution is centred on a motor '
                        'input. Provide the motor form fields in "inputs".'),
            'missing_fields': ['inputs'],
        }), 422

    try:
        # ÖH D23 a2 / P13B4-12: ham ``int()`` alanı adıyla anmadan
        # patlıyordu; ``integer`` kesirli tohumu da reddeder.
        seed = input_guard.integer(data, 'seed', default=42)
    except (TypeError, ValueError):
        return jsonify({'status': 'error',
                        'error': "Field 'seed' must be an integer."}), 400

    # --- ÖH D30 / app-api-uc a3 · P16B3-36 · TOHUMUN İŞARET KAPISI -------
    # ÖLÇÜLDÜ (``a3/once3.json`` K15, taban a2 ``294e6559``; geçerli gövde
    # hibrit/fast/12 örnek):
    #
    #   ``seed``     HTTP   gövde
    #   ----------   ----   ----------------------------------------------
    #   7            200    tam rapor (9196 B)
    #   0            200    tam rapor (9190 B)  -> sıfır GEÇERLİ tohumdur
    #   -1           400    **"expected non-negative integer"** (59 B)
    #   -12345       400    **"expected non-negative integer"** (59 B)
    #   true         400    "Field 'seed' must be an integer." (ucun metni)
    #
    # Negatif tohumun reddi DOĞRU, ama metin ucun değil ``numpy``nındır:
    # ``default_rng(-1)`` içeriden patlıyor ve dışarı çıkan gövde alan
    # adını da, sınırın nereden geldiğini de söylemiyor (59 bayt, yalnız
    # ``error`` + ``status``). Aynı istekte TİP reddi ise ucun kendi
    # cümlesiyle çıkıyordu — aynı alan, aynı sınıf hata, iki ayrı dil.
    #
    # SINIR İCAT EDİLMEDİ: alt uç ``numpy.random.default_rng``ın kendi
    # sözleşmesidir (tohum negatif olamaz) ve ölçümde ``seed = 0``ın
    # geçerli olduğu gösterildi, yani sıfır DIŞLANMAZ. Üst uç YOKTUR ve
    # uydurulmaz. Ret kodu kardeş tip reddiyle AYNI kalır (400).
    if seed < 0:
        return jsonify({
            'status': 'error',
            'error': ("Field 'seed' must be a non-negative integer; "
                      f'{seed} was supplied. The sampler seeds '
                      'numpy.random.default_rng, which does not accept a '
                      'negative seed. Nothing was sampled. (0 is a valid '
                      'seed.)'),
            'invalid_fields': [{
                'field': 'seed',
                'submitted': seed,
                'reason': 'must_be_non_negative',
                'accepted_range': [0, None],
                'basis': ('numpy.random.default_rng seed contract — the '
                          'endpoint no longer forwards the bare library '
                          'text'),
            }],
        }), 400

    # --- ÖH D27 a4 / P7B4-19 + P7B4-21 · MOTOR GİRDİSİ KAPISI ----------
    # ÖLÇÜLDÜ (taban ``8f083ca0``, ``a4/once.json`` K34/K5):
    #
    #   inputs.chamber_pressure = -50, motor_type='hybrid'  -> 400 (kapılı)
    #   inputs.chamber_pressure = -50, motor_type='solid'   -> 400 (kapılı)
    #   inputs.chamber_pressure = -50, motor_type='liquid'  -> **500**
    #                                        'float division by zero'
    #   inputs.of_ratio = -5,0 (senkron)                    -> **500**
    #                'Nominal referans hesabi basarisiz: of_ratio must be...'
    #   AYNI istek level='high_fidelity' ile                -> **202 queued**
    #   inputs.peynir_orani = 42,0                          -> 200, sessizce
    #                                        yutuldu (yanıtta tek yaprak yok)
    #
    # Yani aynı fiziksel imkânsızlık motor tipine ve seviyeye göre üç farklı
    # cevap alıyordu: adıyla ret, ham Python mesajıyla sunucu arızası, ya da
    # kabul + kuyruk. Kapı hiç uçta değildi; ilk üç tipin ikisinde ÇÖZÜCÜNÜN
    # kendi kapısına düşülüyordu ve o kapı ``inputs`` sözlüğünü değil kendi
    # kurucu argümanını suçluyordu.
    #
    # BANT/EŞİK İCAT EDİLMEZ (ÖK-18, doktrin 4): işaret sözleşmesi ucun
    # kendi deposundan gelir — ``PARAMETRIC_POSITIVE_PARAMS`` (``/calculate``
    # aynı adlara aynı kuralı uyguluyor) — geri kalan her sayı yalnız SONLU
    # olmak zorundadır. ``0`` ile "verilmedi" karıştırılmaz
    # (``_collect_unphysical_fields`` sözleşmesi).
    #
    # Kapı KUYRUKTAN ÖNCEDİR: ``distribution_overrides`` doğrulaması da
    # (aşağıda) aynı gerekçeyle erkene alınmıştı — bozuk girdi 202 alıp
    # dakikalar sonra ``job.error`` olarak görünmez.
    if isinstance(inputs, dict):
        _uq_sayisal = [ad for ad, v in inputs.items()
                       if not isinstance(v, (dict, list, tuple))]
        # V3 KK 3. tur (§28-50 (c) kökü): ``/calculate``'in fix-7 sözleşmesi
        # (``_CALCULATE_ZERO_MEANS_AUTO``) burada uygulanmıyordu. ÖLÇÜLDÜ
        # (kk3/olc_uq.py, ürünle gelen örnek hibrit, formun kendi gövdesi):
        # ``chamber_diameter_input: 0`` ("hazne çapını çözücü çözsün") 422
        # ``must_be_positive`` aldı; aynı gövde ``/calculate``te hesaplanıyor.
        # Sıfır "otomatik" sayılır, negatif yine ``must_be_non_negative``
        # ile reddedilir (kapı gevşemez, aynı tek sözleşme).
        _uq_pozitif = [ad for ad in _uq_sayisal
                       if ad in PARAMETRIC_POSITIVE_PARAMS
                       and ad not in _CALCULATE_ZERO_MEANS_AUTO]
        _uq_negatifsiz = [ad for ad in _uq_sayisal
                          if ad in _CALCULATE_ZERO_MEANS_AUTO]
        _uq_sonlu = [ad for ad in _uq_sayisal
                     if ad not in PARAMETRIC_POSITIVE_PARAMS
                     and not isinstance(inputs.get(ad), (str, bool))]
        _uq_ihlal = _collect_unphysical_fields(
            inputs, positive=_uq_pozitif, non_negative=_uq_negatifsiz,
            finite=_uq_sonlu)
        if _uq_ihlal:
            return jsonify({
                'status': 'error',
                'error': 'non_physical_uncertainty_input',
                'message': (
                    'No uncertainty analysis was run: every distribution is '
                    'centred on one of these motor inputs, so a value that '
                    'cannot exist would centre a distribution on it. The '
                    'value was NOT clamped or replaced by a default.'),
                'invalid_fields': [dict(f, container='inputs')
                                   for f in _uq_ihlal],
            }), 422

    # --- ÖH D28 a1 / P7B4-19 (kalan yarı) · FİZİK BANDI --------------
    # ÖLÇÜLDÜ (taban ``7cd08bcc``, ``a1/once.json`` K1): D27'nin işaret
    # kapısı yalnız işareti ve sonluluğu tutuyordu; BÜYÜKLÜK serbestti:
    #
    #   inputs.chamber_pressure = 1e9 bar, hybrid   -> HTTP 200, 12 004 B
    #                                        tam belirsizlik raporu
    #   aynı istek solid                            -> HTTP 200,  7 369 B
    #   inputs.thrust = 1e12 N, üç tipte de         -> HTTP 200
    #   inputs.chamber_pressure = 0,001 bar, hybrid -> HTTP **500**, gövdede
    #                     ÇIPLAK Cantera metni ("No convergence in 500
    #                     iterations ... The phase became unstable (Cp < 0)")
    #   aynı istek liquid -> 500 "The function value at x=1e-06 is NaN"
    #   aynı istek solid  -> 500 "SolidRocketEngine: Invalid grain geometry"
    #
    # Yani fiziksel olarak imkânsız bir motor ya "başarılı" bir belirsizlik
    # raporu üretiyor ya da çözücünün İÇ metniyle sunucu arızasına
    # dönüşüyordu. İkisi de aynı kusurun iki yüzü: kapı uçta yoktu.
    #
    # BANT İCAT EDİLMEZ (ÖK-18, Doktrin 4): bu ucun ``inputs`` sözlüğü kendi
    # belgesinde "the motor form fields"tır, dolayısıyla o formların BANDI
    # uygulanır — ``FORM_LIMITS`` (``motor_validation``), kardeş uçların
    # (``/api/quick-geometry``, ``/calculate_solid``, ``/calculate_liquid``)
    # AYNI alanlara AYNI sayıyla uyguladığı tablo. Yeni sayı yazılmaz,
    # mevcut sayı değiştirilmez; eşleme motor tipinden forma yapılır ve
    # tabloda karşılığı OLMAYAN alana DOKUNULMAZ.
    #: ÖH D33 / P7B4-19 ŞARTI — tabloda satırı olmadığı için denetlenemeyen
    #: sayısal alanların künyesi (aşağıda doldurulur, gövdeyle yayımlanır).
    _uq_bantsiz = []
    if isinstance(inputs, dict):
        from hrma.validation.motor_validation import (
            FORM_LIMITS as _uq_form_limits)
        _uq_form = _UQ_FORM_BY_MOTOR.get(motor_type)
        _uq_band_ihlal = []
        for _ad in sorted(_uq_form_limits.get(_uq_form, {})):
            _ham = inputs.get(_ad)
            if _ham is None or _ham == '':
                continue
            try:
                _form_band_kapisi(_ham, _uq_form, _ad, _ad)
            except BandIhlali as _bi:
                _uq_band_ihlal.append(dict(_bi.kunye, container='inputs',
                                           detail=str(_bi)))
        if _uq_band_ihlal:
            return jsonify({
                'status': 'error',
                'error': 'uncertainty_input_out_of_range',
                'message': (
                    'No uncertainty analysis was run: every distribution is '
                    'centred on one of these motor inputs, and the value '
                    'you sent is outside the band this product accepts for '
                    'that field on the motor form. The same band is applied '
                    'by the form endpoint for this motor type, so a value '
                    'rejected there cannot be sampled here. Nothing was '
                    'clamped and no default was put in its place.'),
                'invalid_fields': _uq_band_ihlal,
                'motor_form': _uq_form,
            }), 422

        # --- ÖH D33 / P7B4-19 (denetim ŞARTI) · BANDI OLMAYAN SAYI ------
        # Yukarıdaki kapı ``FORM_LIMITS[form]`` tablosunu gezer, yani
        # tabloda SATIRI OLMAYAN alan denetlenmeden geçer. ÖLÇÜLDÜ (taban
        # ``56f88e70``, ``docs/scofield/raw/OH/D33/app-api-uc/a1/once.json``
        # K4): ``FORM_LIMITS['solid']`` beş satır taşıyor
        # (``burn_rate_a``, ``burn_rate_n``, ``chamber_diameter``,
        # ``chamber_pressure``, ``grain_length``) ve ``thrust`` ARALARINDA
        # YOK; sonuç, ``motor_type='solid'`` + ``inputs.thrust = 1e12 N``
        # gövdesinin HTTP 200 + tam belirsizlik raporu almasıdır. Yani
        # katı kolda itki ölçüsü hiç denetlenmiyor ve 200 dönen yanıt bunu
        # SÖYLEMİYOR.
        #
        # BANT İCAT EDİLMEZ (ÖK-18, Doktrin 4): katı formun itki zarfı bir
        # VERİ kararıdır (OH-UC-12, Berke) ve ``FORM_LIMITS``e buradan
        # satır eklenmez. Bu yüzden onarım, borcu GÖRÜNÜR kılmaktır:
        # denetlenemeyen alan yanıtta ADIYLA ilan edilir, böylece 200 dönen
        # gövde hangi sayının denetlenmediğini KENDİSİ söyler. Künye bir
        # ÇÖZÜM DEĞİLDİR (Doktrin 1) ve öyle sunulmaz — borcun kapanması
        # tabloya satır girmesidir; künye yalnız gerçeği söyler ve satır
        # girdiği gün kendiliğinden kaybolur.
        #
        # Yalnız SAYI ilan edilir (``is_json_number``, tek kaynak): bir
        # itici adı ya da lüle tipi zaten bant denetlenebilir bir ölçü
        # değildir, onu "denetlenmedi" diye ilan etmek gürültü olurdu —
        # gönderilip okunmayan alanlar ZATEN ``inputs_not_read``ta.
        _uq_bantsiz = [
            {'field': _ad,
             'form': _uq_form,
             'reason': 'no_band_in_form_limits',
             'message': (
                 f"'{_ad}' was sampled as given: this product has no "
                 f"accepted band for it on the '{_uq_form}' motor form, so "
                 'no range check was applied to it. The value was not '
                 'clamped and no default replaced it; it simply was not '
                 'checked.')}
            for _ad in sorted(inputs)
            if _ad not in _uq_form_limits.get(_uq_form, {})
            and input_guard.is_json_number(inputs.get(_ad))]

    # ÖH D27 a4 / P7B4-19 (ikinci yarı) — GÖNDERİLDİ ama OKUNMADI.
    # Kaynak ``uq_adapters.FACTORY_INPUT_FIELDS`` (tek kaynak, AST bekçili).
    # Beyan yalnız gerçekten söylenecek bir şey varsa eklenir; sağlıklı
    # gövde BİT-AYNI kalır. ``solid`` kapalı küme taşımaz (bkz. künye).
    _uq_okunmayan = []
    if isinstance(inputs, dict):
        from hrma.analysis.uq_adapters import (
            FACTORY_INPUT_FIELDS as _uq_okunan)
        _kapali = _uq_okunan.get(motor_type)
        if _kapali:
            _uq_okunmayan = [
                {'field': ad, 'reason': 'field_not_read',
                 'message': (f"'{ad}' was supplied but the {motor_type} "
                             'uncertainty model does not read it: no '
                             'distribution is centred on it and no value was '
                             'assumed in its place.')}
                for ad in sorted(inputs) if ad not in _kapali]

    overrides = data.get('distribution_overrides')
    n_samples = data.get('n_samples')
    if n_samples is not None:
        try:
            n_samples = int(n_samples)
        except (TypeError, ValueError):
            return jsonify({'status': 'error',
                            'error': "Field 'n_samples' must be an "
                                     "integer."}), 400
        # --- ÖH D24 / P16B3-08 · ÖRNEK SAYISININ ÜST SINIRI --------------
        # ÖLÇÜLDÜ (taban 88a29d3, ``a1/once.json``): ``n_samples`` hiçbir
        # üst sınırdan geçmiyordu. ``level`` alanı bu ucun DUVAR SAATİ
        # sözleşmesidir (``LEVEL_BUDGETS``: fast 200, engineering 1000,
        # high_fidelity 3000 örnek; ARGE ölçümü ~91-185 ms/örnek → sırasıyla
        # ~20-30 s, ~1,5-3 dk, ~9-14 dk) ve mimarî tam bu yüzden yalnız
        # ``high_fidelity``yi iş kuyruğuna atıyor. ``n_samples`` o
        # sözleşmenin üstünden atlıyordu: ``{'level': 'fast', 'n_samples':
        # 1e9}`` eşzamanlı istekte 1 milyar motor koşumu talep ediyor,
        # sunucu isteği hiçbir zaman bitiremiyordu (sonda 30 s kapağında
        # kesildi). Alt uç (``n >= 2``) çözücüde zaten var ama işe
        # BAŞLADIKTAN sonra patlıyordu; kapı artık uçta, alan adıyla.
        #
        # YENİ SAYI YAZILMADI: iki sınır da ``LEVEL_BUDGETS``ten okunur —
        # mutlak tavan en yüksek seviyenin bütçesi, eşzamanlı yolun tavanı
        # ise EŞZAMANLI koşulan en yüksek seviyenin bütçesidir. Daha
        # büyüğünü isteyen istek reddedilmez, doğru kanala yönlendirilir.
        _uq_tavan = _LEVELS['high_fidelity']
        _uq_es_zamanli_tavan = max(
            v for k, v in _LEVELS.items() if k != 'high_fidelity')
        if n_samples < UQ_MIN_SAMPLES or n_samples > _uq_tavan:
            return jsonify({
                'status': 'error',
                'error': 'n_samples_out_of_range',
                'message': (
                    f"Field 'n_samples' must be between {UQ_MIN_SAMPLES} "
                    f'and {_uq_tavan}; got {n_samples}. '
                    f'{UQ_MIN_SAMPLES} samples are the minimum a '
                    'distribution can be estimated from, and '
                    f'{_uq_tavan} is the largest budget this product '
                    "declares for any level (LEVEL_BUDGETS['high_fidelity'])."
                    ' Nothing was sampled.'),
                'invalid_fields': [{
                    'field': 'n_samples',
                    'value': n_samples,
                    'reason': 'out_of_range',
                    'accepted_range': [UQ_MIN_SAMPLES, _uq_tavan],
                }],
            }), 400
        if level != 'high_fidelity' and n_samples > _uq_es_zamanli_tavan:
            return jsonify({
                'status': 'error',
                'error': 'n_samples_above_synchronous_budget',
                'message': (
                    f"Field 'n_samples' is {n_samples}, above the largest "
                    f'budget this endpoint runs synchronously '
                    f'({_uq_es_zamanli_tavan} samples). A run that long is '
                    "served by level='high_fidelity', which is queued on the "
                    'job runner and answered with 202 + job_id. Nothing was '
                    'sampled.'),
                'invalid_fields': [{
                    'field': 'n_samples',
                    'value': n_samples,
                    'reason': 'above_synchronous_budget',
                    'accepted_range': [2, _uq_es_zamanli_tavan],
                    'level': level,
                }],
            }), 400

    # Dağılım kümesi erken doğrulanır: bozuk override job kuyruğuna girmeden
    # net bir 400 ile dönsün (job yolunda hata ancak poll'da görünürdü).
    try:
        from hrma.analysis import uq_adapters as _uqa
        _uqa.build_distributions(motor_type, overrides)
    except ValueError as exc:
        return jsonify({'status': 'error', 'error': str(exc)}), 400

    if level == 'high_fidelity':
        job_id = job_runner.submit(_uncertainty_job, {
            'motor_type': motor_type,
            'level': level,
            'seed': seed,
            'inputs': inputs,
            'overrides': overrides,
            'n_samples': n_samples,
        })
        _kuyruk = {
            'status': 'queued',
            'job_id': job_id,
            'poll_url': f'/api/jobs/{job_id}',
        }
        if _uq_okunmayan:
            _kuyruk['inputs_not_read'] = _uq_okunmayan
        # ÖH D33 / P7B4-19 ŞARTI: kuyruğa giren istek de denetlenmemiş
        # alanını ADIYLA öğrenir — yoksa borç yalnız eşzamanlı kolda
        # görünür, aynı gövde ``level='high_fidelity'`` ile sessiz kalırdı.
        if _uq_bantsiz:
            _kuyruk['inputs_not_band_checked'] = _uq_bantsiz
        return jsonify(_kuyruk), 202

    try:
        body = _run_uq_analysis(motor_type, level, seed, inputs, overrides,
                                n_samples)
    except ValueError as exc:
        return jsonify({'status': 'error', 'error': str(exc)}), 400
    except _UQAnalysisError as exc:
        # Örnek #0 tutarlılık kırılması dahil: sessiz düşme yok (spec 7.3)
        return jsonify({'status': 'error', 'error': str(exc)}), 500
    except Exception as exc:
        traceback.print_exc()
        return jsonify({'status': 'error', 'error': str(exc)}), 500
    if _uq_okunmayan:
        body['inputs_not_read'] = _uq_okunmayan
    # ÖH D33 / P7B4-19 ŞARTI — boşken alan KONMAZ: boş liste "denetlendi,
    # temiz" demek olurdu (sahte gösterge yasağı, ``inputs_not_read`` ile
    # aynı sözleşme). Tabloya satır girdiği gün künye kendiliğinden kaybolur.
    if _uq_bantsiz:
        body['inputs_not_band_checked'] = _uq_bantsiz
    return jsonify(body)


# ---------------------------------------------------------------------------
# v2.5.0 G3 — Otomatik korelasyon raporu endpoint'i
# ---------------------------------------------------------------------------
# GET  /api/correlation-report          -> önbellekli özet (ilk çağrı koşar)
# POST /api/correlation-report {refresh:true} -> önbelleği yok say, yeniden koş
# Önbellek anahtarı: deney DB içerik hash'i (correlation_runner.db_content_hash)

_CORRELATION_CACHE = {}

# Korelasyon koşusu tek seferde BİR kez çalışsın (v2.6.2).
#
# Koşu soğukta ~2 dakika sürüyor (Cantera denge çözümleri; docstring "~15-25 s"
# diyordu ama DB 136 -> 209 kayda çıkınca güncellenmemişti). Flask geliştirme
# sunucusu çok iş parçacıklı olduğu için, önbellek soğukken gelen iki eşzamanlı
# istek AYNI ağır işi iki kez başlatıyordu: CPU ikiye katlanıyor, ikisi de
# önbelleğe yazıyor ve kullanıcı iki katı bekliyordu. Kilit, ikinci isteğin
# birincinin sonucunu beklemesini sağlar (sonra önbellekten anında döner).
_CORRELATION_LOCK = threading.Lock()


def _correlation_report_body(refresh=False):
    """Korelasyon rapor gövdesini kurar (modül-içi {db_hash: gövde} önbelleği).

    ÖH D30 / app-api-uc a2 · P7B4-17 — SÜRE İDDİASI DÜZELTİLDİ.
    Bu docstring koşuyu "~15-25 s" diye tanıtıyordu. ÖLÇÜLDÜ (P07 bulucu
    koşumu, ``docs/scofield/P07-app-api-rapor.md#EKA-P7B4-17``): soğuk koşu
    ``generated_s = 112,229`` saniye, yani iddianın 4,5-7,5 KATI. İddianın
    yanlış olduğu 13 satır yukarıdaki ``_CORRELATION_LOCK`` yorumunda ZATEN
    yazılıydı ("Koşu soğukta ~2 dakika sürüyor ... docstring '~15-25 s'
    diyordu ama DB 136 -> 209 kayda çıkınca güncellenmemişti") — aynı dosyada
    iki metin birbiriyle çelişiyordu. YENİ SABİT SÜRE UYDURULMADI: süre DB
    kayıt sayısıyla büyüyen bir ÖLÇÜMdür ve tek kaynağı yanıtın kendi
    ``generated_s`` alanıdır.

    Süre: ölçülen soğuk koşu ~2 dakika mertebesinde (112,2 s / 209 kayıt) ve
    kayıt sayısıyla büyür; GERÇEK süre her koşuda yanıtın ``generated_s``
    alanında yayımlanır. İlk çağrı senkron kabul edilir, sonrakiler
    cached=true ile anında döner. DB içeriği değişince hash değişir ve
    önbellek kendiliğinden ıskalar.
    """
    from hrma.validation import correlation_runner as _cr
    from hrma.validation.experiment_db import (load_records,
                                               records_for_statistics)
    from hrma.validation.status_report import correlation_cells

    records = load_records()
    stat_records = sorted(records_for_statistics(records),
                          key=lambda r: r.get('test_id', ''))
    db_hash = _cr.db_content_hash(stat_records)

    if not refresh and db_hash in _CORRELATION_CACHE:
        body = dict(_CORRELATION_CACHE[db_hash])
        body['cached'] = True
        return body

    # P17B3-01: kardeş rotayla aynı iş parçacığı-yerel sessizleştirme.
    with _motor_stdout_sessiz():
        result = _cr.run_correlation(records=records)

    skipped_scores = {}
    for rr in result['records']:
        for score in rr.get('scores', {}).values():
            status = score.get('status')
            if status and status != 'scored':
                skipped_scores[status] = skipped_scores.get(status, 0) + 1

    # --- ÖH Z5S / P10-C: BEYAN EDİLEN DÜRÜSTLÜK KANALLARI UCA İNİYOR -------
    #
    # P10B2-09 — ÖLÇÜLDÜ (28 Ağustos 2026, tam koşu; kanıt:
    # docs/scofield/raw/OH/Z5S/p10c/once_korelasyon.json): adaptör 212 kaydın
    # 95'inde ``assumed_defaults``, 98'inde ``adapter_notes`` dolduruyor
    # (48 kayıtta genişleme oranını HRMA'nın kendisi seçiyor, 48'inde ortam
    # basıncı varsayılıyor, 26'sında yakıt yoğunluğu tablo değeri, 10'unda
    # itki 10 kN varsayılıyor). Koşucu ikisini de kayıt sözlüğüne taşıyor.
    # Ama ``/api/correlation-report`` gövdesi YALNIZ record_counts / cells /
    # skipped_summary / markdown yayımlıyordu: modülün kendi ilan ettiği iki
    # dürüstlük kanalı uca HİÇ çıkmıyordu — karşılaştırmanın varsayımları
    # kullanıcıdan gizliydi.
    #
    # HÜCREYE EKLENMEZ, GÖVDEYE EKLENİR: hücre düzleştiricisi
    # (``status_report._flatten_cell``) ayrı bir kalemin (P13B4-05 / P10 D-03)
    # konusudur ve şekli ``tests/test_fazb_serilestirici_esligi.py`` tarafından
    # ölçülüp dondurulmuştur. Bu blok o ölçümü bozmadan, kayıt düzeyinde
    # yayımlar.
    assumed_counts = {}
    note_records = 0
    declared = []
    for rr in result['records']:
        assumed = rr.get('assumed_defaults') or {}
        notes = rr.get('adapter_notes') or []
        for key in assumed:
            assumed_counts[key] = assumed_counts.get(key, 0) + 1
        if notes:
            note_records += 1
        if assumed or notes:
            declared.append({
                'test_id': rr.get('test_id'),
                'motor_type': rr.get('motor_type'),
                'assumed_defaults': assumed,
                'adapter_notes': notes,
            })

    # P10B2-08 — yakınsamayan koşu artık uçta da GÖRÜNÜR. Koşucu bayrağı
    # üretiyordu, skorlama yolu okumuyordu; hüküm geri çekilen hücreler ve
    # yakınsamayan girişler ayrı ayrı yayımlanır (sayı silinmez).
    statistics = result['statistics']
    non_converged = {
        'entries': statistics.get('non_converged_entries', []),
        'withheld_cells': statistics.get('non_converged_withheld_cells', []),
        'record_ids': sorted({e['test_id'] for e
                              in statistics.get('non_converged_entries', [])}),
    }

    # P10B2-06 — MODEL KAPSAMI dışlaması uca iniyor ve ANOMALİDEN AYRILIYOR.
    # ÖLÇÜLDÜ (taban, 5 Eylül 2026; kanıt
    # docs/scofield/raw/OH/D23/app-api/a1/once_p10b2_06.json): dört Heydari
    # S4A1 swirl kaydı "HRMA v1 EKSENEL hibrit modelinin kapsamı dışında"
    # gerekçesiyle ANOMALİ bayrağı taşıyordu; yani MODELİN sınırı DENEYİN
    # kusuru kılığında başlıktan çıkıyordu. Uç gövdesi de yalnız 'anomaly'
    # katmanını yayımlıyordu — tüketici iki gerekçeyi ayıramıyordu.
    # Kapsam-dışı girişler artık kendi bloğunda, geri çekilen hücrelerle
    # (ölçüldü ama yayımlanmadı ≠ ölçülmedi) birlikte iner.
    out_of_scope = {
        'entries': statistics.get('out_of_scope_entries', []),
        'withheld_cells': statistics.get('out_of_scope_withheld_cells', []),
        'record_ids': sorted({e['test_id'] for e
                              in statistics.get('out_of_scope_entries', [])}),
    }

    # P10B2-02 — 'insufficient_inputs' GEREKÇESİ uca iniyor. Koşucunun
    # ``insufficient_inputs`` listesi yalnız ``{test_id, missing}`` taşır
    # (şekli ``tests/test_correlation_runner.py`` birebir kilitliyor), bu
    # yüzden ayrıştırılmış gerekçe AYRI bir alanda yayımlanır: "değer yok" ile
    # "birim soneki çözülemedi" artık aynı cümleye sığınmıyor.
    insufficient_detail = [
        {
            'test_id': rr.get('test_id'),
            'missing': rr.get('missing', []),
            'reason': rr.get('reason'),
            'missing_detail': rr.get('missing_detail', []),
        }
        for rr in result['records']
        if rr.get('status') == 'insufficient_inputs'
    ]

    body = sanitize_json_values({
        'status': 'ok',
        'db_hash': result['db_content_hash'],
        'cached': False,
        'generated_s': result['timing']['total_s'],
        'record_counts': {
            'total': result['n_records'],
            'scored': result['status_counts'].get('ok', 0),
            'insufficient_inputs': result['status_counts'].get(
                'insufficient_inputs', 0),
            'not_supported': result['status_counts'].get('not_supported', 0),
            'runner_error': result['status_counts'].get('runner_error', 0),
            # P10B2-10: 'scored' bir DURUM sayımıdır (adaptör koştu), tabloya
            # katkı değil. ÖLÇÜLDÜ: 98 'ok' kaydın 6'sı SIFIR büyüklük
            # skorluyor (RL10'un beş gerçek ateşleme kaydı + F-1 spec'i);
            # ölçülen büyüklükleri ya girdi olarak tüketiliyor ya cebirsel
            # türev sayılıyor. Dört terimli toplam kimliği DEĞİŞMEDİ; bu
            # beşinci alan onun yanına, adıyla eklenir.
            'with_scored_quantity': sum(
                1 for rr in result['records']
                if rr.get('status') == 'ok' and any(
                    s.get('status') == 'scored'
                    for s in (rr.get('scores') or {}).values())),
        },
        'cells': correlation_cells(result['statistics']),
        'skipped_summary': {
            'status_counts': result['status_counts'],
            'not_supported': result['not_supported'],
            'insufficient_inputs': result['insufficient_inputs'],
            'runner_errors': result['runner_errors'],
            'skipped_score_counts': dict(sorted(skipped_scores.items())),
        },
        'declared_assumptions': {
            'records_with_assumed_defaults': sum(
                1 for rr in result['records'] if rr.get('assumed_defaults')),
            'records_with_adapter_notes': note_records,
            'assumed_default_counts': dict(sorted(assumed_counts.items())),
            'records': declared,
        },
        'non_converged': non_converged,
        'out_of_scope': out_of_scope,
        'insufficient_inputs_detail': insufficient_detail,
        'markdown': _cr.to_markdown(result),
    })

    # Tek girdilik önbellek: DB değişince eski sonuç bellekte birikmesin
    _CORRELATION_CACHE.clear()
    _CORRELATION_CACHE[db_hash] = body
    return dict(body)


@app.route('/api/correlation-report', methods=['GET', 'POST'])
def correlation_report():
    """Real-experiment correlation report (G3 contract).

    GET returns the cached report when the experiment DB is unchanged
    (cached=true); the first call runs the full correlation synchronously.
    POST with {"refresh": true} ignores the cache and re-runs.
    """
    refresh = False
    if request.method == 'POST':
        data = request.get_json(silent=True) or {}
        refresh = bool(data.get('refresh'))
    try:
        # Kilit: eşzamanlı istekler ağır koşuyu tekrarlamaz. İlk istek koşar,
        # ikincisi bekler ve kilidi aldığında önbellekten anında döner.
        with _CORRELATION_LOCK:
            body = _correlation_report_body(refresh=refresh)
    except Exception as exc:
        traceback.print_exc()
        return jsonify({'status': 'error', 'error': str(exc)}), 500
    return jsonify(body)


if __name__ == '__main__':
    # Gerçek giriş noktası hrma/run.py (waitress, 8080); bu blok yalnız
    # geliştirme içindir. debug VARSAYILAN OLARAK KAPALIDIR: Flask debug modu
    # Werkzeug'un interaktif hata ayıklayıcısını açar ve localhost'ta bile
    # rastgele kod çalıştırılmasına izin verebilir (2026-07-24 denetim bulgusu).
    # Açıkça istemek için HRMA_DEBUG=1 ortam değişkeni kullanılır.
    debug = os.environ.get('HRMA_DEBUG', '') in ('1', 'true', 'True')
    print("Starting Motor Analysis on port 8080..." + (" [debug]" if debug else ""))
    # V3 SG-2 / SG-02: geliştirme yolu da köken kapısına portunu bildirir.
    _dev_port = _origin_gate.register_self_port(app, 8080)
    app.run(debug=debug, port=_dev_port, host='127.0.0.1')